INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(173790, 'ض', '<span class=\"hlight\">ض .</span> (حرف ) نشانه ٔ حرف پانزدهم است از الفبای عرب و نام آن ضاد است و در حساب جُمّل آن را به هشتصد دارند و در حساب ترتیبی عربی نماینده ٔ عدد پانزده و در فارسی هجده است و آن یکی از دو حرف مختص به عرب است، یعنی «ض » و «ظ»، و در فارسی این حرف نباشد و آن از حروف هفتگانه ٔ مستعلیة و شجریّة و مصمتة و روادف و مجهورة و مُطبقة و شمسیة و ناریّة و مرفوعة است . و در عربی بدل ص آید مانند: تیضیض، تیصیص . ومض، ومص . و همچنین آن را بدل ث آرند: تحاض، تحاث . اَضر، اثَر. حضیضی، حثیثی . حض، حث . و نیز به ظ بدل شود چون : بهض، بهظ. و هم به لام، چون : جضد، جلد. هم به شین، چون : تحریض، تحریش . و این حرف منحصر بزبان عرب باشد، و ناطق بالضاد بمعنی عرب است چنانکه در حدیث آمده است که : اَنا افصح ُ من نَطق بالضاد، ای العرب . و در مخرج این حرف اختلافات کثیره است . احمدبن مطرف بن اسحاق مصری لغوی را در تمیز مخرج «ض » از «ظ» رسالتی است . و از ابی عمروبن العلاء آرند که گفته است مخرج «ض » و «ظ» یکی باشد و شیخ بهائی را همین عقیده است و این اختلاف دلیل کند که مخرج این دو حرف بسی بیکدیگر نزدیکست . رجوع به روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٦٧</span> شود.<br /></font></div>'),
(173791, 'ضاب', '<span class=\"hlight\">ضاب .</span> (ع اِ) درختی تلخ مثل حنظل و زقّوم . (آنندراج ) (غیاث اللغات ).<br /></font></div>'),
(173792, 'ضابث', '<span class=\"hlight\">ضابث .</span> <font color=\"DarkGreen\"><b>[ب ِ ]</font></b> (ع ص ) نعت فاعلی از ضَبث . رجوع به ضَبث شود.<br /></font></div>'),
(173793, 'ضابح', '<span class=\"hlight\">ضابح .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص ) اسب بابانگ . ج، ضوابح . (منتهی الارب ).<br /></font></div>'),
(173794, 'ضابط', '<span class=\"hlight\">ضابط.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص، اِ) فراهم آورنده . نگاهدارنده . نگاهدارنده ٔ چیزی . آنکه ضبط مدینه و سیاست آن را از طرف سلطان بس باشد. شِحنه <span class=\"hlight\">:</span> گرد عالم گشتن چه سود، پادشاه ضابط باید. (تاریخ بیهقی ). پادشاه ضابط باید، چون ملکی و بقعتی بگیرد و آن را ضبط نتواند کرد و زود دست بمملکت دیگر یازد... (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٩٠</span>). ما را خداوندی گماشت عادل و مهربان و ضابط. (تاریخ بیهقی ). <BR><font color=\"Blue\">◄</font> مُبرّ: انّه لمُبِرّ بذلک ؛ ای ضابط له . <BR><font color=\"Blue\">◄</font> رجل ضابط؛ مرد هشیار و توانا و سخت . <BR><font color=\"Blue\">◄</font> شتر قوی سخت . <BR><font color=\"Blue\">◄</font> شیر بیشه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> در اصطلاح درایة، متقن مثبت . ج، ضابطون، ضُبّاط، ضوابط.<br /></font></div>'),
(173795, 'ضابع', '<span class=\"hlight\">ضابع.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص ) نعت فاعلی از ضبع: ناقة ضابع؛ شتر بازویازنده در رفتن . <BR><font color=\"Blue\">◄</font> فَرس ضابع؛ اسب تیزرفتار یا بسیاررو یا گردن پیچان یک جانب رونده . (منتهی الارب ).<br /></font></div>'),
(173796, 'ضابن', '<span class=\"hlight\">ضابن .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) بنوضابن . قبیله ای است . (منتهی الارب ).<br /></font></div>'),
(173797, 'ضابوک', '<span class=\"hlight\">ضابوک .</span> (ع اِ) آنکه در خواب چنان نماید که مردم را فروگرفته است . (مهذب الاسماء) .<br /></font></div>'),
(173798, 'ضابی', '<span class=\"hlight\">ضابی .</span> (ع اِ) خاکستر نرم، یا عام است . (منتهی الارب ). خاکستر. (مهذب الاسماء). خاکستر گرم، یا عام است . (آنندراج ). خُلواره . و ظاهراً خاکستر نرم در منتهی الارب غلط کتابت است .<br /></font></div>'),
(173799, 'ضابی', '<span class=\"hlight\">ضابی .</span> (اِخ ) ابن حارث برجمی . شاعری است .<br /></font></div>'),
(173800, 'ضابی', '<span class=\"hlight\">ضابی ٔ.</span> <font color=\"DarkGreen\"><b>[ ب ِءْ ]</font></b> (ع اِ) خاکستر. رجوع به ضابی شود.<br /></font></div>'),
(173801, 'ضابی', '<span class=\"hlight\">ضابی ٔ.</span> <font color=\"DarkGreen\"><b>[ ب ِءْ ]</font></b> (اِخ ) رودباری است که از حرّة بدیار بنی ذبیان درآید. (معجم البلدان ).<br /></font></div>'),
(173802, 'ضاج', '<span class=\"hlight\">ضاج .</span> <font color=\"DarkGreen\"><b>[ ضاج ج ]</font></b> (ع ص ) خروشنده و کسی که آواز بلند کند، و فی الحدیث : عبروا ضاجین ؛ ای رافعین اصواتهم بالتلبیة. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (مص ) بانگ کردن . <BR><font color=\"Blue\">◄</font> دلتنگی نمودن . (زوزنی ).<br /></font></div>'),
(173803, 'ضاجر', '<span class=\"hlight\">ضاجر.</span> <font color=\"DarkGreen\"><b>[ ج ِ ]</font></b> (ع ص ) دلتنگ . بی آرام از غم . مضطرب . (غیاث ) (آنندراج ).<br /></font></div>'),
(173804, 'ضاجع', '<span class=\"hlight\">ضاجع.</span> <font color=\"DarkGreen\"><b>[ ج ِ ]</font></b> (اِخ ) رودباری است در پائین حره ٔ بنی سلیم . (منتهی الارب ) (معجم البلدان ). <BR><font color=\"Blue\">◄</font> موضعی است . (منتهی الارب ).<br /></font></div>'),
(173805, 'ضاجع', '<span class=\"hlight\">ضاجع.</span> <font color=\"DarkGreen\"><b>[ ج ِ ]</font></b> (ع ص، اِ) جای خم وادی . ج، ضواجع. <BR><font color=\"Blue\">◄</font> گول . (منتهی الارب ). نادان . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> ستاره ٔ مایل بغروب . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> مرد بر پهلو خوابیده . <BR><font color=\"Blue\">◄</font> کاهل بسیار خسبنده و ملازم خانه و مقیم در آن بجهت عجز یا بزرگی . (منتهی الارب ). ج، ضواجع.<br /></font></div>'),
(173806, 'ضاحة', '<span class=\"hlight\">ضاحة.</span> <font color=\"DarkGreen\"><b>[ ح َ ]</font></b> (ع اِ) بینائی یا چشم . (منتهی الارب ).<br /></font></div>'),
(173807, 'ضاحک', '<span class=\"hlight\">ضاحک .</span> <font color=\"DarkGreen\"><b>[ ح ِ ]</font></b> (اِخ ) آبی است در بطن السّر، بسرزمین بلقین شام . (معجم البلدان ).<br /></font></div>'),
(173808, 'ضاحک', '<span class=\"hlight\">ضاحک .</span> <font color=\"DarkGreen\"><b>[ ح ِ ]</font></b> (اِخ ) (برقه ٔ...) جائیست به دیار بنی تمیم . (منتهی الارب ).<br /></font></div>'),
(173809, 'ضاحک', '<span class=\"hlight\">ضاحک .</span> <font color=\"DarkGreen\"><b>[ ح ِ ]</font></b> (اِخ ) دو کوهست در پائین فرش . ابن السکیت گوید ضاحک و ضویحک دو کوهند و میان آن دو رودباری است بنام یین . (معجم البلدان ).<br /></font></div>'),
(173810, 'ضاحک', '<span class=\"hlight\">ضاحک .</span> <font color=\"DarkGreen\"><b>[ ح ِ ]</font></b> (اِخ ) رودباری است در یمامة. (معجم البلدان ).<br /></font></div>'),
(173811, 'ضاحک', '<span class=\"hlight\">ضاحک .</span> <font color=\"DarkGreen\"><b>[ ح ِ ]</font></b> (ع ص ) خندان . (دهار). خندنده . (منتهی الارب ). مرد بسیارخند. (منتهی الارب ). خنده کننده . <BR><font color=\"Blue\">◄</font> رأی ضاحک ؛ ظاهر. غیرملتبس . <BR><font color=\"Blue\">◄</font> سنگ درخشنده . (مهذب الاسماء). سنگ نیک سپید نمایان در کوه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ابر که سایه افکند. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> ابر بابرق . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> روضة ضاحک ؛ موضعی است در صمان . (منتهی الارب ).<br /></font></div>'),
(173812, 'ضاحی', '<span class=\"hlight\">ضاحی .</span> (ع ص ) پیدا. گشاده : مکان ضاح ؛ جای ظاهر و بارز. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> برآمده (روز).<br /></font></div>'),
(173813, 'ضاحی', '<span class=\"hlight\">ضاحی .</span> (اِخ ) رودباری است هذیل را. (معجم البلدان ).<br /></font></div>'),
(173814, 'ضاحی', '<span class=\"hlight\">ضاحی .</span> (اِخ )ریگزاری است در جانب سَلمی غربی و در آن آبی است بنام محرَمة و آب دیگری بنام اَثیب . (معجم البلدان ).<br /></font></div>'),
(173815, 'ضاحیة', '<span class=\"hlight\">ضاحیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص، اِ) تأنیث ضاحی . کرانه ٔ چیز: ضاحیة کل شی ٔ؛ کرانه ٔ ظاهر هر چیزی . (منتهی الارب ). ج، ضواحی . <BR><font color=\"Blue\">◄</font> آشکار. یقال : فَعلَه ضاحیة؛ ای علانیة. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ضاحیةالمال ؛ اشتری که بوقت چاشت آب خورد. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ضاحیة البصرة؛ خلاف باطنه ٔ آن است . <BR><font color=\"Blue\">◄</font> از شهر آن سوی که صحرا بود. <BR><font color=\"Blue\">◄</font> نامیست آسمان را. (مهذب الاسماء).<br /></font></div>'),
(173816, 'ضاخیة', '<span class=\"hlight\">ضاخیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع اِ) بلا و سختی . (منتهی الارب ).<br /></font></div>'),
(173817, 'ضاد', '<span class=\"hlight\">ضاد.</span> (ع اِ) نام حرف پانزدهم از حروف تهجی عرب است . رجوع به «ض » شود. <BR><font color=\"Blue\">◄</font> هدهد در آن وقت که بانگ کند. (مهذب الاسماء). هدهد وقتی که سر خود را بالا کند و فریاد زند. هدهد. (دهار).<br /></font></div>'),
(173818, 'ضادشوربانان', '<span class=\"hlight\">ضادشوربانان .</span> (اِخ ) ناحیتی از دشت اورد. (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">١٦٤</span>).<br /></font></div>'),
(173819, 'ضادی', '<span class=\"hlight\">ضادی .</span> (ع ص، اِ) خشمناک . ج، ضُداة. <BR><font color=\"Blue\">◄</font> سخن زشت که بخشم آورد. ج، ضوادی . <BR><font color=\"Blue\">◄</font> آنچه تعلل و بهانه کنندبدان و هیچ فعل محقق نشود برای وی . (منتهی الارب ).<br /></font></div>'),
(173820, 'ضار', '<span class=\"hlight\">ضار.</span> <font color=\"DarkGreen\"><b>[ ضارر ]</font></b>(ع ص ) زیانکار. ضرررساننده . (غیاث ) (آنندراج ). زیان دهنده . (مهذب الاسماء). زیان آور. مُضر. پرزیان . <BR><font color=\"Blue\">◄</font> نامی از نامهای خدای تعالی . (مهذب الاسماء).<br /></font></div>'),
(173821, 'ضارب', '<span class=\"hlight\">ضارب .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (ع ص، اِ)زننده . <BR><font color=\"Blue\">◄</font> زننده ٔ تیر قداح . <BR><font color=\"Blue\">◄</font> امین تیر قمار. <BR><font color=\"Blue\">◄</font> رونده . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> لیل ضارب ؛ شب سخت تاریک . (دهار). شب که تاریکی آن همه ٔ اطراف را پوشد. <BR><font color=\"Blue\">◄</font> ناقه ٔ لگدزننده وقت دوشیدن . <BR><font color=\"Blue\">◄</font> شتر ماده که دم را برداشته بر شرم خود زنان رود. ضاربة مثله . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ضارب السلم ؛ و هو شجر مجتمع من السلم و بالیمامة یسمی ضارب . (معجم البلدان ). <BR><font color=\"Blue\">◄</font> مرغ طلبکار رزق . <BR><font color=\"Blue\">◄</font> جای پست هموار درختناک . <BR><font color=\"Blue\">◄</font> پاره ای از زمین درشت دراز در زمین نرم . (منتهی الارب ). زمین فراخ در وادی . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> آب راهه و رحبةمانندی در وادی .ج، ضوارب . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> زننده به رنگی از رنگها. مائل به رنگی : اجوده الضارب الی البیاض .(ابن البیطار)؛ نیکوترین آن است که به سپیدی زند.<br /></font></div>'),
(173822, 'ضاربة', '<span class=\"hlight\">ضاربة.</span> <font color=\"DarkGreen\"><b>[ رِ ب َ ]</font></b> (ع ص ) تأنیث ضارب . <BR><font color=\"Blue\">◄</font> شب تاریک . <BR><font color=\"Blue\">◄</font> آن اشتر که لگد زند دوشنده را. (مهذب الاسماء).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عروق ضاربة</span> ؛ رگها که نبضان دارد. و رجوع به ضارب شود.<br /></font></div>'),
(173823, 'ضارج', '<span class=\"hlight\">ضارج .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) جایگاهی است بین مدینه و یمن . (معجم البلدان ).<br /></font></div>'),
(173824, 'ضارج', '<span class=\"hlight\">ضارج .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) آبی و نخلی که از پیش ازآن ِ بنی سعدبن زید مناة بود و سپس به تصرف رباب و بقولی بتصرف بنی الصیداء از بنی اسد درآمده است . (معجم البلدان ). و رجوع به عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٣</span> و <span class=\"hlight\" dir=\"rtl\">١٤٤</span> شود.<br /></font></div>'),
(173825, 'ضارح', '<span class=\"hlight\">ضارح .</span> <font color=\"DarkGreen\"><b>[ رِ]</font></b> (ع ص، اِ) ضریح ساز. <BR><font color=\"Blue\">◄</font> گورکن . قبرکن .<br /></font></div>'),
(173826, 'ضارع', '<span class=\"hlight\">ضارع .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (ع ص ) فروتن . <BR><font color=\"Blue\">◄</font> خوار. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> رام . <BR><font color=\"Blue\">◄</font> ضعیف . (منتهی الارب ). نزار. (دهار) (منتهی الارب ) (منتخب اللغات ). لاغرجسم . (منتهی الارب ). سخت لاغر. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> ریزه از هرچیزی . <BR><font color=\"Blue\">◄</font> خردسال ناتوان . (منتهی الارب ).<br /></font></div>'),
(173827, 'ضارور', '<span class=\"hlight\">ضارور.</span> (ع اِ) نیاز. حاجت . <BR><font color=\"Blue\">◄</font> تنگی . <BR><font color=\"Blue\">◄</font> (ص ) تنگ . (منتهی الارب ).<br /></font></div>'),
(173828, 'ضاری', '<span class=\"hlight\">ضاری .</span> (ع ص ) در پی صید دونده (سگ ومانند آن ). سگ بچه ٔ دوان . (منتهی الارب ). سگ شکاری . (مهذب الاسماء) <span class=\"hlight\">:</span> هنگام کار در غلبه و اقتحام سباع ضاری اندر شکار. (جهانگشای جوینی ). ج، ضواری : کلب ٌ ضار؛ سگ حریص بشکار و سگ در پی صید رونده . <BR><font color=\"Blue\">◄</font> خون روان . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> سقاءٌ ضار باللبن ؛ خیک نیکوکننده ٔ شیر. <BR><font color=\"Blue\">◄</font> عرق ٌ ضار؛ رگ که خون آن منقطع نشود. (منتهی الارب ).<br /></font></div>'),
(173829, 'ضاریة', '<span class=\"hlight\">ضاریة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص ) تأنیث ضاری .<br /></font></div>'),
(173830, 'ضاس', '<span class=\"hlight\">ضاس .</span> (اِخ ) جایگاهی است بین مدینه و ینبع. (معجم البلدان ).<br /></font></div>'),
(173831, 'ضاطر', '<span class=\"hlight\">ضاطر.</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (اِخ ) ابن حبشیّه بن سلول خزاعی، از قحطان . جدی جاهلی است و قرةبن ایاس شاعر از نسل اوست . (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٣٧</span>).<br /></font></div>'),
(173832, 'ضاعل', '<span class=\"hlight\">ضاعل .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) شتر نر توانا. (منتهی الارب ).<br /></font></div>'),
(173833, 'ضاغب', '<span class=\"hlight\">ضاغب .</span> <font color=\"DarkGreen\"><b>[ غ ِ ]</font></b> (ع ص، اِ) ضاغث . شخصی که جهت ترسانیدن کسی در پنهان آوازی مهیب و مخوف برزند تا شنونده خائف و بیمناک گردد. (منتهی الارب ).<br /></font></div>'),
(173834, 'ضاغث', '<span class=\"hlight\">ضاغث .</span> <font color=\"DarkGreen\"><b>[ غ ِ ]</font></b> (ع ص، اِ) ضاغب . آنکه پنهان شود در پوششی و جز آن و به آواز مهیب ترساند کودکان و مانند آنرا. (منتهی الارب ). لولو. کخ . یک سردوگوش . لولوخُرخره . لولوخُرناس .<br /></font></div>'),
(173835, 'ضاغط', '<span class=\"hlight\">ضاغط.</span> <font color=\"DarkGreen\"><b>[ غ ِ ]</font></b> (ع ص، اِ) نگاهبان و امین بر چیزی . (منتهی الارب ). مشرف . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> گشادگی بغل شتر و بسیاری گوشت آن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آنچه انگور بدان بیفشارند. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> افشرنده . فشارنده . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> نام دردی است که صاحبش پندارد که آن عضو را می افشرند. (غیاث ) (آنندراج ). یکی از اوجاع خمسةعشر که دارای اسمند. شیخ الرئیس در قانون در «الاوجاع التی لها اسماء» گوید: سببه مادة تضیق علی العضو المکان او ریح تکتنفه فیکون کأنه مقبوض علیه فینضغط. و یکی از شارحین نصاب الصبیان گوید: دردی است که خداوند آن پندارد که آن عضو دردناک را میفشارند. و صاحب ذخیره ٔ خوارزمشاهی گوید: المی است که گوئی آن موضع را میفشارند. و رجوع به وجع شود. <BR><font color=\"Blue\">◄</font> سوسمار. (منتهی الارب ).<br /></font></div>'),
(173836, 'ضاغن', '<span class=\"hlight\">ضاغن .</span> <font color=\"DarkGreen\"><b>[ غ ِ ]</font></b> (ع ص ) (فرس ...) اسب کاهل . اسبی که تا نزنی نیکو نرود. (منتخب اللغات ) (منتهی الارب ).<br /></font></div>'),
(173837, 'ضاغوط', '<span class=\"hlight\">ضاغوط.</span> (ع اِ) کابوس . (بحر الجواهر). خفتو. حالتی که آدمی خفته پندارد که کسی گلوی وی می فشارد. (غیاث ) (آنندراج ). سکاچه .بختک . نیدلان . نیدل . عبدالجنة. رجوع به کابوس شود.<br /></font></div>'),
(173838, 'ضاف', '<span class=\"hlight\">ضاف .</span> <font color=\"DarkGreen\"><b>[ فِن ْ ]</font></b> (ع ص ) ثوب ٌ ضاف ؛ جامه ٔ کامل و تمام . (منتهی الارب ). ضافی . رجوع به ضافی شود.<br /></font></div>'),
(173839, 'ضافط', '<span class=\"hlight\">ضافط.</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (ع ص ) مسافر سفر دور و دراز. <BR><font color=\"Blue\">◄</font> شتر بارکش . <BR><font color=\"Blue\">◄</font> آنکه متاع را از شهری بشهری برد برای فروختن . (منتهی الارب ).<br /></font></div>'),
(173840, 'ضافی', '<span class=\"hlight\">ضافی .</span> (ع ص ) تمام . و یقال : ضافی الفضل علی قومه . (مهذب الاسماء). فراخ عیش و تمام نعمت . <BR><font color=\"Blue\">◄</font> ثوب ٌ ضاف ؛ جامه ٔ کامل و تمام . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> رجل ٌ ضافی الرأس ؛ مرد بسیارموی . (منتهی الارب ).<br /></font></div>'),
(173841, 'ضافیة', '<span class=\"hlight\">ضافیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص ) تأنیث ضافی . <BR><font color=\"Blue\">◄</font> زن تمام . (مهذب الاسماء) <span class=\"hlight\">:</span> نعمت حق سبحانه و بحمده، در بازمانده ٔ امیر ماضی سایغ و ضافیةاللباس است . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٦٠</span>).<br /></font></div>'),
(173842, 'ضال', '<span class=\"hlight\">ضال .</span> (ع اِ) درخت که از آن کمان کنند. کُنار که از باران آب بخورد. کُنار دشتی یا درخت دیگر. کُنار. درخت کُنار دشتی . (منتخب اللغات ). میوه ای است سرخ چون عناب و آن را بفارسی کُنار خوانند و بعربی ثمرةالسّدر خوانند و در هندوستان بِبْر گویند. (آنندراج ) (برهان ). اسم سدر جبلی است . سدر. (تذکره ٔ انطاکی ). سدر دشتی . نام ثمر سدر است . درختی است در بادیه و ذکرش در اشعار بسیار آمده . (نزهة القلوب ).<br /></font></div>'),
(173843, 'ضال', '<span class=\"hlight\">ضال .</span> (اِخ ) ذات الضال ؛ موضعی است .<br /></font></div>'),
(173844, 'ضال', '<span class=\"hlight\">ضال .</span> <font color=\"DarkGreen\"><b>[ ضال ل ]</font></b> (ع ص ) گمراه . (منتهی الارب ) (مهذب الاسماء) (دهار) (منتخب اللغات ). گمره . غوی . تائه . بیراه . (دهار). بیره . ج، ضالون (مهذب الاسماء)، ضالین <span class=\"hlight\">:</span> <br />بس ز نقش لفظهای مثنوی <br />صورتش ضالست و هادی معنوی .<br /> <font color=\"Red\">مولوی .</font><br />چونکه از میخانه مستی ضال شد<br />تسخر و بازیچه ٔ اطفال شد.<br /> <font color=\"Red\">مولوی .</font><br />وحشتت همچون موکل می کشد<br />که بجوی ای ضال منهاج رشد.<br /> <font color=\"Red\">مولوی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضال ّبن ضال </span> ؛ شتمی است عربان را. (منتهی الارب ). یُقال : ضال ٌ بال ؛ اتباع . (مهذب الاسماء). صاحب کشاف اصطلاحات الفنون آرد: ضال ّ؛ غلامی که راه خانه ٔ مولی گم کرده بی قصد اباق . بخلاف آبق که قصد گریز نیز دارد. کذا فی الجرجانی . در اصطلاح فقهی ضال ّ، انسان یا حیوان گمشده است .<br /></font></div>'),
(173845, 'ضال', '<span class=\"hlight\">ضال .</span> <font color=\"DarkGreen\"><b>[ ضال ل ]</font></b> (اِخ ) ابوعبدالرحمن معویةبن عبدالکریم ضال . وعلت اشتهار او بدین صفت آن است که در طریق مکه راه را گم کرد، نه اینکه در دین گمراه باشد. (سمعانی ).<br /></font></div>'),
(173846, 'ضالة', '<span class=\"hlight\">ضالة.</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (ع اِ) یک بنه ٔ ضال باشد یعنی از کُنار دشتی . <BR><font color=\"Blue\">◄</font> سلاح هرچه باشد یا تیر خاصةً.<br /></font></div>'),
(173847, 'ضالة', '<span class=\"hlight\">ضالة.</span> <font color=\"DarkGreen\"><b>[ ضال ْ ل َ ]</font></b> (ع ص ) شتر که بی شبان و صاحب در جای هلاک باشد. (منتهی الارب ). گمشده (مذکر و مؤنث در وی یکسانست ). (منتهی الارب ) (دهار). گم گشته از حیوان (مذکر و مؤنث ) و جز آن . ضایعه . چیزی گمشده . (منتخب اللغات ). و در شعر بتخفیف نیز آمده است ضرورت را <span class=\"hlight\">:</span> <br />سابع از ثامن ندانم ضاله ام <br />خون همی گرید فلک از ناله ام .<br /> <font color=\"Red\">مولوی .</font><br />حکمت قرآن چو ضاله ٔمؤمنست <br />هر کسی در ضاله ٔ خود موقنست .<br /> <font color=\"Red\">مولوی .</font><br />الحکمة ضالة مؤمن (حدیث ).<br /></font></div>'),
(173848, 'ضالع', '<span class=\"hlight\">ضالع.</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص ) ستمکار. جورکننده . <BR><font color=\"Blue\">◄</font> کژ که نه از خلقت باشد. (منتهی الارب ). میل کننده . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> شتر هفت ساله .<br /></font></div>'),
(173849, 'ضالین', '<span class=\"hlight\">ضالین .</span> <font color=\"DarkGreen\"><b>[ ضال ْ لی ]</font></b> (ع ص، اِ) ج ِ ضال ّ.<br /></font></div>'),
(173850, 'ضامر', '<span class=\"hlight\">ضامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص ) باریک میان . (مهذب الاسماء). باریک اندام . جمل ٌ ضامر؛ شتر باریک اندام لاغر. (منتهی الارب ). اشتر باریک میان . (دهار). <BR><font color=\"Blue\">◄</font> دقیق ِ لطیف .ج، ضوامر. <BR><font color=\"Blue\">◄</font> قضیب ٌ ضامر؛ شرم ِ آب بشده .<br /></font></div>'),
(173851, 'ضامز', '<span class=\"hlight\">ضامز.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص ) رجل ٌ ضامِز؛ مرد خاموش و بازایستاده از چیزی . (منتهی الارب ). خاموش . <BR><font color=\"Blue\">◄</font> آهسته . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بعیرٌ ضامز؛ شتر که دبه از دهان بیرون نیارد. (منتهی الارب ). شتری که شقشقه از دهان بیرون نکند. (منتخب اللغات ).<br /></font></div>'),
(173852, 'ضامل', '<span class=\"hlight\">ضامل .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص ) ضَمیل . خشک . (منتهی الارب ).<br /></font></div>'),
(173853, 'ضامن', '<span class=\"hlight\">ضامن .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص، اِ) پذیرفتار. (دهار). پذرفتار. (منتهی الارب ) (دهار). کفیل . (منتهی الارب ). حَمیل . تاوان دار. (دهار) (مؤیدالفضلا). پایندان . (مهذب الاسماء). ضَمین . ج، ضوامن (منتهی الارب )، ضامنون، ضُمناء. (مهذب الاسماء) <span class=\"hlight\">:</span> دریغ اریارق که اقلیمی ضبط توانستی کردن جز هندوستان و من <font color=\"DarkGreen\"><b>[ خواجه احمد حسن ]</font></b> ضامن وی بودمی . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٢٩</span>).<br />چرخ مرا بنده بود چون ازو<br />ایزد دادار بود ضامنم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ای حجّت زمین خراسان بگوی <br />بر راستی سخن که توئی ضامنش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ای جهان را بمکرمت ضامن <br />وی خرد را براستی داور.<br /> <font color=\"Red\">مسعودسعد.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">ضامن را بدل ضامن گیرند</span> . (جامع التمثیل ).<br /> <span class=\"hlight\">مرده شوی ضامن بهشت و جهنم نیست </span> .<br />تقبیل ؛ ضامن دادن ؛ تقبیل، تقبّل العامل العمل ؛ ضامن داد عامل . (منتهی الارب ). تقبّل ؛ ضامن گرفتن بر کار از کارکن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (در اسلحه ٔ ناریّه ) جائی از تفنگ یا طپانچه و غیره که چون بندند گشاد تفنگ و طپانچه ممکن نباشد. <BR><font color=\"Blue\">◄</font> ناقه ٔ باردار. ج، ضوامن . (منتهی الارب ).<br /></font></div>'),
(173854, 'ضامن آهو', '<span class=\"hlight\">ضامن آهو.</span> <font color=\"DarkGreen\"><b>[ م ِ ن ِ ]</font></b> (اِخ ) نزد عوام لقب حضرت امام رضا (ع ). ضمانت از آهو منسوب به علی بن الحسین علیهماالسلام نیز هست . (حبیب السیر چ تهران ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٩</span>).<br /></font></div>'),
(173855, 'ضامن تن', '<span class=\"hlight\">ضامن تن .</span> <font color=\"DarkGreen\"><b>[ م ِ ن ِ ت َ ]</font></b> (ترکیب اضافی، اِ مرکب ) کفیل . که ضامن شود. که مدیون یا گناهکار را بوقت حاجت بقاضی تحویل کند.<br /></font></div>'),
(173856, 'ضامن جریره', '<span class=\"hlight\">ضامن جریره .</span> <font color=\"DarkGreen\"><b>[ م ِ ن ِ ج َ ری رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (ترکیب اضافی، اِ مرکب ) (اصطلاح فقه ). رجوع به ضمان جریره شود.<br /></font></div>'),
(173857, 'ضامن درک', '<span class=\"hlight\">ضامن درک .</span> <font color=\"DarkGreen\"><b>[ م ِ ن ِ دَ رَ ]</font></b> (ترکیب اضافی، اِ مرکب ) رجوع به ضمان درک شود.<br /></font></div>'),
(173858, 'ضامنة', '<span class=\"hlight\">ضامنة.</span> <font color=\"DarkGreen\"><b>[ م ِ ن َ ]</font></b> (ع ص، اِ) تأنیث ضامن . <BR><font color=\"Blue\">◄</font> خرمابن که در شهر یا قریه یا داخل حصار شهر باشد، و منه الحدیث : انّه صلی اﷲ علیه و سلّم کتب ان لنا الضاحیة من البعل و لکم الضامنة من النخل (و الضاحیة هی الظاهرة التی فی البر من النخیل و البعل الذی یشرب بعروقه من غیر سقی ). (منتهی الارب ).<br /></font></div>'),
(173859, 'ضان', '<span class=\"hlight\">ضان .</span> (اِخ ) کوهی است و گویا از کوههای دَوس باشد چه در حدیث آمده که ابوهریره از رأس ضان فروافتاد. (معجم البلدان ).<br /></font></div>'),
(173860, 'ضانة', '<span class=\"hlight\">ضانة.</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (ع اِ) ضأنة. حلقه که در بینی شتر اندازند. (منتهی الارب ).<br /></font></div>'),
(173861, 'ضانی', '<span class=\"hlight\">ضانی ٔ.</span> <font color=\"DarkGreen\"><b>[ ن ِءْ ]</font></b> (ع ص ) زن بسیارفرزند. ضانئة مثله . (منتهی الارب ).<br /></font></div>'),
(173862, 'ضاهر', '<span class=\"hlight\">ضاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع اِ) سر کوه . (منتهی الارب ).<br /></font></div>'),
(173863, 'ضاهس', '<span class=\"hlight\">ضاهس .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع ص ) کسی که بگزد چیزی را با دندان پیشین . در نفرین گویند: لااطعمه اﷲ الا ضاهساً و لاسقاه ُ الاّ فارساً؛ یعنی بخوراند خدای او را اندک از نبات که بمقدم دهان خائیده شود و بنوشاند او را آب خالص بی آمیغ شیر یعنی شیر میسر نشود او را. (منتهی الارب ).<br /></font></div>'),
(173864, 'ضاهلة', '<span class=\"hlight\">ضاهلة.</span> <font color=\"DarkGreen\"><b>[ هَِ ل َ ]</font></b> (ع ص ) عین ٌ ضاهلة؛ چشمه ٔ کم آب . (منتهی الارب ).<br /></font></div>'),
(173865, 'ضاهی', '<span class=\"hlight\">ضاهی .</span> (ع ص ) شبیه . مانند.<br /></font></div>'),
(173866, 'ضاوی', '<span class=\"hlight\">ضاوی .</span> <font color=\"DarkGreen\"><b>[ وی ی ]</font></b> (ع ص ) نزار. لاغر. نحیف . باریک اندام . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کودک نارسیده و نحیف . (مهذب الاسماء) (منتهی الارب ).<br /></font></div>'),
(173867, 'ضاوی', '<span class=\"hlight\">ضاوی .</span> (ع ص ) مرد درآینده در شب . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِخ ) نام اسبی است .<br /></font></div>'),
(173868, 'ضاویة', '<span class=\"hlight\">ضاویة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص ) تأنیث ضاوی . (منتهی الارب ).<br /></font></div>'),
(173869, 'ضایر', '<span class=\"hlight\">ضایر.</span> <font color=\"DarkGreen\"><b>[ ی ِ]</font></b> (ع ص ) (از «ض ی ر») ضائر. زیان رساننده <span class=\"hlight\">:</span> <br />دولت ضایر بگاه صلح تو نافع شود<br />دولت نافع بگاه خشم تو ضایر شود.<br /><font color=\"Red\">منوچهری .</font><br /></font></div>'),
(173870, 'ضایع', '<span class=\"hlight\">ضایع.</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِخ ) لقب شاعری است از بنی ضبعةبن قیس بنام عمروبن قمئة بن ذریح بن سعدبن مالک بن ضبیعةبن قیس بن ثعلبة الشاعر. وی با امروءالقیس به بلاد روم رفت و بدانجا درگذشت، و از این روی او را ضایع گفتند که در سرزمینی غیر وطن خود بمرده است . سمعانی گوید: و هو اول من عمل فی الجبال شعرا. (انساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٣٥٩</span>).<br /></font></div>'),
(173871, 'ضایع', '<span class=\"hlight\">ضایع.</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِخ ) عثمان بن بالغ الضایع. وی از عمروبن مرزوق و از وی محمدبن بکربن داسة البصری روایت کند. (سمعانی ).<br /></font></div>'),
(173872, 'ضایع', '<span class=\"hlight\">ضایع.</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) تلف . تباه . (دهار) <span class=\"hlight\">:</span> <br />ایزد امروز همه کار برای تو کند<br />همه عالم بمراد و بهوای تو کند<br />از لَطَف هرچه کند با تو سزای تو کند<br />زآنکه ضایع نکند هرچه بجای تو کند.<br /> <font color=\"Red\">منوچهری (دیوان ص <span class=\"hlight\" dir=\"rtl\">١٩٢</span>).</font><br />خواجه احتیاط وی و مردم وی اینجا و بنواحی بکند تا از دست بنشود و چیزی ضایع نگردد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٣٠</span>). بدرستی که او ضایع نمی گرداند اجر نیکوکاران را. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣١١</span>). آلتونتاش را فرو باید گرفت و این فرصت را ضایع نباید کرد. (تاریخ بیهقی ). تاکنون کارها سخت ناپسندیده رفته است و هر کس بکار خویش مشغول بوده و شغلهای سلطان ضایع. (تاریخ بیهقی <span class=\"hlight\" dir=\"rtl\">١٥٤</span>). هر بنده که جانب ایزد عزّوجل نگاه دارد وی عزّ ذکره و جلت عظمته آن بنده را ضایع بنماند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٥٥</span>).<br />نکندبا سفها مرد سخن ضایع<br />نان جو را که زند زیره ٔ کرمانی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />تا آخر روز بازرگان بضرورت از عهده ٔ مقرر بیرون آمد و متحیر بماند، روزگارضایع. (کلیله و دمنه ). اقوال پسندیده مدروس گشته ...و ضایع گردانیدن احکام خرد طریقتی مشروع . (کلیله و دمنه )... و دین بی ملک ضایع. (کلیله و دمنه ).<br />که ز یزدان آگهیم و طایعیم <br />ما همه بی اتفاقی ضایعیم .<br /> <font color=\"Red\">مولوی (مثنوی ).</font><br />لقمان حکیم اندر آن قافله بود، یکی گفتش از کاروانیان مگر اینان را نصیحتی کنی ... تا طرفی از مال ما دست بدارند که دریغ باشد که چندین نعمت ضایع شود. (گلستان سعدی ).<br />وصیت همین است جان ِ برادر<br />که اوقات ضایع مکن تا توانی .<br /> <font color=\"Red\">سعدی .</font><br />صبا از من بگو یار عبوساً قمطریرا را<br />نمی چسبی به دل ضایع مکن صمغ و کتیرا را.<br /> <font color=\"Red\">؟</font><br /> <BR><font color=\"Blue\">◄</font> فروگذاشته . بی تیمار که پروای آن نکنند <span class=\"hlight\">:</span> <br />دار ملک خویش را ضایع چرا باید گذاشت <br />مر سپاهان را چرا کرده ست بر غزنین گزین .<br /> <font color=\"Red\">فرخی .</font><br /> <BR><font color=\"Blue\">◄</font> بیکار. مهمل . معطل . فرومانده . (دهار) <span class=\"hlight\">:</span> اگر بیهنران خدمت اسلاف را وسیلت سعادت سازند خلل بکارها راه یابدو اهل هنر ضایع مانند. (کلیله و دمنه ). <BR><font color=\"Blue\">◄</font> بی ثمر. بی بر. بیفایده <span class=\"hlight\">:</span> الحق که در آن سعی پیوسته آید و مؤونتی تحمل کرده شود ضایع و بی ثمرت نماند. (کلیله و دمنه ).<br />نباشد ترا ضایع از کردگارت <br />اگر بی کسان را کنی دستیاری .<br /> <font color=\"Red\">کمال اسماعیل .</font><br />فضل و هنر ضایعست تا ننمایند<br />عود بر آتش نهند و مشک بسایند.<br /> <font color=\"Red\">سعدی (گلستان ).</font><br /> <BR><font color=\"Blue\">◄</font> بی نگهبان <span class=\"hlight\">:</span> چون دید که جمع بنماز مشغول شده اند واز رختها دورند و قماشها ضایع است، قصد کرد تا رختی ببرد. (اسرار التوحید ص <span class=\"hlight\" dir=\"rtl\">١٢٤</span>). <BR><font color=\"Blue\">◄</font> گم . مفقود <span class=\"hlight\">:</span> <br />یک روز شیخ را ازارپای نودوخته بودند و بر آب زده و نمازی کرده و برحبل افکنده تا خشک شود، ازارپای ضایع شد. (اسرارالتوحید ص <span class=\"hlight\" dir=\"rtl\">١٩٧</span>). آن کاغذ زر که بخرقان ضایع شده بود ندید. (اسرارالتوحید ص <span class=\"hlight\" dir=\"rtl\">١٨٨</span>). حسن گفت چیزی داشتم ضایع شده است . (اسرار التوحید ص <span class=\"hlight\" dir=\"rtl\">١٨٨</span>).<br />از آن قبل را کردند هار مروارید<br />که دُرّ ضایع بودی اگر نبودی هار.<br /> <font color=\"Red\">؟ (از حاشیه ٔ فرهنگ اسدی نخجوانی ).</font><br /> <BR><font color=\"Blue\">◄</font> گندیده (مانند تخم مرغ و غیره ). لغ. <BR><font color=\"Blue\">◄</font> هالک . (منتهی الارب ). به بادشده .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضایع شدن </span> ؛ ضَیاع . (دهار). ضلال . (تاج المصادر). گم شدن <span class=\"hlight\">:</span> <br />مسلمانان مرا وقتی دلی بود<br />که با وی گفتمی گر مشکلی بود<br />کنون ضایع شد اندر کوی جانان <br />چه دامنگیر یا رب منزلی بود.<br /> <font color=\"Red\">حافظ.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضایع کردن </span> ؛ تضییع. اضاعة. (تاج المصادر). اِهجال . (منتهی الارب ). گم کردن <span class=\"hlight\">:</span> و از جهت آنکه سلیمان علیه السلام انگشتری ضایع کرد ملک از وی برفت . (نوروزنامه ). بباد دادن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضایع گذاشتن </span> ؛ از دست نهادن . اهمال کردن در...<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضایع گردانیدن </span> ؛ تضییع.<br /></font></div>'),
(173873, 'ضایعات', '<span class=\"hlight\">ضایعات .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع اِ) ج ِ ضایعة.<br /></font></div>'),
(173874, 'ضایق', '<span class=\"hlight\">ضایق .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) تنگ . (منتهی الارب ). کم وسعت . ضائق . ضیّق .<br /></font></div>'),
(173875, 'ضاین', '<span class=\"hlight\">ضاین .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) رجوع به ضائن شود.<br /></font></div>'),
(173876, 'ضب', '<span class=\"hlight\">ضب .</span> <font color=\"DarkGreen\"><b>[ ض َب ب ]</font></b> (ع اِ) ج ِ ضبّه . (منتهی الارب ). رجوع به ضبة شود.<br /></font></div>'),
(173877, 'ضب', '<span class=\"hlight\">ضب .</span> <font color=\"DarkGreen\"><b>[ ض َب ب ]</font></b> (اِخ ) ابن الفرافصةبن عمرو، برادر نائلة. رجوع به عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٧٦</span> شود.<br /></font></div>'),
(173878, 'ضب', '<span class=\"hlight\">ضب .</span> <font color=\"DarkGreen\"><b>[ ض َب ب ]</font></b> (ع اِ) سوسمار. (منتهی الارب ) (دهار). بُرق . بهندی آن را گوگو نامند. (آنندراج ).ج، اَضُب ّ، ضِباب، ضُبّان، و مَضَبّة. صاحب تحفه گوید: بفارسی سوسمار نامند و او حیوانیست کوچکتر از گربه مابین سیاهی و زردی و دنباله ٔ او بسیار کوتاه و درشت و شبیه به ثمر درخت سرو. در سیُم گرم و خشک و گوشت او مقوی باه و سرگین او با سرکه جهت بیاض چشم و کلف و نمش و ضماد شق کرده ٔ او جاذب پیکان و خار و سموم جانوران است و طلای جلد سوخته ٔ او مورث بی حسی عضو است بحدی که اگر قطع کنند متألم نگردد، و مضر محرورین، و مصلحش بُقول بارده است . (تحفه ٔ حکیم مؤمن ). بچه ٔ سوسمار که اول میزاید او را حسل میگویند و بعد از آن غیداق خوانند و بعد از آن مطبّخ و بعد از آن خضرم و چون بتمامی رسد ضَب ّ گویند. صاحب اختیارات گوید: ضَب ّ، عضائه است و عضا نیز گویند و آن نزدیکست به ورل و بپارسی سوسمار خوانند. سرگین وی بر کلف و نمش طلا کنند زایل گرداند و سفیدی که در چشم بود ببرد. (اختیارات بدیعی ). انطاکی گوید: ضب، بین الورل و الحرذون و قیل هو الحرذون و الصحیح انه اکبر حجماً و اشد صفرة قصیرالذنب خشن یشبه جلده جلد البغال و الحمیر بعد الدبغ و المعروفة الآن بالبرغال یکثر بنواحی العراق، و هو حار یابس فی الثالثة اذا شق و وضع علی السموم جذبها و کذا السلی و النصول و بعره اجود من بعر الحرذون فی قلع البیاض و قیل ان جلده اذا احرق و مسح به العضو الذی یراد قطعه لم یحس فیه بالم و اخثاؤه تجلو الکلف عن تجربة و هو یضر المحرورین و یصلحه البقل و الخل . (تذکره ٔ ضریر انطاکی ). و در حدیث است که سوسماری پیغمبر اکرم را بیاوردند و آن حضرت آن را نخورد و حرام نیز نفرمود، بدین جهت ابوحنیفه و اصحاب وی خوردن آن را مکروه دانسته اند و شافعی غیرمکروه شمرده و قول اخیر رایج تر است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">اضل ّ از ضب ّ</span> ؛ گمراه تر از سوسمار، چه او چون از سوراخ بیرون آید کرّت دیگر راه بسوراخ نبرد. و نیز در مثل است : اعق ّ من ضب ّ، و کذا اخدع من ضب، و گویند: لاافعله حتی یحن الضّب فی اثر الابل الصادرة. و کذا: لاافعله حتی یرد الضب لأنه لایشرب ماءً. (منتهی الارب ).<br /><BR><font color=\"Blue\">◄</font> بغض . خشم . کینه . (منتهی الارب ) (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> شکوفه که از کارد بیرون آید. (مهذب الاسماء): ضب نخله ؛ طلع آن است . <BR><font color=\"Blue\">◄</font> رجل خَب ٌّ ضَب ﱡ؛ مرد گربز پرکار. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بیمارئی است در آرنج شتر. <BR><font color=\"Blue\">◄</font> آماس سپل شتر. <BR><font color=\"Blue\">◄</font> آماس سینه ٔ شتر. <BR><font color=\"Blue\">◄</font> بیمارئی در لب که خون رود از وی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بیمارئی که در لب پیدا می گردد و بدان از لب خون روان میشود. (منتخب اللغات ).<br /></font></div>'),
(173879, 'ضب', '<span class=\"hlight\">ضب .</span> <font color=\"DarkGreen\"><b>[ ض َب ب ]</font></b> (ع مص ) خون آوردن لب . (منتهی الارب ). سیلان خون از لثه . روان شدن خون از دهن . خون آمدن لب و سیلان او. (منتهی الارب ).روان شدن آب یا خون یا آب ِ دهان . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> دوشیدن با پنج انگشت، و یا ابهام را بر سرپستان و انگشتان را بر ابهام گذاشته دوشیدن . (منتهی الارب ). به پنج انگشت دوشیدن شیر را. (منتهی الارب ). با تمام کف دوشیدن . (منتخب اللغات ). جمع کردن دو سر پستان در دوشیدن . (منتهی الارب ). دوشیدن شتر. (زوزنی )(تاج المصادر). دوشیدن ناقه . (دهار). <BR><font color=\"Blue\">◄</font> دوسیده شدن به زمین . <BR><font color=\"Blue\">◄</font> بسیار شدن سوسمار در جائی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> رفتن شیر اندک اندک . (تاج المصادر) (زوزنی ). <BR><font color=\"Blue\">◄</font> فراگرفتن چیزی را. (منتهی الارب ). شامل بودن به چیزی . (منتخب اللغات ). به چیزی محتوی شدن . <BR><font color=\"Blue\">◄</font> خاموش شدن .خاموش شدن بر کینه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آکنده و پُرگوشت شدن بَغل . <BR><font color=\"Blue\">◄</font> آماسیدن سپل شتر. <BR><font color=\"Blue\">◄</font> آماسیدن سینه ٔ شتر. (منتهی الارب ).<br /></font></div>'),
(173880, 'ضب', '<span class=\"hlight\">ضب .</span> <font color=\"DarkGreen\"><b>[ ض َب ب ]</font></b> (اِخ ) نام مردی است . (منتهی الارب ).<br /></font></div>'),
(173881, 'ضب', '<span class=\"hlight\">ضب .</span> <font color=\"DarkGreen\"><b>[ ض َب ب ]</font></b> (اِخ ) نام کوهی است که مسجد خیف در پای آن کوهست، و نام دیگر آن صابح است . (معجم البلدان ).<br /></font></div>'),
(173882, 'ضبا', '<span class=\"hlight\">ضبا.</span> <font color=\"DarkGreen\"><b>[ ض َ]</font></b> (ع اِ) درختی است شبیه به بلوط. (مخزن الادویه ).<br /></font></div>'),
(173883, 'ضباب', '<span class=\"hlight\">ضباب .</span> <font color=\"DarkGreen\"><b>[ ض ِ ]</font></b> (ع اِ) ج ِ ضَب ّ و ضبة. (منتهی الارب ). رجوع به ضب ّ و ضبة شود.<br /></font></div>'),
(173884, 'ضباب', '<span class=\"hlight\">ضباب .</span> <font color=\"DarkGreen\"><b>[ ض ِ ]</font></b> (ع اِ) ضباب الباب ؛ آهن مسمار. (منتهی الارب ). آهن جامه . پشیز در.<br /></font></div>'),
(173885, 'ضباب', '<span class=\"hlight\">ضباب .</span> <font color=\"DarkGreen\"><b>[ ض ِ ]</font></b> (اِخ ) (قلعة الَ ...) قلعه ای است <br />به کوفه . (منتهی الارب ).<br /></font></div>'),
(173886, 'ضباب', '<span class=\"hlight\">ضباب .</span> <font color=\"DarkGreen\"><b>[ ض ِ ]</font></b> (اِخ ) نام قبیله ای از عرب، و اشعار این قبیله را ابوسعید سکّری گرد کرده است . (الفهرست ابن الندیم ص <span class=\"hlight\" dir=\"rtl\">٢٢٦</span>). قومی از عرب از اولاد معاویةبن کلاب بن ربیعه، و ضبابی منسوب بدان قبیله است . (منتهی الارب ).<br /></font></div>'),
(173887, 'ضباب', '<span class=\"hlight\">ضباب .</span> <font color=\"DarkGreen\"><b>[ ض ُ ]</font></b> (اِخ ) نام مردی است . (منتهی الارب ).<br /></font></div>'),
(173888, 'ضباب', '<span class=\"hlight\">ضباب .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ) نَزم . (ذخیره ٔ خوارزمشاهی ).میغ نرم و آن بخاری باشدکه در زمستان در هوا پیدا گردد. (منتهی الارب ). نَژم . مِه . پاره میغ. ابرهای تُنُک . (منتخب اللغات ). ابرها که متصل بزمین شود و آن را بپوشاند <span class=\"hlight\">:</span> نوررای روشن او که در دریای ظلمات واقعات ماهیی کردی در شست کسوف حجاب حیرت و ضباب دهشت متواری ماند. (تاریخ جهانگشای جوینی ). هر کجا انوار ولاء حق تجلی کند ظلمات کفر و فسوق مضمحل و متلاشی شود چون ضباب که به ارتفاع آفتاب پایدار نبود. (تاریخ جهانگشای جوینی ).<br /></font></div>'),
(173889, 'ضبابة', '<span class=\"hlight\">ضبابة.</span> <font color=\"DarkGreen\"><b>[ ض َ ب َ ]</font></b> (ع اِ) ضباب . نژم . نزم . (مهذب الاسماء). ابر تنک که چون شبنم روی زمین را پوشد. (منتخب اللغات ).<br /></font></div>'),
(173890, 'ضبابی', '<span class=\"hlight\">ضبابی .</span> <font color=\"DarkGreen\"><b>[ ض ِ ]</font></b> (ص نسبی ) منسوب است به نام جدابی الحسن محمدبن سلیمان بن منصوربن عبداﷲبن محمدبن منصوربن موسی بن سعدبن مالک بن جابربن وهب بن ضباب الازرق . (سمعانی ). <BR><font color=\"Blue\">◄</font> منسوب است به ضباب که قومی است از اولاد معاویةبن کلاب بن ربیعة. (منتهی الارب ).<br /></font></div>'),
(173891, 'ضباث', '<span class=\"hlight\">ضباث .</span> <font color=\"DarkGreen\"><b>[ ض ُ ]</font></b> (ع اِ) پنجه ٔ شیر. (منتهی الارب ). برثن .<br /></font></div>'),
(173892, 'ضباث', '<span class=\"hlight\">ضباث .</span> <font color=\"DarkGreen\"><b>[ ض ُ ]</font></b> (اِخ ) نام پدر زید و منجی و عطیة. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بطنی از جشم .<br /></font></div>'),
(173893, 'ضباث', '<span class=\"hlight\">ضباث .</span> <font color=\"DarkGreen\"><b>[ ض َب ْ با ]</font></b> (ع اِ) شیر بیشه . (منتهی الارب ).<br /></font></div>'),
(173894, 'ضباثم', '<span class=\"hlight\">ضباثم .</span> <font color=\"DarkGreen\"><b>[ ض ُ ث ِ ]</font></b> (ع اِ) شیر بیشه . (منتهی الارب ).<br /></font></div>'),
(173895, 'ضباثی', '<span class=\"hlight\">ضباثی .</span> <font color=\"DarkGreen\"><b>[ ض ُ ]</font></b> (ص نسبی ) منسوب به ضباث که بطنی است از جشم . (سمعانی ).<br /></font></div>'),
(173896, 'ضباثیة', '<span class=\"hlight\">ضباثیة.</span> <font color=\"DarkGreen\"><b>[ ض ُ ثی ی َ ]</font></b> (ع اِ) ذراع فراخ سطبر سخت . (از منتهی الارب ).<br /></font></div>'),
(173897, 'ضباح', '<span class=\"hlight\">ضباح .</span> <font color=\"DarkGreen\"><b>[ ض َب با]</font></b> (اِخ ) ابن محمدبن علی . محدث است . (منتهی الارب ).<br /></font></div>'),
(173898, 'ضباح', '<span class=\"hlight\">ضباح .</span> <font color=\"DarkGreen\"><b>[ ض ُ ]</font></b> (اِخ ) جایگاهی است . (منتهی الارب ).<br /></font></div>'),
(173899, 'ضباح', '<span class=\"hlight\">ضباح .</span> <font color=\"DarkGreen\"><b>[ ض ُ ]</font></b> (ع اِ) بانگ روباه . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> آواز دم اسب، و آن غیر صهیل و غیر حمحمه است . <BR><font color=\"Blue\">◄</font> بانگ بوم . <BR><font color=\"Blue\">◄</font> (اِخ ) نام مردی . (منتهی الارب ).<br /></font></div>'),
(173900, 'ضباح', '<span class=\"hlight\">ضباح .</span> <font color=\"DarkGreen\"><b>[ ض ُ ]</font></b> (ع مص ) ضَبح . (منتهی الارب ). برآوردن و شنوانیدن اسبان آواز خود را در دویدن یا پویه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بانگ کردن روباه . (مهذب الاسماء) (زوزنی ) (تاج المصادر).<br /></font></div>'),
(173901, 'ضباح', '<span class=\"hlight\">ضباح .</span> <font color=\"DarkGreen\"><b>[ ض َب ْ با ]</font></b> (اِخ ) ابن اسماعیل کوفی . محدّث است . (منتهی الارب ).<br /></font></div>'),
(173902, 'ضبار', '<span class=\"hlight\">ضبار.</span> <font color=\"DarkGreen\"><b>[ ض ُب ْ با ]</font></b> (ع اِ) درختی است مانا به درخت بلوط. (منتهی الارب ).<br /></font></div>'),
(173903, 'ضبار', '<span class=\"hlight\">ضبار.</span> <font color=\"DarkGreen\"><b>[ ض ِ <span class=\"hlight\" dir=\"rtl\">/</span> ض ُ ]</font></b> (ع اِ) کتابها (واحد ندارد). (منتهی الارب ).<br /></font></div>'),
(173904, 'ضبار', '<span class=\"hlight\">ضبار.</span> <font color=\"DarkGreen\"><b>[ ض ُ ]</font></b> (اِخ ) نام کوهیست نزدیک حرةالنار. (معجم البلدان ).<br /></font></div>'),
(173905, 'ضبار', '<span class=\"hlight\">ضبار.</span> <font color=\"DarkGreen\"><b>[ ض َب ْ با ]</font></b> (اِخ ) نام سگی است . (منتخب اللغات ).<br /></font></div>'),
(173906, 'ضبارز', '<span class=\"hlight\">ضبارز.</span> <font color=\"DarkGreen\"><b>[ ض ُ رِ ]</font></b> (ع ص ) مرد گرداندام استوارخلقت . (منتهی الارب ).<br /></font></div>'),
(173907, 'ضبارم', '<span class=\"hlight\">ضبارم .</span> <font color=\"DarkGreen\"><b>[ ض ُ رِ ]</font></b> (ع ص، اِ) شیر. شیر بیشه ٔ سخت خلقت . (منتهی الارب ). شیر قوی .(مهذب الاسماء). <BR><font color=\"Blue\">◄</font> مرد توانا و دلاور دشمن کش . (منتهی الارب ). مرد دلیر. (مهذب الاسماء). ضُبارمة، مثله فی الکل، و قیل المیم زائدة. (منتهی الارب ).<br /></font></div>'),
(173908, 'ضبارمة', '<span class=\"hlight\">ضبارمة.</span> <font color=\"DarkGreen\"><b>[ ض ُ رِ م َ ]</font></b> (ع ص، اِ) ضُبارم . رجوع به ضُبارم شود.<br /></font></div>'),
(173909, 'ضبارک', '<span class=\"hlight\">ضبارک .</span> <font color=\"DarkGreen\"><b>[ ض َ رِ ]</font></b> (ع ص، اِ) ج ِ ضُبارِک . (منتهی الارب ). رجوع به ضُبارِک شود.<br /></font></div>'),
(173910, 'ضبارک', '<span class=\"hlight\">ضبارک .</span> <font color=\"DarkGreen\"><b>[ ض ُ رِ ]</font></b> (ع اِ) ضبراک . شیر بیشه . <BR><font color=\"Blue\">◄</font> (ص ) شتر دفزک . <BR><font color=\"Blue\">◄</font> مرد توانا و استوارخلقت و فربه بسیار اهل و عدد. (منتهی الارب ). مرد بزرگ . (مهذب الاسماء). ج، ضَبارک . (منتهی الارب ).<br /></font></div>'),
(173911, 'ضباری', '<span class=\"hlight\">ضباری .</span><font color=\"DarkGreen\"><b>[ ض ِ را ]</font></b> (اِخ ) نام مردی از تمیم . (منتهی الارب ).<br /></font></div>'),
(173912, 'ضباری', '<span class=\"hlight\">ضباری .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (اِخ ) نام مردی است در رباب . (منتهی الارب ).<br /></font></div>'),
(173913, 'ضباری', '<span class=\"hlight\">ضباری .</span> <font color=\"DarkGreen\"><b>[ ض ِ ]</font></b> (ص نسبی ) منسوب به ضبار، بطنی است از تمیم . (سمعانی ).<br /></font></div>'),
(173914, 'ضباضب', '<span class=\"hlight\">ضباضب .</span> <font color=\"DarkGreen\"><b>[ ض ُ ض ِ ]</font></b> (ع ص ) دلیر پلیدزبان : رجل ضُباضب ؛ مردتوانا و قوی کوتاه بالا. پلیدزبان فربه . مرد چالاک توانا. (منتهی الارب ). مرد کوتاه فربه . (مهذب الاسماء).<br /></font></div>'),
(173915, 'ضباط', '<span class=\"hlight\">ضباط.</span> <font color=\"DarkGreen\"><b>[ ض ُب ْ با ]</font></b> (ع ص، اِ) ج ِ ضابط.<br /></font></div>'),
(173916, 'ضباط', '<span class=\"hlight\">ضباط.</span> <font color=\"DarkGreen\"><b>[ ض َب ْ با ]</font></b> (ع ص، اِ) ضبطکننده . <BR><font color=\"Blue\">◄</font> آنکه ضبط اوراق اداره یا محکمه ای کند. بایگان . آرشیویست . <br /></font></div>'),
(173917, 'ضباع', '<span class=\"hlight\">ضباع .</span> <font color=\"DarkGreen\"><b>[ ض ِ ]</font></b> (اِخ ) ستاره های بسیارند اسفل از بنات نعش . (منتهی الارب ). ستارگانی که بر سر و منکبین و عصای صورت بقّار واقع است .<br /></font></div>'),
(173918, 'ضباع', '<span class=\"hlight\">ضباع .</span> <font color=\"DarkGreen\"><b>[ ض ِ ]</font></b> (ع اِ) ج ِ ضَبُع و ضَبْع. (منتهی الارب ) <span class=\"hlight\">:</span> ضباع و سباع از خصب آن مراتع بفراخی رسیده . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٩٤</span>). در مأوای سباع و منزل ضباع در خواب غفلت رفت . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">١٥٩</span>). ضباع با ثعالب مستأنس شده . (جهانگشای جوینی ). <BR><font color=\"Blue\">◄</font> (ص ) ضَبِعة. رجوع به ضَبِعة شود.<br /></font></div>'),
(173919, 'ضباع', '<span class=\"hlight\">ضباع .</span> <font color=\"DarkGreen\"><b>[ ض ِ ]</font></b> (اِخ ) (بطن الَ ...) موضعی است . (منتهی الارب ). وادیی است در بلاد عرب . (معجم البلدان ).<br /></font></div>'),
(173920, 'ضباعة', '<span class=\"hlight\">ضباعة.</span> <font color=\"DarkGreen\"><b>[ ض ُ ع َ ]</font></b> (اِخ ) کوهی است . (منتهی الارب ).<br /></font></div>'),
(173921, 'ضباعة', '<span class=\"hlight\">ضباعة.</span> <font color=\"DarkGreen\"><b>[ ض ُ ع َ ]</font></b> (اِخ ) دختر عمران بن حصین . (منتهی الارب ).<br /></font></div>'),
(173922, 'ضباعة', '<span class=\"hlight\">ضباعة.</span> <font color=\"DarkGreen\"><b>[ ض ُ ع َ ]</font></b> (اِخ ) دختر عامربن قشیر، و آن ضباعه ٔ کبری و از صحابیات است . (منتهی الارب ).<br /></font></div>'),
(173923, 'ضباعة', '<span class=\"hlight\">ضباعة.</span> <font color=\"DarkGreen\"><b>[ ض ُ ع َ ]</font></b> (اِخ ) دختر عامربن قرط. (منتهی الارب ).<br /></font></div>'),
(173924, 'ضباعة', '<span class=\"hlight\">ضباعة.</span> <font color=\"DarkGreen\"><b>[ ض ُ ع َ ]</font></b> (اِخ ) دختر عامربن صعصعه . رسول صلوات اﷲ علیه او را بزنی کرد و نادیده طلاق گفت .<br /></font></div>'),
(173925, 'ضباعة', '<span class=\"hlight\">ضباعة.</span> <font color=\"DarkGreen\"><b>[ ض ُ ع َ ]</font></b> (اِخ ) دختر زبیربن عبدالمطلب بن هاشم، صحابیه است . (منتهی الارب ). وی از هُجناء است، و هَجین نزد عرب کسی است که پدر وی عرب و مادرش عجمی باشد. صاحب عقدالفرید گوید: و مما احتجت به الهجناء ان النبی صلی اﷲعلیه و سلم زَوَّج َ ضُباعة بنت الزبیربن عبدالمطلب من المقدادبن الاسود. (عقد الفرید ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٣</span> و <span class=\"hlight\" dir=\"rtl\">١٤٤</span>).<br /></font></div>'),
(173926, 'ضباعة', '<span class=\"hlight\">ضباعة.</span> <font color=\"DarkGreen\"><b>[ ض ُ ع َ ]</font></b> (اِخ ) دختر زفربن حارث که اشاره کرد پدر را به رها کردن بند قطامی و منت نهادن بر سر وی که اسیر بود و پس رها کرد او را و بخشید به وی صد ناقه پس گفت قطامی :<br />قفی قبل التفرق یا ضباعاً<br />و لایک موقف منک الوداعا.<br />(اراد یا ضباعة فرخم، ای قفی و دعینا ان عزمت علی فرقتنا فلا کان منک الوداع لنا فی موقف ). (منتهی الارب ).<br /></font></div>'),
(173927, 'ضباعی', '<span class=\"hlight\">ضباعی .</span> <font color=\"DarkGreen\"><b>[ ض َ عا]</font></b> (ع ص ) ضِبعة. رجوع به ضِبعة شود. (منتهی الارب ).<br /></font></div>'),
(173928, 'ضباعین', '<span class=\"hlight\">ضباعین .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ) ج ِ ضِبعان . (منتهی الارب ).<br /></font></div>'),
(173929, 'ضباغط', '<span class=\"hlight\">ضباغط.</span> <font color=\"DarkGreen\"><b>[ ض َ غ ِ ]</font></b> (ع اِ) ج ِ ضَبَغْطی . (منتهی الارب ).<br /></font></div>'),
(173930, 'ضبان', '<span class=\"hlight\">ضبان .</span> <font color=\"DarkGreen\"><b>[ ض ُب ْ با ]</font></b> (ع اِ) ج ِ ضَب . (منتهی الارب ).<br /></font></div>'),
(173931, 'ضببة', '<span class=\"hlight\">ضببة.</span> <font color=\"DarkGreen\"><b>[ ض َ ب ِ ب َ ]</font></b> (ع ص ) ارض ضَبِبة؛ زمین سوسمارناک . (منتهی الارب ). زمین بسیارسوسمار. (مهذب الاسماء).<br /></font></div>'),
(173932, 'ضبة', '<span class=\"hlight\">ضبة.</span> <font color=\"DarkGreen\"><b>[ ض َب ْ ب َ ]</font></b> (ع اِ) سوسمار ماده یا یک سوسمار. (منتهی الارب ). ضبة المکون ؛ سوسمار که خایه بسیار دارد در شکم . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> شکوفه ٔ خرما که گل نکرده باشد. <BR><font color=\"Blue\">◄</font> پوست سوسمار که برای روغن پیراسته باشند. <BR><font color=\"Blue\">◄</font> آهنی است پهن که بدان در را بند کنند. ج، ضَب ّ، ضِباب . <BR><font color=\"Blue\">◄</font> (اِخ ) نام مردی است . <BR><font color=\"Blue\">◄</font> (اِخ ) نام ماده شتر احبش بن قلع عنبری . (منتهی الارب ).<br /></font></div>'),
(173933, 'ضبة', '<span class=\"hlight\">ضبة.</span> <font color=\"DarkGreen\"><b>[ ض َب ْ ب َ ]</font></b> (اِخ ) دهی است به تهامة. (منتهی الارب ). نام زمینی است و گویند دیهی است بتهامه بکنار دریا بدان سوی شام، و برابر آن ده دیگری است بنام بدا و آن ده یعقوب پیغمبر است . (معجم البلدان ).<br /></font></div>'),
(173934, 'ضبة', '<span class=\"hlight\">ضبة.</span> <font color=\"DarkGreen\"><b>[ ض َب ْ ب َ ]</font></b>(اِخ ) ابن اد، عم تمیم بن مرّة است . (منتهی الارب ).<br /></font></div>'),
(173935, 'ضبة', '<span class=\"hlight\">ضبة.</span> <font color=\"DarkGreen\"><b>[ ض َب ْ ب َ ]</font></b> (اِخ ) ابن ادّبن طابخةبن الیاس بن مضر. جدی جاهلی، سعد و سعید از پسران ویند. مسکن ایشان در شمال نجد بود و در دوران اسلامی بعراق منتقل شدند و در جزیره (جزیره ٔ فراتی ) سکونت گزیدند. گویند ضبة نخستین کسی است که گفت : «الحدیث ذوشجون » و «سبق السیف العذل »، و درباره ٔ مثل نخستین وی را حکایتی است . رجوع بمجمع الامثال میدانی والسبائک ص <span class=\"hlight\" dir=\"rtl\">٢٣</span> شود.<br /></font></div>'),
(173936, 'ضبة', '<span class=\"hlight\">ضبة.</span> <font color=\"DarkGreen\"><b>[ ض َب ْ ب َ ]</font></b> (ع اِ) سوسمار ماده . (منتهی الارب ) (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> آهن در. حلقه ٔ در. بَش . پَش . آهن جامه . آهن که بر در زنند. ج، ضباب . (مهذب الاسماء).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(173937, 'ضبث', '<span class=\"hlight\">ضبث .</span> <font color=\"DarkGreen\"><b>[ ض َ]</font></b> (ع مص ) سخت به پنجه گرفتن چیزی را. سخت گرفتن . (تاج المصادر) (زوزنی ). بکف و پنجه گرفتن چیزی . (منتخب اللغات ). به پنجه گرفتن چیزی . <BR><font color=\"Blue\">◄</font> زدن کسی را. <BR><font color=\"Blue\">◄</font> بسودن ناقه و جز آن را تا فربهی ولاغری آن معلوم شود. پرماسیدن ناقه . (منتهی الارب ).<br /></font></div>'),
(173938, 'ضبث', '<span class=\"hlight\">ضبث .</span> <font color=\"DarkGreen\"><b>[ ض َ ب ِ ]</font></b> (ع اِ) شیر بیشه . (منتهی الارب ).<br /></font></div>'),
(173939, 'ضبثم', '<span class=\"hlight\">ضبثم .</span> <font color=\"DarkGreen\"><b>[ ض َ ث َ ]</font></b> (ع اِ) شیر بیشه . ضُباثِم . (منتهی الارب ). نامی است شیر را و داهیه را. ج، ضَباثِم . (مهذب الاسماء).<br /></font></div>'),
(173940, 'ضبثم', '<span class=\"hlight\">ضبثم .</span> <font color=\"DarkGreen\"><b>[ ض َ ث َ ]</font></b> (اِخ ) ابن ابی یعقوب . تابعی است . (منتهی الارب ).<br /></font></div>'),
(173941, 'ضبج', '<span class=\"hlight\">ضبج .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) انداختن خود را بزمین از اندوه یا ماندگی یا ضرب و الم و مانند آن . (منتهی الارب ).<br /></font></div>'),
(173942, 'ضبح', '<span class=\"hlight\">ضبح .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (اِخ ) آنجای از عرفات که مردمان اوائل از آن جا افاضت کنند. (منتهی الارب ). یاقوت گوید: ضبح، الموضع الذی یُدفع منه اوائل الناس من عَرفات . و ابوالکمال سیداحمد عاصم در ترجمه ٔ قاموس گوید: ضبح، مدح وزننده عرفاتده بر موضعدر که اهل وقوفک اوائلی اورادن بوشانوب گیدرلَر؛ و معنی آنکه ضبح بر وزن مدح موضعی است بعرفات که دسته ٔ اول واقفین عَرفات نخست آنان آنجا را تخلیه کرده و می روند.<br /></font></div>'),
(173943, 'ضبح', '<span class=\"hlight\">ضبح .</span> <font color=\"DarkGreen\"><b>[ ض ِ <span class=\"hlight\" dir=\"rtl\">/</span> ض َ ]</font></b> (ع اِ) خاکستر. (منتهی الارب ) (دهار) (مهذب الاسماء).<br /></font></div>'),
(173944, 'ضبح', '<span class=\"hlight\">ضبح .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ) رفتاری است اسب را و آن فوق تقریب است . <BR><font color=\"Blue\">◄</font> آواز دَم اسب که از جوف آن برآید وقت دویدن . (منتهی الارب ). بانگ نفس اسب چون بدود. (مهذب الاسماء).<br /></font></div>'),
(173945, 'ضبح', '<span class=\"hlight\">ضبح .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) ضُباح . برآوردن و شنوانیدن اسبان آواز انفاس خود را در دویدن . <BR><font color=\"Blue\">◄</font> پویه دویدن اسپان . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> از حال بگردانیدن آتش و آفتاب چیزی را. (تاج المصادر) (زوزنی ). گردانیدن آتش و آفتاب گونه ٔ چیزی را اندک نه بغایت . (منتخب اللغات ). پرهودن : ضبحت النار الشی َٔ؛ اندک برگردانید آتش گونه ٔ چیزی راو بسوخت . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بانگ کردن روباه . (تاج المصادر): ضَبح الثعلب ؛ بانگ کرد روباه . <BR><font color=\"Blue\">◄</font> ضَبحه ؛ خصومت کرد او را. (منتهی الارب ).<br /></font></div>'),
(173946, 'ضبحة', '<span class=\"hlight\">ضبحة.</span> <font color=\"DarkGreen\"><b>[ ض َ ح َ ]</font></b> (ع اِ) صیحة. آواز، و منه الحدیث : لایخرجن احدکم الی ضبحة بلیل ؛ ای صیحة یسمعها فلعله یصیبه مکروه و یروی صبحة. (منتهی الارب ).<br /></font></div>'),
(173947, 'ضبد', '<span class=\"hlight\">ضبد.</span> <font color=\"DarkGreen\"><b>[ ض َ ب َ ]</font></b> (ع اِ) خشم . خشم پنهان . (منتهی الارب ).<br /></font></div>'),
(173948, 'ضبد', '<span class=\"hlight\">ضبد.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص )آمیختن خرمای رسیده را با نارسیده . (منتهی الارب ).<br /></font></div>'),
(173949, 'ضبر', '<span class=\"hlight\">ضبر.</span> <font color=\"DarkGreen\"><b>[ ض ِ ]</font></b> (ع اِ) بغل . (منتهی الارب ). اِبط.<br /></font></div>'),
(173950, 'ضبر', '<span class=\"hlight\">ضبر.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ) جماعت غازیان . (منتهی الارب ). گروه غازیان . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> پوست پر از کاه . چوب که مردم در پس آن شده تا زیر قلعه روند برای جنگ . (منتهی الارب ). پوست که بالای چوبها کشند و در پناه آن مردان به قلعه نزدیک شوند و جنگ کنند. (منتخب اللغات ). ج، ضبور. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> درخت چارمغز. گردکان . (منتهی الارب ) (منتخب اللغات ). درخت چارمغز دشتی . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> انار دشتی . (منتهی الارب ) (منتخب اللغات ). انار کوهی . <BR><font color=\"Blue\">◄</font> جوزبوا. (منتهی الارب ). جوزبویا. (منتخب اللغات ). گوز بیابانی . (مهذب الاسماء). جوزالبر. (ضریر انطاکی ). جوزالبر؛ و آن جوز صلب است . (فهرست مخزن الادویه ). اصمعی گوید که ضبر جوز سرو را گویند در عرب . ابن الاعرابی گوید ضبر جوزبویارا گویند. ابوحنیفه گوید ضبر درختیست که بزرگی و ضخامت آن به اندازه ٔ درخت جوز باشد و برگ او بهیأت گرد به اندازه ٔ کف دست و سایه ٔ او انبوه باشد و میوه ٔ او بشبه خوشه انگور و خرما بود، و در این میوه منفعتی نباشد و در وقتی که صمغ از او آمدن گیرد آدمیان ازسایه ٔ او احتراز کنند. (ترجمه ٔ صیدنه ٔ ابوریحان ).<br /></font></div>'),
(173951, 'ضبر', '<span class=\"hlight\">ضبر.</span> <font color=\"DarkGreen\"><b>[ ض َ ب ِ ]</font></b> (ع اِ) درخت چارمغز. (منتهی الارب ). درخت گردکان . درخت گردو. درخت گوز. درخت جوز.<br /></font></div>'),
(173952, 'ضبر', '<span class=\"hlight\">ضبر.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص )فراهم آوردن اسب پایها را تا برجهد. <BR><font color=\"Blue\">◄</font> پشتاره کردن و یکجای نمودن کتابها. (منتهی الارب ). دسته کردن کتاب و آنچه بدان ماند. (تاج المصادر). <BR><font color=\"Blue\">◄</font> بترتیب چیدن سنگها و بر هم نشانیدن . (منتهی الارب ). بر هم نشاندن سنگ و جز آن . (منتخب اللغات ).<br /></font></div>'),
(173953, 'ضبر', '<span class=\"hlight\">ضبر.</span> <font color=\"DarkGreen\"><b>[ ض ِب ِرر ]</font></b> (ع ص ) فرس ضِبِرّ؛ اسب جهنده . (منتهی الارب ) (منتخب اللغات ) (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> (اِ) شیر بیشه . (منتهی الارب ). شیر درنده . (منتخب اللغات ).<br /></font></div>'),
(173954, 'ضبر', '<span class=\"hlight\">ضبر.</span> <font color=\"DarkGreen\"><b>[ ض ِ ]</font></b> (اِخ ) موضعی از نواحی صنعاء به یمن . (معجم البلدان ).<br /></font></div>'),
(173955, 'ضبران', '<span class=\"hlight\">ضبران .</span> <font color=\"DarkGreen\"><b>[ ض َ ب َ ]</font></b> (ع مص ) ضَبْر.فراهم آوردن اسپ پایها را تا بجهد. (منتهی الارب ).<br /></font></div>'),
(173956, 'ضبراک', '<span class=\"hlight\">ضبراک .</span> <font color=\"DarkGreen\"><b>[ ض ِ ]</font></b> (ع ص، اِ) ضُبارک . مردبزرگ . (مهذب الاسماء). مرد زفت . مرد توانا. استوارخلقت . <BR><font color=\"Blue\">◄</font> فربه بسیار اهل و عدد. <BR><font color=\"Blue\">◄</font> شیر بیشه . <BR><font color=\"Blue\">◄</font> شتر دفزک . (منتهی الارب ).<br /></font></div>'),
(173957, 'ضبرک', '<span class=\"hlight\">ضبرک .</span> <font color=\"DarkGreen\"><b>[ ض ِ رِ ]</font></b> (ع ص ) زن بزرگ ران . (منتهی الارب ).<br /></font></div>'),
(173958, 'ضبز', '<span class=\"hlight\">ضبز.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ) سختی نگاه . نگاه سخت . (منتهی الارب ). نگاه تند. نگاه تیز.<br /></font></div>'),
(173959, 'ضبز', '<span class=\"hlight\">ضبز.</span> <font color=\"DarkGreen\"><b>[ ض َ ب ِ ]</font></b> (ع ص ) ذِئب ضَبِز؛ گرگ سخت نظر افروخته چشم . (منتهی الارب ).<br /></font></div>'),
(173960, 'ضبس', '<span class=\"hlight\">ضبس .</span> <font color=\"DarkGreen\"><b>[ ض َ ب َ ]</font></b> (ع مص ) پلید و درشت خوی شدن نَفْس کسی . (منتهی الارب ). دشوارخو و پلید شدن . (منتخب اللغات ).<br /></font></div>'),
(173961, 'ضبس', '<span class=\"hlight\">ضبس .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) سخت گرفتن غریم را بتقاضا و ستهیدن بر آن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (ص ) سخت . (مهذب الاسماء).<br /></font></div>'),
(173962, 'ضبس', '<span class=\"hlight\">ضبس .</span> <font color=\"DarkGreen\"><b>[ ض ِ ]</font></b> (ع اِ) هو ضِبْس ُ شَرّ؛ او صاحب شرّ و بدی است . (منتهی الارب ).<br /></font></div>'),
(173963, 'ضبس', '<span class=\"hlight\">ضبس .</span> <font color=\"DarkGreen\"><b>[ ض َ ب ِ ]</font></b> (ع ص ) پلید. دشوارخوی . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> گربز پرکار. (منتهی الارب ). زیرک . <BR><font color=\"Blue\">◄</font> (اِ) بلا. (منتهی الارب ).<br /></font></div>'),
(173964, 'ضبضب', '<span class=\"hlight\">ضبضب .</span> <font color=\"DarkGreen\"><b>[ ض ِ ض ِ ]</font></b> (ع ص ) فربه . <BR><font color=\"Blue\">◄</font> دلیر بدزبان . (منتهی الارب ).<br /></font></div>'),
(173965, 'ضبط', '<span class=\"hlight\">ضبط.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) صاحب کشاف اصطلاحات الفنون گوید: در لغت بمعنی قطع است . ودر اصطلاح رساندن سخن بگوش شنونده است کما هو حقه، یعنی بهمان نحو که سخن را از دیگری فراگرفته . سپس درک سخن باشد بقسمی که در موقع رساندن بغیر معنی آن بر شنونده روشن و هویدا بود. سپس در حفظ و نگاهداری سخن چندان کوشش ورزد و در خاطر چندان آن سخن را بیاد آورد که هنگام شنواندن بغیر بتواند بدون هیچ تغییر و تبدیلی آن سخن را بنحوی که شنیده و فراگرفته ادا کند.کذا فی الجرجانی . یاد گرفتن . حفظ کردن <span class=\"hlight\">:</span> <br />کس ز کوه و سنگ عقل و دل نجست <br />فهم و ضبط نکته ٔ مشکل نجست .<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> نگاه داشتن چیزی را بهوش . (منتهی الارب ). نگاه داشتن به حزم و هوش . (منتخب اللغات ) <span class=\"hlight\">:</span> و احداث متعلمان بطریق تحصیل علم و موعظت نگرند و ضبط آن بر ایشان سبک خیزد. (کلیله و دمنه ). <BR><font color=\"Blue\">◄</font> در قبضه آوردن و اداره کردن سرزمینی آنچنان که اوضاع آن به سامان آید <span class=\"hlight\">:</span> آن دیار تا روم و از دیگر جانب تا مصر طولاً و عرضاً به ضبط ما آراسته گردد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٢٣</span>). اهل جمله آن ولایات گردن برافراشته تا نام ما بر آن نشیند و به ضبط ما آراسته گردد. (تاریخ بیهقی ). چون پدر ما گذشته شد ما دور بودیم ازتخت ملک که ... جهانی را زیر ضبط آورده . (تاریخ بیهقی ). <BR><font color=\"Blue\">◄</font> در حیطه ٔ تصرف و تسلط خود نگه داشتن <span class=\"hlight\">:</span> چون رسول دررسید جواب فرستاد که خراسان بشوریده است و من بضبط آن مشغول بودم . (تاریخ بیهقی ). <BR><font color=\"Blue\">◄</font> انجام دادن و به نظم آوردن <span class=\"hlight\">:</span> احمد و شکر بگریستند و بیرون آمدند و بضبط کارها مشغول شدند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٥٧</span>). اعیان و مقدمان نیک بکوشیدند تا کار ضبط شد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٤٢</span>). <BR><font color=\"Blue\">◄</font> حفظ کردن و صیانت چیزی <span class=\"hlight\">:</span> <br />سلطان علاء دولت کز یُمن دولتش <br />در ضبط دین و دنیا عالیست کار تیغ.<br /> <font color=\"Red\">مسعودسعد.</font><br />ضبط مسالک و حفظ ممالک ... به سیاست منوط. (کلیله و دمنه ). هم سیاست پادشاهان را در ضبط ممالک بدان ملاذ تواند بود. (کلیله و دمنه ).<br /> <BR><font color=\"Blue\">◄</font> نگاه داشتن . (دهار) <span class=\"hlight\">:</span> یکی را از بزرگان بادی مخالف در شکم پیچیدن گرفت، طاقت ضبط آن نیاورد. (گلستان ). <BR><font color=\"Blue\">◄</font> فراهم آوردن . (دهار). <BR><font color=\"Blue\">◄</font> ضُبطت الارض (مجهولاً)؛ باران باریده شد زمین . (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">در ضبط آوردن </span> ؛ به تصرف درآوردن و زیر فرمان آوردن <span class=\"hlight\">:</span> تا اغلب ممالک عالم در ضبط خویش آورد. (کلیله و دمنه ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضبطالقلم، ضبط قلم </span> ؛ نهادن حرکات کلمه ای را با قلم، یعنی زیر و زبر و پیش و جزم و مدّ در بالا یا زیر کلمه نهادن و یا با بیان تمام آنها را ادا کردن چنانکه گوئی طاهر به طاء مشالّه ٔ به الف کشیده و کسر هاء هوّز و سکون راء.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضبط کردن </span> ؛ حفظ کردن . اداره کردن . نگاهداری <span class=\"hlight\">:</span> پادشاه چون مُلکی ... بگیرد و آن را ضبط نتواند کرد... همه ٔ زبانها را در گفتن اینکه وی عاجز است مجال تمام داده باشد. (تاریخ بیهقی ). ما را چندین ولایت در پیش است، آن را به فرمان امیرالمؤمنین می باید گرفت و ضبط کرد. (تاریخ بیهقی ).<BR>۩ تصرف کردن . در قبضه آوردن <span class=\"hlight\">:</span> و ما را با خود برد و آن نواحی ضبطکرد و بما سپرد و بازگشت بسبب نالانی و نزدیک آمدن اجل . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢١٦</span>). به هرچه ایشان را دست در خواهد شد از مکر و حیل و فریفتن غلامان و ضبط ولایات ...بسیار کرده اند و هیچ باقی نخواهند گذاشت . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٩٩</span>).<br />ملک بیک حمله ضبط کردی احسنت <br />این ظفرت بر خلود ملک ضمانست .<br /> <font color=\"Red\">؟</font><BR>۩ مقاومت و پایداری کردن <span class=\"hlight\">:</span> خوارزمشاه بانگ برزد و مددی فرستادن از قلب، ضبط نتوانست کردن . (تاریخ بیهقی ).<BR>۩ به نظم آوردن ونیک انجام دادن . اداره کردن <span class=\"hlight\">:</span> دیگر روز بدرگاه آمد کار ضبط کرد و مردی شهم و کافی بود. (تاریخ بیهقی ). سالاری محتشم فرستاده آید... تا آن دیار که گرفته بودیم ضبط کند و دیگر گیرد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٧٦</span>). دریغ چون اریارق که اقلیمی ضبط توانستی کردن . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٢٩</span>).<BR>۩ حفظ کردن و در اختیار داشتن <span class=\"hlight\">:</span> هر مردی که تن خود را ضبط تواند کرد... وی را خردمند خویشتن دار گویند. (تاریخ بیهقی ).<BR>۩ زیر فرمان آوردن <span class=\"hlight\">:</span> غلامان گردن آورتر از مرگ خوارزمشاه شمّتی یافته بودند شمایان را بدین رنجه کردم تا ایشان را ضبط کرده آید. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٥٨</span>).<BR>۩ حفظ کردن و در اختیار گرفتن <span class=\"hlight\">:</span> و ما چون از ری حرکت کردیم تا تخت ملک پدر را ضبط کرده آید و بدامغان رسیدیم بوسهل زوزنی بما پیوست . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٢٣</span>).<br /> <BR><font color=\"Blue\">◄</font> در ضبط آمدن ؛ به تصرف درآمدن و زیر فرمان قرار گرفتن <span class=\"hlight\">:</span> و تمام ممالک غزنین و زابلستان ... در ضبط فرمان آن شاهنشاه محتشم ... آمد. (کلیله و دمنه ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضبطگونه </span> ؛ شبه تصرف <span class=\"hlight\">:</span> خراسان را ضبطگونه ای کرد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٢٩</span>).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضبط و ربط</span> ؛ از اتباع است .<br /></font></div>'),
(173966, 'ضبط', '<span class=\"hlight\">ضبط.</span> <font color=\"DarkGreen\"><b>[ ض َ]</font></b> (ع اِ) جائی که اوراق و اسناد ملی را نگهداری کنند. آنجا که اوراق اداره را نگاه دارند. بایگانی .<br /></font></div>'),
(173967, 'ضبط', '<span class=\"hlight\">ضبط.</span> <font color=\"DarkGreen\"><b>[ض ُ ]</font></b> (ع ص، اِ) ج ِ اَضبط و ضَبطاء. (منتهی الارب ).<br /></font></div>'),
(173968, 'ضبط', '<span class=\"hlight\">ضبط.</span> <font color=\"DarkGreen\"><b>[ ض َ ب َ ]</font></b> (ع مص ) بهر دو دست کار کردن . (منتخب اللغات ).<br /></font></div>'),
(173969, 'ضبطبیگی', '<span class=\"hlight\">ضبطبیگی .</span> <font color=\"DarkGreen\"><b>[ ض َ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (اِ مرکب ) مأموری که خدمت ضبط اموال واثاثه ٔ باقی داران بواسطه ٔ او باشد. (از آنندراج ).<br /></font></div>'),
(173970, 'ضبطر', '<span class=\"hlight\">ضبطر.</span> <font color=\"DarkGreen\"><b>[ ض ِ ب َ ]</font></b> (ع ص ) ضبیطر. توانا. <BR><font color=\"Blue\">◄</font> فربه پرگوشت و گرداندام . <BR><font color=\"Blue\">◄</font> شیر قوی سخت . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> سخت . (مهذب الاسماء).<br /></font></div>'),
