(174267, 'ضرس', '<span class=\"hlight\">ضرس .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) گزیدن سخت . (منتهی الارب ). سخت گزیدن . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> سخت شدن روزگار بر کسی . (منتهی الارب ) (منتخب اللغات ). سختی زمانه . <BR><font color=\"Blue\">◄</font> سکوت تمام روز تا شب . (منتهی الارب ). خاموش بودن تا شب . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> بریدن بینی شتر به سنگ سپس آن گذاشتن بر آن دوال یازه را تا رام شود. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بدندان آزمودن چوب را بنرمی و سختی . (منتهی الارب ). بدندان نرمی و سختی چوب آزمودن . (منتخب اللغات ). دندان برتیر نهادن و جز آن . (تاج المصادر). دندان بر تیر نهادن تا سخت است یا سست . (زوزنی ). <BR><font color=\"Blue\">◄</font> برزیدن چاه به سنگ . (تاج المصادر). چاه به سنگ برآوردن . (زوزنی ). برآوردن گرداگرد چاه را از سنگ . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کند شدن دندان از ترشی . (منتهی الارب ) (منتخب اللغات ) (زوزنی ) (تاج المصادر). خیره شدن دندان . خیرگی دندان . رجوع به خیرگی شود. <BR><font color=\"Blue\">◄</font> (ص، اِ) زمین که جای جای گیاه دارد. (منتهی الارب ).<br /></font></div>'),
(174268, 'ضرس', '<span class=\"hlight\">ضرس .</span> <font color=\"DarkGreen\"><b>[ ض ِ ]</font></b> (ع اِ) دندان . (دهار) (منتهی الارب )(منتخب اللغات ) (مهذب الاسماء). سِن ّ. ج، ضُروس، اضراس . (منتهی الارب ) (مهذب الاسماء). و اضراس نام دیگر دندانهای آسیا یعنی طواحن است . (از ذخیره ٔ خوارزمشاهی ). دندان کرسی . (بحر الجواهر). و آن شانزده دندانست از پس ضواحک، هشت بر بالا و هشت بر زیر، چهار بر جانب راست و چهار بر جانب چپ . نام دندان آسیاست . دندان بزرگ یعنی دندان آسیا که بهندی داره گویند. (غیاث ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">به ضرس قاطع</span> ؛ از روی یقین .<br /><BR><font color=\"Blue\">◄</font> درددندان . دندان درد . <BR><font color=\"Blue\">◄</font> پشته ٔ درشت . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> باران ِ اندک . (منتهی الارب ) (منتخب اللغات ) (مهذب الاسماء). ج، ضروس . <BR><font color=\"Blue\">◄</font> (مص ) طول قیام در نماز. (منتهی الارب ). بسیار ایستادن در نماز. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> بند کردن چشم برقع. <BR><font color=\"Blue\">◄</font> (اِ) گیاه شیح . (منتهی الارب ). درمنه . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> درخت رمث که بیخ آنها پوسیده و خورده شده باشد. <BR><font color=\"Blue\">◄</font> سنگ که بدان گرداگرد چاه را برآورند. (منتهی الارب ). سنگی که به آن چاه را بگیرند. (منتخب اللغات ). ج، ضُروس . <BR><font color=\"Blue\">◄</font> ضرس العیر؛ لقب شمشیر علقمةبن ذی قیفان است . (منتهی الارب ).<br /></font></div>'),
(174269, 'ضرس', '<span class=\"hlight\">ضرس .</span> <font color=\"DarkGreen\"><b>[ ض َ رِ ]</font></b> (اِخ ) نام اسپی که نبی (ص ) از فزاری خرید و نام آن به سکب تغییر فرمود. (منتهی الارب ).<br /></font></div>'),
(174270, 'ضرس', '<span class=\"hlight\">ضرس .</span> <font color=\"DarkGreen\"><b>[ض َ رِ ]</font></b> (ع ص ) آنکه خشم گیرد از گرسنگی (منتهی الارب ). غضبناک از گرسنگی . <BR><font color=\"Blue\">◄</font> بدخو. (منتخب اللغات ). مرد تندخو. (منتهی الارب ). مردی درشت . (مهذب الاسماء). ضَرِس ٌ شَرِس ٌ؛ مرد دشوارخو. (منتهی الارب ).<br /></font></div>'),
(174271, 'ضرس العجوز', '<span class=\"hlight\">ضرس العجوز.</span> <font color=\"DarkGreen\"><b>[ ض ِ سُل ْ ع َ ]</font></b> (ع اِ مرکب ) سعدان . حَسک . حسک است، و گویند خار سعدان است . (تحفه ٔ حکیم مؤمن ). خَسک . (اختیارات بدیعی ). شوک السعدان را نامند، و گویند حسک است . (فهرست مخزن الادویه ). ضریر انطاکی در تذکره گوید:ضرس العجوز حسک است نه سعدان چنانکه گمان برده اند.<br /></font></div>'),
(174272, 'ضرسام', '<span class=\"hlight\">ضرسام .</span> <font color=\"DarkGreen\"><b>[ ض ِ ]</font></b> (اِخ ) نام آبی است . (منتهی الارب ).<br /></font></div>'),
(174273, 'ضرسامة', '<span class=\"hlight\">ضرسامة.</span> <font color=\"DarkGreen\"><b>[ ض ِ م َ ]</font></b> (ع ص ) ناکس بیمروت . <BR><font color=\"Blue\">◄</font> سست حقیر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> داهیه . (مهذب الاسماء).<br /></font></div>'),
(174274, 'ضرضم', '<span class=\"hlight\">ضرضم .</span> <font color=\"DarkGreen\"><b>[ ض َ ض َ ]</font></b> (ع اِ) شیر بیشه . (منتهی الارب ). اسد. (فهرست مخزن الادویه ). <BR><font color=\"Blue\">◄</font> ددِنر. (منتهی الارب ). سباع نر. (فهرست مخزن الادویه ).<br /></font></div>'),
(174275, 'ضرط', '<span class=\"hlight\">ضرط.</span> <font color=\"DarkGreen\"><b>[ ض َ رَ ]</font></b> (ع اِمص ) سبکی ریش . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> باریکی ابرو. (منتهی الارب ). تنکی ابرو. (منتخب اللغات ).<br /></font></div>'),
(174276, 'ضرط', '<span class=\"hlight\">ضرط.</span> <font color=\"DarkGreen\"><b>[ ض َ رِ ]</font></b> (ع مص ) ضَرط. تیز دادن . (منتهی الارب ).<br /></font></div>'),
(174277, 'ضرط', '<span class=\"hlight\">ضرط.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) ضَرِط. تیز دادن . (منتهی الارب ).<br /></font></div>'),
(174278, 'ضرطم', '<span class=\"hlight\">ضرطم .</span> <font color=\"DarkGreen\"><b>[ ض ِ طِ ]</font></b> (ع ص ) کلان شکم . (منتهی الارب ).<br /></font></div>'),
(174279, 'ضرع', '<span class=\"hlight\">ضرع .</span> <font color=\"DarkGreen\"><b>[ض َ ]</font></b> (ع اِ) پستان، و هوللظلف و الخف او للشاة و البقر و نحوهما. ج، ضروع . (منتهی الارب ). پستان گاو و گوسفند. (دهار). پستان اشتر. (مهذب الاسماء). پستان گاو و گوسفند و غزال و امثال آن . پستان شتر و گاو و گوسفند و مانند آن، یا آنکه مخصوص بقر و غنم است . (منتخب اللغات ) <span class=\"hlight\">:</span> <br />آنکه مادر آفرید و ضَرع و شیر<br />تا پدر کردش قرین آن خود مگیر.<br /> <font color=\"Red\">مولوی .</font><br />پستان، و آن چیزی باشد از انسان و حیوان دیگر که شیر از آن دوشند. (برهان ). پستان حیوان است و مولد خلط کثیف و دیرهضم و مدر بول زنان و جهت رفع خمار و معده ای که اخلاط حاره در آن موجود باشد نافع است . (تحفه ٔ حکیم مؤمن ). محل اللبن من الحیوان رَدی ءالمأکول عصبانی لاخیر فی کیموسه . (تذکره ٔ ضریر انطاکی ). بهترین پستان آن بود که از حیوانی گیرند که گوشت وی نیکوبود و در وی شیر بسیار بود، و طبیعت وی سرد و خشک بود و اولی آن بود که با افاویه خورند زود از معده بگذرد، و شریف گوید آن شیردار که شیر وی اندک بود چون بخورد شیر وی زیاده گردد. (اختیارات بدیعی ). بپارسی پستان از غیر انسان را گویند، بهترین پستانهای حیوانات پستان گوسفند بود، طبیعتش سرد و خشک است در اول که به داروهای گرم خورند تا زود از معده بگذرد، و منفعت او آن است که چون بروغن بریان کرده بخورند ادرار شیر کند. <BR><font color=\"Blue\">◄</font> شبرق، و آن گیاهی است در عربستان . (از حاشیه ٔ مثنوی ). نام گیاهی است . (غیاث ) <span class=\"hlight\">:</span> <br />ظاهر الفاظشان توحید و شرع <br />باطن آن همچو در نان تخم ضرع .<br /> <font color=\"Red\">مولوی .</font><br /><BR><font color=\"Blue\">◄</font> دوشیدنی . شیرده : ما له حرث و لا ضرع، ما له زرع و لا ضرع .<br /></font></div>'),
(174280, 'ضرع', '<span class=\"hlight\">ضرع .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) ضراعة. زاری و خواری . زاریدن . خوار و حقیر گردیدن . <BR><font color=\"Blue\">◄</font> فروتنی کردن . <BR><font color=\"Blue\">◄</font> رام شدن . <BR><font color=\"Blue\">◄</font> رام کردن اسپ . (منتهی الارب ).<br /></font></div>'),
(174281, 'ضرع', '<span class=\"hlight\">ضرع .</span> <font color=\"DarkGreen\"><b>[ ض ِ ]</font></b> (ع اِ) مثل و مانند. (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> تاه رسن . ج، ضروع، اضرع . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> استواری رسن . (منتخب اللغات ).<br /></font></div>'),
(174282, 'ضرع', '<span class=\"hlight\">ضرع .</span> <font color=\"DarkGreen\"><b>[ ض َ رَ ]</font></b> (ع ص ) سست و ناتوان . (منتهی الارب ) (منتخب اللغات ). ج، ضَرَع (بصورت واحد)، و گویند: رجل ضَرَع و قوم ضَرَع . <BR><font color=\"Blue\">◄</font> مُهْرٌ ضَرَع ٌ؛ اسب کره ٔ ناتوان که دویدن نتواند جهت سستی و ناتوانی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ریزه و خرد از هر چیزی . (منتهی الارب ). چیز خرد. <BR><font color=\"Blue\">◄</font> خردسال . (منتخب اللغات ). کم سن سست بدن ناتوان ناآزموده کار. (منتهی الارب ).<br /></font></div>'),
(174283, 'ضرع', '<span class=\"hlight\">ضرع .</span> <font color=\"DarkGreen\"><b>[ ض َ رَ ]</font></b> (ع ص ) ج ِ ضَرَع . (منتهی الارب ). رجوع به ماده ٔ قبل شود.<br /></font></div>'),
(174284, 'ضرع', '<span class=\"hlight\">ضرع .</span> <font color=\"DarkGreen\"><b>[ ض َ رِ ]</font></b> (ع ص ) متواضع. <BR><font color=\"Blue\">◄</font> رام . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خوار. (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> سست ناتوان . (منتهی الارب ). ضعیف . (مهذب الاسماء) (منتخب اللغات ).<br /></font></div>'),
(174285, 'ضرعة', '<span class=\"hlight\">ضرعة.</span> <font color=\"DarkGreen\"><b>[ ض َ رَ ع َ ]</font></b> (ع ص ) رام . <BR><font color=\"Blue\">◄</font> متواضع. <BR><font color=\"Blue\">◄</font> خوار و حقیر. (منتهی الارب ).<br /></font></div>'),
(174286, 'ضرعمط', '<span class=\"hlight\">ضرعمط.</span> <font color=\"DarkGreen\"><b>[ ض ُ رَ م ِ ]</font></b> (ع ص، اِ) شیر دفزک زده ٔ جغرات شده . <BR><font color=\"Blue\">◄</font> مرد آرزومند هر چیزی . (منتهی الارب ).<br /></font></div>'),
(174287, 'ضرغام', '<span class=\"hlight\">ضرغام .</span> <font color=\"DarkGreen\"><b>[ ض ِ ]</font></b> (ع اِ) شیر بیشه . ضرغامة. (منتهی الارب ). شیر. (بحر الجواهر) (مهذب الاسماء) (دهار). شیردرنده . (منتخب اللغات ). اسد. ج، ضراغم <span class=\"hlight\">:</span> <br />ارجو که مردی شود مبارز<br />کز پیل نندیشد و ز ضرغام .<br /> <font color=\"Red\">فرخی .</font><br />وگر نشاط شکار آیدت روا باشد<br />که با منست بهر بیشه ای کنون ضرغام .<br /> <font color=\"Red\">مسعودسعد.</font><br />جائی که بأس حسام و صولت بهرام و سورت ضرغام روی نمود، بخوادع کلام و روادع ملام التفاتی نرود. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٨٨</span>).<br /></font></div>'),
(174288, 'ضرغامة', '<span class=\"hlight\">ضرغامة.</span> <font color=\"DarkGreen\"><b>[ ض ِ م َ ]</font></b> (ع اِ) شیر بیشه . (منتهی الارب ). اسد. ضرغام . <BR><font color=\"Blue\">◄</font> مرد دلاور. (منتهی الارب ). گشن قوی و توانا. مرد سخت . وفی نسخة و الوحل الشدید، فسّرها گل و لای شدید. (منتهی الارب ).<br /></font></div>'),
(174289, 'ضرغد', '<span class=\"hlight\">ضرغد.</span> <font color=\"DarkGreen\"><b>[ ض َ غ َ ]</font></b> (اِخ ) کوهی است و گویند سنگستانی است در بلادغطفان . یا آبی است در نجد ازآن ِ بنی مرة میان یمامه و ضریه، و نیز گویند مقبره ای است . (معجم البلدان ).<br /></font></div>'),
(174290, 'ضرغم', '<span class=\"hlight\">ضرغم .</span> <font color=\"DarkGreen\"><b>[ ض َ غ َ ]</font></b> (ع اِ) شیر بیشه . (منتهی الارب ). شیر درنده . (منتخب اللغات ). اسد.<br /></font></div>'),
(174291, 'ضرغمة', '<span class=\"hlight\">ضرغمة.</span> <font color=\"DarkGreen\"><b>[ ض َ غ َ م َ ]</font></b> (ع مص ) ضَرغمت الابطال ؛ شیری کردند دلاوران و شیر شدند. (منتهی الارب ).<br /></font></div>'),
(174292, 'ضرف', '<span class=\"hlight\">ضرف .</span> <font color=\"DarkGreen\"><b>[ ض َ رِ ]</font></b> (ع اِ) درخت انجیر. (منتهی الارب ) (فهرست مخزن الادویه ). بعضی گفته اند درختی است کوهی در بزرگی و در برگ مانا بدرخت اثاب . بار آن سپید مدور و پهن، مانند تین الحماط الصغار و تلخ . می شکنند آن را بدندان و میخورند آن را مردم و طیور و بوزنگان . (منتهی الارب ).<br /></font></div>'),
(174293, 'ضرفة', '<span class=\"hlight\">ضرفة.</span> <font color=\"DarkGreen\"><b>[ ض ُ ف َ ]</font></b> (ع اِمص ) بسیاری . گویند: هو فی ضرفة خیر؛ ای کثرته . (منتهی الارب ).<br /></font></div>'),
(174294, 'ضرفة', '<span class=\"hlight\">ضرفة.</span> <font color=\"DarkGreen\"><b>[ ض َ رِ ف َ ]</font></b> (ع اِ) یکی درخت انجیر. (منتهی الارب ). انجیر وحشی . درخت کوهی . ج، ضرف . (مهذب الاسماء).<br /></font></div>'),
(174295, 'ضرفطی', '<span class=\"hlight\">ضرفطی .</span> <font color=\"DarkGreen\"><b>[ ض ِ رِ طی ی ]</font></b> (ع ص ) فربه کلان شکم . (منتهی الارب ).<br /></font></div>'),
(174296, 'ضرم', '<span class=\"hlight\">ضرم .</span> <font color=\"DarkGreen\"><b>[ ض ِ <span class=\"hlight\" dir=\"rtl\">/</span> ض ُ ]</font></b> (ع اِ) درختی است خوشبو، بار آن مانند بلوط است و شکوفه اش مانند شکوفه ٔ سعتر، شهد آن نیکو باشد، یا آن اسطوخودوس است بیونانیه . (منتهی الارب ). اسطوخودوس . (فهرست مخزن الادویه ) (تحفه ٔ حکیم مؤمن ) (اختیارات بدیعی ). درختی است خوشبو که ثمرش چون بلوط و شکوفه اش چون شکوفه ٔ خرماست، و برخی گفته اند که بیونانی آن را اسطوخودوس گویند. (منتخب اللغات ). نام داروئی که بیونانی اسطوخودوس گویند و آن شاه اسفرم رومی است، علت صرع را نافع باشد. (برهان ).<br /></font></div>'),
(174297, 'ضرم', '<span class=\"hlight\">ضرم .</span> <font color=\"DarkGreen\"><b>[ ض َ رَ ]</font></b> (ع اِ) ج ِ ضَرمة. (منتهی الارب ). چیزهای نیم سوخته . (منتخب اللغات ).<br /></font></div>'),
(174298, 'ضرم', '<span class=\"hlight\">ضرم .</span> <font color=\"DarkGreen\"><b>[ض َ رَ ]</font></b> (ع مص ) سخت گرسنه گردیدن . (تاج المصادر) (منتهی الارب ) (زوزنی ). سخت شدن گرسنگی . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> سخت شدن سوزش و حرارت چیزی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> افروخته شدن آتش . (زوزنی ). افروخته شدن آتش و شعله زدن آن . (منتهی الارب ). زبانه زدن آتش . (تاج المصادر). افروختن آتش سخت . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> افروخته شدن بر کسی از خشم . (منتهی الارب ). غضبناک شدن . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> نیک خوردن طعام و چیزی نگذاشتن از آن . (منتهی الارب ).<br /></font></div>'),
(174299, 'ضرم', '<span class=\"hlight\">ضرم .</span> <font color=\"DarkGreen\"><b>[ ض َ رِ ]</font></b> (ع ص ) گرسنه . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> فَرَس ٌ ضَرِم ؛ اسبی دونده . (مهذب الاسماء). اسپ تیزرفتار. (منتخب اللغات ). اسپ بسیار تیز دونده . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) بچه ٔ عقاب . (مهذب الاسماء) (منتخب اللغات ). فرخ العقاب . (فهرست مخزن الادویه ).<br /></font></div>'),
(174300, 'ضرمة', '<span class=\"hlight\">ضرمة.</span> <font color=\"DarkGreen\"><b>[ ض َ رَ م َ ]</font></b> (ع اِ) نیم سوخته از شیحه و از شاخ خرما. ج، ضَرَم . (منتهی الارب ). نیم سوز. هیزم نیم سوخته . هیزم آتش گیر. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> خدرک آتش . <BR><font color=\"Blue\">◄</font> آتش . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ما بها نافخ ضرمة؛ یعنی نیست در آن کسی . (منتهی الارب ) (مهذب الاسماء).<br /></font></div>'),
(174301, 'ضرمة', '<span class=\"hlight\">ضرمة.</span> <font color=\"DarkGreen\"><b>[ ض َ رَ م َ ]</font></b> (اِخ ) یوم ُ ضرَمة؛ نام جنگی از جنگهای عرب . (عقد الفرید ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٧٥</span>).<br /></font></div>'),
(174302, 'ضرمة', '<span class=\"hlight\">ضرمة.</span> <font color=\"DarkGreen\"><b>[ ض ِ م َ ]</font></b> (اِخ ) ابن ضِرمة. جد است هاشم بن حُرمله را. (منتهی الارب ).<br /></font></div>'),
(174303, 'ضرو', '<span class=\"hlight\">ضرو.</span> <font color=\"DarkGreen\"><b>[ ض ُ رُوو ]</font></b> (ع مص ) ضَرْو. رجوع به ضَرْو شود.<br /></font></div>'),
(174304, 'ضرو', '<span class=\"hlight\">ضرو.</span> <font color=\"DarkGreen\"><b>[ ض ِرْوْ ]</font></b> (ع اِ) بچه ٔ دونده ٔ سگ . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> سگ صید. (مهذب الاسماء). سگ شکاری . (فهرست مخزن الادویه ). <BR><font color=\"Blue\">◄</font> اندک از جذام که خوره باشد. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بن (در این معنی بفتح اول نیز آید). (منتهی الارب ). ج، اضراء. کمکام یا صمغ آن . (منتهی الارب ). خنجک و آن نام درختی باشد. (بحر الجواهر).صمغ درخت کمکام و آن را از یمن آرند. (مفاتیح ). بطم . حبةالخضراء. شلم این درخت حسن لَبه است (حصی لبان ). شجرةالمصطکی . افواه الطیب .ضرو، مانند درخت بلوط است برگش بسرخی زند و چوبش درعمارات بقای عظیم دارد. (نزهة القلوب ). صمغالکمکام .(ذخیره ٔ خوارزمشاهی ). گروهی گفته اند که درخت حبةالخضراء (ونیزه ) که کهن شود و بزرگ باشد، آن را ضرو گویند. (ذخیره ٔ خوارزمشاهی ). ضرو، کمکام و صمغالکمکام صمغ این درخت است . ابن الاعرابی گوید که ضرو درخت بطم را گویند یعنی درخت حبةالخضراء را و ذکر او در حرف باء کرده شده است . ارجانی گوید او گرم است در سه درجه و خشکست در دو درجه و اطلاق شکم را دفع کند و درد دهان را که بتازی آن را قلاع گویند بغایت مفید باشد و زداینده است هر اعضا را و آماسها را تحلیل کند و از عمق تن مادّه های غلیظ را بکشد و دفع کند. ابن ماسویه گوید: قوت او چون قوت لادن است و او را در عطرها بکاربرند و محمد زکریا گوید هرکه را قُلاع باشد چون از او در دهان گیرد درد دهان را دفع کند. (ترجمه ٔ صیدنه ٔابوریحان ). درختی است در کوهستان یمن مانند درخت بلوط بزرگ الا از وی نیکوتر بود و ورق وی بسرخی مایل بود و ثمر وی مانند خوشه ٔ بطم لیکن حب وی بزرگتر بود وورق وی چون بپزند و صافی کنند و دیگر بر سر آتش نهند و بپزند تا نزدیک به انعقاد بعد از آن بردارند و استعمال کنند جهت خشونت سینه و سرفه که از سردی بود ودرد دهان و گویند قلاع را ساکن کند درحال و صمغ وی می آورند بمکه، و به قوت مانند لادن بود در بویهای خوش زنان بکار دارند و خوشبوی بود و طبیعت آن گرم و خشک بود در دوم و گویند در سیوم و تر بود در اول و گویندخشک در اول و بعضی گویند کمکام ورق درخت ضرو است و گویند کمکام لحای وی است یعنی پوست بیخ آن، صمغ ضرو معروفست به کمکام و طبیعت آن گرم است در دوم و خشک در اول، محلل و جذاب بود از عمق بدن، و اسحاق بن سلیمان گوید که حب آن ریاح بلغمی را تحلیل دهد و رازی گوید ضرو جهت دفع قلاع و اطلاق بطن نیکو بود و شریف گوید روغن بسیار از حب وی بیرون آید و بادها بشکند و محلل و مجفف بود و چون ورق وی با روغن بپزند و در گوش چکانند درد دندان را ساکن کند و چون به آب بپزند و طبیخ آن مضمضه کنند بُن دندان را محکم گرداند و بلغم را زایل کند و چون ورق تازه ٔ وی همچنان بسوزانند تا خاکستر گردد و به آب بپزند و صاف کنند و مقدار سی درم بیاشامند درد خاصره زایل کند و فحم چوب وی جهت جراحتها نیکو بود و قطع خون رفتن بکند خاصه از جراحت ختنه ٔ اطفال، و اسحاق بن عمران گوید بدل ضرو یمنی ضرو اندلس بود و بعضی گویند ضرو درخت حبةالخضراء است و این مؤلف گوید آنچه بمکه می آورند رب ّالضرو خوانند بوی دهان خوش کند چون در دهان گیرند. (اختیارات بدیعی ). اسم درختیست در بلاد یمن شبیه بدرخت بلوط و ثمرش مثل بطم و دانه ٔ او بزرگتر از آن و صمغ او معروف به حصی لبان است . شاخ و برگ و بار او گرم و خشک و آب مطبوخ او که با شکر بقوام آورند جهت خشونت حلق و سرفه و درد دهان نافع و روغن دانه ٔ او خوشبو و مجفف و محلل بلغم و ریاح و جهت تقویت معده و جرب حیوانات مفید و بدلش روغن حب البطم است و برگش خوشبو و طبیخ او بقدر سه وقیه رافع درد تهیگاه و مضمضه ٔ او جهت قلاع و تقویت لثه مؤثر و عصاره ٔ او قوی و روغنی که در آن برگ او را جوشانیده باشند جهت درد گوش و چوب سوخته ٔ او جهت قطع خون جراحات و قروح مقعدو قضیب نافع است . (تحفه ٔ حکیم مؤمن ). شجرةٌ یمانیةٌ کالبلوط الا ان اوراقها لیست شائکة و تحمل عناقید فوق حجم الحیةالخضراء و هذه الشجرة لم یعرفها غالب اهل هذه الصناعة بحقیقتها و الصحیح انها الکمکام و ان صمغها هو المعروف بالحصی لبان الجاوی علی ما صححته بعدمشقة و هی حارة یابسة فی الثالثة او یبسها فی الاولی قابضة تحذو اللسان و تنفع من القلاع و مرض اللهاة و الصدر و السعال و المقعدة و آلات التناسل مطلقاً و الاغتسال بها یقوی البدن و یحفظ الشعر و یحل الصلابات و صمغها المذکور من اجود الصموغ رائحة و اجوده الابیض المشرب بالحمرة الطیب الرائحه اذا القی فی النار و یغش بالمصطکی و الکندر و الصمغ اذا طبخ فی النخالة و طبقت فی فصوص الجاوی ایاماً و رفعت کما جربته و الفرق بینهما الدخان و یقوی القلب و یسر النفس بخوراً و یشد اللثة مضغاً و یحس النزلات طلاء و جب هذه الشجرة اذامضغ نقی الرأس و دهنه یحلل الریاح المزمنة. (تذکره ٔ ضریر انطاکی ). صاحب البیان و التبیین گوید قضبان المساویک، البشام و الضرو و العنم و... (ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٧٧</span>).<br /></font></div>'),
(174305, 'ضرو', '<span class=\"hlight\">ضرو.</span> <font color=\"DarkGreen\"><b>[ ض َرْوْ ]</font></b> (ع اِ) بن . ضِرو. رجوع به ضِرو شود. ج، اَضراء. (منتهی الارب ).<br /></font></div>'),
(174306, 'ضرو', '<span class=\"hlight\">ضرو.</span> <font color=\"DarkGreen\"><b>[ ض َرْوْ ]</font></b> (ع مص ) ضُرُوّ. بیرون جهیدن خون ازرگ . (منتهی الارب ). شاریدن خون از جراحت و شیر از پستان . (زوزنی ). شریدن خون از جراحت . (تاج المصادر).<br /></font></div>'),
(174307, 'ضروان', '<span class=\"hlight\">ضروان .</span> <font color=\"DarkGreen\"><b>[ ض َ رَ ]</font></b> (اِخ ) شهرکی است نزدیک صنعاء و بنام وادئی که بهمین نام و در کنار آن واقعست موسوم گردیده و بین آن وادی و صنعا چهار فرسنگ است . یاقوت در وصف آن گوید: و هو واد ملعون حرج مشئوم حجارته تشبه انیاب الکلاب لایقدر احد یطؤه بوجه و لا سبب و لاینبت شیئاً و لایستطیع طائر ان یمرّ به فاذا قاربه مال عنه و قیل هی الارض التی ذکرها اﷲ تعالی فی کتابه العزیز و قیل انها کانت احسن بقاع اﷲ فی الارض و اکثرها نخلاً و فاکهةً و ان اهلها غدوا الیها و تواصوا الا یدخلها علیهم مسکین فاصبحوا فوجدوا ناراً تأجج فمکثت النار تتقد فیها ثلاثمائة سنة. (معجم البلدان ). ضروان نام دهی است . (غیاث ) (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">اصحاب ضروان </span> ؛ درباره ٔ اصحاب ضروان ابوالفتوح رازی در تفسیر (ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧٧</span>) ذیل آیه ٔ «انا بلوناهم کما بلونا اصحاب الجنة اذ اَقْسَموا لَیَصْرِمُنَّها مُصبحین (<span class=\"hlight\" dir=\"rtl\">١٧/٦٨</span>) آرد:... بیازمودیم ایشان را یعنی اهل مکه را چنانکه امتحان و ابتلا کردیم اهل آن بستان را یعنی اهل صروان (کذا به صاد مهمله ) را. ابوصالح گفت از عبداﷲ عباس، بستانی است در یمن آن را صروان خوانند پیش از صنعا به دو فرسنگ بر گذر آنانکه بصنعا روند و مردی را بود از اهل صلاح و نمازکن و عادت او آن بود که چون خرما خواستی بریدن هرچه از درخت بیفتادی درویشان را بودی و تا بر درخت بودی رهگذریان را منع نبودی و چون تمام بچیدی حق تمام بدرویشان دادی و خدای تعالی او را از برای آن برکت می داد، چون مُرد و از دنیا برفت سه پسر بود او را بمیراث به ایشان رسید با یکدیگر گفتندما این نتوانیم کرد که پدر ما کرد از آنکه یک نیمه از میوه ٔ این بستان کمابیش بدرویشان دادی که ما را عیال بسیار است و مال اندک راه برگرفتند برهگذران و چون وقت ارتفاع بود درویشان بعادت آمدند گفتند امروز و فردا وقت نیست هنوز. آنگه اتفاق کردند که شبی بروند و در شب برِ آن درختان باز کنند پنهان از درویشان و بر آن سوگند خوردند و استثنا نکردند آن شب که به این اتفاق کردند عذابی بیامد و آتشی و جمله ٔ درختان را با بَر بسوخت . خدای تعالی در این آیه قصه ٔ ایشان کرد <span class=\"hlight\">:</span> <br />قصه ٔ اصحاب ضَرْوان خوانده ای <br />پس چرا در حیله جوئی مانده ای .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(174308, 'ضروب', '<span class=\"hlight\">ضروب .</span> <font color=\"DarkGreen\"><b>[ ض ُ ]</font></b> (ع اِ) ج ِ ضرب . گونه ها. روشها. اقسام . انواع . اصناف <span class=\"hlight\">:</span> خلف بفنون زرق و ضروب حیل محاضران را تشویش می داد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٥٦</span>).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضروب اشکال قیاس </span> ؛ انواع اشکال قیاس .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضروب الامثال </span> ؛ علم ضروب الامثال . قال المیدانی ان عقود الامثال یحکم بأنها عدیمة اشباه و امثال تتحلی بفرائدها صدور المحافل و المحاضر و یتسلی بفوائدها قلب البادی و الحاضر و تقید اوابدها فی بطون الدفاتر و الصحائف و تطیر نواهضها فی رؤس الشواهق و ظهور المنایف و یحتاج الخطیب و الشاعر الی ادماجها و ادراجها لاشتمالها علی اسالیب الحسن و الجمال و کفی جلالة قدرها ان کتاب اﷲ سبحانه و تعالی لم یعر من وشاحها و ان کلام نبیه (ص ) لم یخل فی ایراده و اصداره من مثل یحوز قصب السبق فی حلبة الایجاز و امثال التنزیل کثیرة. و اما الکلام النبوی من هذا الفن فقد صنف العسکری فیه کتاباً برأسه من اوله الی آخره و من العلوم ان الادب سلم الی معرفة العلوم . به یتوصل الی الوقوف علیها و منه یتوقع الوصول الیها غیر ان له مسالک و مدارج و لتحصیله مراقی و معارج و ان علی تلک المراقی و اقصاها وادعر تلک المسائل و اعصاها هذه الامثال الواردة من کل مرتضع درر الفصاحة یانعاً و ولیداً فینطق بما یعبربه المعبر عنها حشواً فی ارتقاء معارج البلاغة و لهذا السبب خفی اثرها و ظهر اقلها و من حام حول حماها علم ان دون الوصول الیها احرق من خرط القتاد و ان لا وقوف علیها الا للکامل المعتاد کالسلف الماضین الذین نظموا من شملها ما تشتت و جمعوا من امرها ما تفرق فلم یبقوا فی قوس الاحسان منزعاً. (کشف الظنون ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضروب قیاس </span>؛ انواع قیاس .<br /></font></div>'),
(174309, 'ضروب', '<span class=\"hlight\">ضروب .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص ) بسیار زننده . یقال : رجل ٌ ضروب ؛ ای شدیدالضرب و کثیره . (منتهی الارب ).<br /></font></div>'),
(174310, 'ضروح', '<span class=\"hlight\">ضروح .</span> <font color=\"DarkGreen\"><b>[ ض ُ ]</font></b> (ع مص ) کاسد گردیدن بازار. (منتهی الارب ).<br /></font></div>'),
(174311, 'ضروح', '<span class=\"hlight\">ضروح .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص ) ستور لگدزن . (منتخب اللغات ). اسب لگدزن . (مهذب الاسماء). اسپ بسیار لگدزن . اسپ دست و پا زننده، یا عام است . <BR><font color=\"Blue\">◄</font> قوس ضروح ؛ کمان نیک دوراندازنده تیر را. (منتهی الارب ). کمان سخت که تیر را سخت جهاند. (منتخب اللغات ).<br /></font></div>'),
(174312, 'ضرور', '<span class=\"hlight\">ضرور.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص ) بایسته . واجب . لازم .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضرور بودن </span> ؛ بایستن . دربایستن . صاحب آنندراج گوید: مخفف ضرورة و بعضی مخفف ضروری گمان برده اند بمعنی ناگزیر، و با لفظ آمدن و بودن مستعمل <span class=\"hlight\">:</span><br />گاهی به درد دشمن و گاهی به داغ دوست <br />عمری چنین به حکم ضرور تو سوختم .<br /> <font color=\"Red\">بابافغانی .</font><br />بمجلس نوجوانان را کهن پیری ضرورآمد<br />مرارت دارد این معجون به تأثیری ضرور آمد.<br /> <font color=\"Red\">میر محمدعلی رائج .</font><br />از لطف توام هرچه ضرور است مهیاست <br />چیزی که من امروز ندارم غم فرداست .<br /><font color=\"Red\">شفیع اثر.</font><br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(174313, 'ضرورت', '<span class=\"hlight\">ضرورت .</span> <font color=\"DarkGreen\"><b>[ ض َ رو رَ ]</font></b> (ع اِ)ضرورة. نیاز و حاجت . (منتهی الارب ). حاجت . (منتخب اللغات ) <span class=\"hlight\">:</span> اکنون ضرورتی پیش آمده است . (کلیله و دمنه ). درویشی را ضرورتی پیش آمد کسی گفت فلان نعمتی دارد بی قیاس . (گلستان ). درویشی را ضرورتی پیش آمدگلیم یاری بدزدید. (گلستان ). <BR><font color=\"Blue\">◄</font> (اِمص ) بیچارگی . <BR><font color=\"Blue\">◄</font> درماندگی . (دهار) <span class=\"hlight\">:</span> <br />داد من امروز ده که روز ضرورت <br />یار نباشد که دست یار نگیرد.<br /> <font color=\"Red\">اوحدی .</font><br /> <BR><font color=\"Blue\">◄</font> ناگزیری . (دهار). ناچاری <span class=\"hlight\">:</span> من درایستادم و حال حسنک و رفتن بحج ... و خلعت مصریان ستدن و ضرورت را ستدن ... بتمامی شرح کردم . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٧٩</span>). چون از اخراجات و دخلها فرومانیم ضرورت را دست بمصادره ... و گرفتن ولایتها باید زد واز ما عیب نگیرند که بضرورت باشد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٦٠</span>). همچنین است که امیر می گوید این عجز باشد و ظاهر است اما ضرورت است . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٩٣</span>). خداوند ما راکشته اند و ما از بیم و ضرورت نزدیک شما آمده ایم . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٨٣</span>). مرا تیری رسید بضرورت بازگشتم و با دو اسب و غلامی بیست اینجا آمدم . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٥٥</span>). ترسم که از ضرورت بخراسان آید که شنوده باشد که کار بوقه و یغمر و کوکتاش و دیگران ... چه جمله است . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٥٣</span>). اگر یک باران آمدی امیر را باز بایستی گشت بضرورت که زمین آن نواحی با تنگی راه سست است . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٦٠</span>). اگر ما را حاجتمند نکردندی سوی خراسان بازگشتن را بضرورت، امروز بمصر و شام بودیمی . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٩٤</span>). چون سخنان مخالف به امیر رسانیدند و از غازی نیز خطا بضرورت ظاهر گشت ... بدگمان شد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٣٥</span>). و بضرورت بتوان دانست که از آن دو تن کدام کس را طاعت باید داشت . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٩٤</span>). لشکر قصد جان وی <font color=\"DarkGreen\"><b>[ غازی ]</font></b> کردند ناچار و بضرورت بجنگ بایستاد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٣٣</span>).<br />لیکن ز نزد تو بضرورت همی رَوَم <br />در شرع کارهای ضرورت بود روا.<br /> <font color=\"Red\">معزّی .</font><br />تا آخر روز بازرگان بضرورت از عهده ٔ مقرر بیرون آمد. (کلیله و دمنه ). بضرورت عزیمت مصمم گشت بر آنکه علماء هر صنف را ببینم . (کلیله و دمنه ). بضرورت زن در حیله ایستاد. (کلیله و دمنه ). از سر ضرورت روی از آن نواحی بتافت وبه غزنه آمد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٤٩</span>). از ضرورت اختناق فرا بند می شتافتم و بر وفق جذبه ٔ او می رفتم . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٢٨</span>). بحکم ضرورت سخن گفتیم وتفرج کنان بیرون رفتیم . (گلستان ). جوان را پشیزی نبود طلب کرد و بیچارگی نمود رحمت نیاوردند... بضرورت تنی چند را فروکوفت . (گلستان ).<br />که فردا چو پیک اجل دررسد<br />بحکم ضرورت زبان درکشی .<br /> <font color=\"Red\">سعدی .</font><br />چو خویشتن نتواند که می خورد قاضی <br />ضرورتست که بر دیگران بگیرد سخت <br />که گفت پیرزن از میوه می کند پرهیز<br />دروغ گفت که دستش نمی رسد بدرخت .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> بایستگی . دربایستن . دربایست . <BR><font color=\"Blue\">◄</font> ناکامی . (دهار). <BR><font color=\"Blue\">◄</font> بداهت . ضروری . غیرمحتاج به نظر و فکر.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بالضرورة</span> ؛ لاجرم . بضرورت . ناچار. بناچار.لابد. ناگزیر <span class=\"hlight\">:</span> خاصه که بضرورت غذا باز می باید گرفت . (ذخیره ٔ خوارزمشاهی ). ضرورةً. بناچار. اضطراراً. ناچار. صاحب کشاف اصطلاحات الفنون گوید: ضرورة، فی اللّغة الحاجة. و عند اهل السّلوک هی ما لا بدّ للانسان فی بقائه . و یسمّی حقوق النّفس ایضاً کما فی مجمعالسّلوک . و عند المنطقیّین عبارة عن استحالة انفکاک المحمول عن الموضوع سواء کانت ناشئة عن ذات الموضوع او عن امر منفصل عنها. فان ّ بعض المفارقات لو اقتضی الملازمة بین امرین یکون احدهما ضروریاً للآخَر فکان امتناع انفکاکه من خارج و المراد استحالة انفکاک نسبة المحمول الی الموضوع فتدخل ضرورة السّلب . و المعتبر فی القضایا الموجهة هی الضروریة بالمعنی المذکور. و قیل المعتبر فیها الضرورة بمعنی اخص من الاوّل .و هو استحالة انفکاک المحمول عن الموضوع لذاته . و الصحیح الاوّل و تقابل الضرورة اللاضرورة و هی الامکان والضرورة خمس : الاولی الضرورة الازلیة وهی الحاصلة ازلاً و ابداً. کقولنا: اﷲ تعالی عالم بالضرورة الازلیّة.و الازل دوام الوجود فی الماضی و الاَبَد دوامه فی المستقبل . و الثانیة الضّرورة الذاتیة ای الحاصلة مادامت ذات الموضوع موجودة و هی اما مطلّقة کقولنا: کل انسان حیوان بالضرورة او مقیدة بنفی الضرورة الازلیّة او بنفی الدوام الازلی . و المطلقة اعم ّ من المقیدة لان ّ المطلق اعم ّ من المقیّد و المقیدة بنفی الضرورة الازلیّة اعم من المقیّدة بنفی الدّوام الازلی . لان ّ الدّوام الازلی اعم من الضرورة الازلیّة فان ّ مفهوم الدوام شمول الازمنة. و مفهوم الضرورة امتناع الانفکاک و متی امتنع انفکاک المحمول عن الموضوع ازلاً و ابداً یکون ثابتاً له فی جمیع الازمنة ازلاً و ابداً بدون العکس فیکون نفی الضّرورة الازلیة اعم من نفی الدوام الازلی و المقیّد بالاعم ّ اعم من المقیّد بالاخص لانّه اذا صدق المقید بالاخص صدق المقیّد بالاعم و لاینعکس . و فیه ان هذا علی الاطلاق غیر صحیح فان ّ المقیّد بالقید الاعم انّما یکون اعم . اذا کان اعم مطلقاً من القیدین او مساویا للقید الاعم . اما اذا کان اخص من القیدین او مساویا للقید الاخص فهما متساویان او کان اعم منهما من وجه فیحتمل العموم و التساوی کما فیما نحن بصدده . و الضرورة الازلیة اخص من الضرورة الذاتیة المطلقة لان ّ الضرورة متی تحقّقت ازلاً و ابداً تتحقق مادام ذات الموضوع موجودة من غیر عکس . هذا فی الایجاب و امّا فی السّلب فهما متساویان لانّه متی سلب المحمول عن الموضوع مادامت ذاته موجودة یکون مسلوباً عنه ازلاً و ابداً، لامتناع ثبوته فی حال العدم و مباینة للاخیرین اما مباینتها للمقیدة بنفی الضرورة الازلیة فظاهر و اما مباینتها للمقید بنفی الدوام الازلی فللمباینة بین نقیض العام و عین الخاص . و الثالثة الضرورة الوصفیّة و هی الضرورة باعتبار وصف الموضوع و تطلق علی ثلاثة معان ؛ الضرورة مادام الوصف ای الحاصلة فی جمیع اوقات اتّصاف الموضوع بالوصف العنوانی کقولنا: کل انسان کاتب بالضرورة مادام کاتباً. والضرورة بشرط الوصف ای مایکون للوصف مدخل فی الضرورة کقولنا: کل کاتب متحرک الاصابع بالضرورة مادام کاتباً. والضرورة لاجل الوصف ای یکون الوصف منشاء الضرورة کقولنا: کل متعجب ضاحک بالضرورة مادام متعجباً. و الاولی اعم من الثانیة من وجه لتصادقهما فی مادة الضرورة الذاتیّة ان کان العنوان نفس الذات او وصفاً لازماً کقولنا: کل انسان او کل ناطق حیوان بالضرورة و صدق الاولی بدون الثانیة فی مادة الضرورة اذا کان العنوان وصفاً مفارقاً کما اذا بدل الموضوع بالکاتب و بالعکس فی مادة لایکون المحمول ضروریاً للذات بل بشرط مفارق کقولنا کل کاتب متحرک الاصابع. فان ّ تحرّک الاصابع ضروری لکل ما صدق علیه الکاتب بشرطاتصافه بالکتابة و لیس بضروری <font color=\"DarkGreen\"><b>[ الاّ ]</font></b> فی اوقات الکتابة فان ّ نفس الکتابة لیست ضروریة لما صدق علیه الکاتب فی اوقات ثبوتها، فکیف یکون تحرک الاصابع التّابعلها ضروریاً و کذا النسبة بین الاولی و الثالثة من غیر فرق و الثانیة اعم من الثالثة لأنّه متی کان الوصف منشاء الضرورة یکون للوصف مدخل فیها بدون العکس کما اذا قلنا فی الدّهن الحارّ بعض الحارّ ذائب بالضرورة فانّه یصدق بشرط وصف الحرارة و لایصدق لاجل الحرارةفان ّ ذات الدّهن لو لم یکن له دخل فی الذّوبان و کفی الحرارة فبه کان الحجر ذائباً اذا صار حارّاً. ثم الضرورة بشرط الوصف امّا مطلقة او مقیّدة بنفی الضرورة الازلیّة او بنفی الضرورة الذاتیّة او بنفی الدّوام الازلی او بنفی الدوام الذّاتی و القسم الاول اعم ّ من الاربعة الباقیة لأن ّ المطلق اعم ّ من المقید و الثانی اعم ّ من الثلاثة الباقیة لان ّ الضرورة الازلیة اخص من الضّرورة الذّاتیّة و الدّوام الازلی و الدّوام الذّاتی . فیکون نفیها اعم ّ من نفیهما و الثالث و الرّابعاعم من الخامس لأنّه متی صدقت الضرورة بشرط الوصف مع نفی الدّوام الذّاتی صدقت مع نفی الضرورة الذاتیة او مع نفی الدّوام الازلی و الاّ لصدقت مع تحققها فتصدق مع تحققها فتصدق مع تحقق الدّوام الذّاتی . هذا خلف . و لیس متی صدقت مع نفی الضرورة الذّاتیة او نفی الدوام الازلی صدقت مع نفی الدّوام الذّاتی لجواز ثبوته مع انتفائهما و بین الثّالث و الرابع عموم من وجه لتصادقهما فی مادّة لاتخلو عن الضرورة و الدوام و صدق الثالث فقط فی مادّة الدّوام المجرّد عن الضرورة و صدق الرّابع فقط فی مادّة الضرورة المجردة عن الدّوام الازلی و کذا بین الضّرورة بشرط الوصف و الضرورة الذاتیة اذ الضروریة قد لاتکون بشرط الوصف و قد تکون بشرط الوصف فتتصادقان اذا اتحد الوصف و الذّات و تصدق الضرورة المشروطة فقط ان کان الوصف مغایراً للذات . نعم، الضرورة مادام الوصف اعم ّ من الذّاتیة لأنّه متی ثبت فی جمیع اوقات الوصف ثبت فی جمیع اوقات الذّات بدون العکس . الرّابعة الضّرورة بحسب وقت اما معیّن کقولنا کل ّ قمر منخسف بالضرورة وقت الحیلولة و امّا غیر معیّن بمعنی ان التعیین لا یعتبر فیه لا بمعنی ان ّ عدم التعیین معتبر فیه کقولنا: کل انسان متنفّس بالضرورة فی وقت ما. و علی التقدیرین فهی امّا مطلقة و تسمی وقتیة مطلقة ان تعین الوقت و منتشرة مطلقة اِن لم یتعیّن . و امّا مقیدة بنفی الضرورة الازلیة او الذّاتیة او الوصفیة او بنفی الدّوام الازلی او الذّاتی اوالوصفی . فهذه اربعةعشر قسماً. و علی التقادیر فالوقت امّا وقت الذّات ای تکون نسبة المحمول الی الموضوع ضروریة فی بعض اوقات وجود ذات الموضوع و امّا وقت الوصف ای تکون النسبة ضروریة فی بعض اوقات اتصاف ذات الموضوع بالوصف العنوانی . کقولنا: کل ّ مغتذ نام فی وقت زیادة الغذاء علی بدل مایتحلل و کل ّ نام طالب للغذاء وقتاً ما من اوقات کونه نامیاً فالاقسام تبلغ ثمانیة و عشرین . و الضابطة فی النسبة ان ّ المطلق اعم ّ من المقیّد و المقیّد بالقید الاعم ّ اعم ّ و کُل ّ واحد من السبعة بحسب الوقت المعین اخص ّ من نظیره من السبعة بحسب الوقت الغیر المعین فان ّ کُل ّ مایکون ضروریاً فی وقت معین یکون ضروریاً فی وقت ما، من غیر عکس و کُل ّ واحد من الاربعة عشر بحسب وقت الذّات اعم ّ من نظیره من الاربعة عشر بحسب وقت الوصف . لان ّ وقت الوصف وقت الذّات من غیر عکس فکُل ّ ما هو ضروری ّ فی وقت الوصف فهو ضروری ّ فی وقت الذّات . و السِّرّ فی صیرورة ما لیس بضروری ّ ضروریاً فی وقت، ان الشّی ٔ اذا کان منتقلاً من حال الی حال آخر فربّما تؤدی تلک الانتقالات الی حالة تکون ضروریة له بحسب مقتضی الوقت . و من ههنا علم انه لابد ان یکون للوقت مدخل فی الضرورة و لذات الموضوع ایضاً کما ان للقمر مدخلاً فی ضرورة الانخساف فانّه لمّا کان بحیث یقتبس النّور من الشمس و تختلف تشکّلاته بحسب اختلاف اوضاعه منها، فلهذا او لحیلولةالارض وجب الانخساف . الخامسة الضرورة بشرط المحمول : وهی ضرورة ثبوت المحمول للموضوع او سلبه عنه بشرط الثّبوت او السلب . و لافائدة فیها لأن ّ کُل ّ محمول فهو ضروری ّ للموضوع بهذا المعنی . (فائدة) اذا قیل ضروریةاو ضروریة مطلقة او قیل کُل ّ «ج ب » بالضرورة و ارسلت غیر مقیدة بامر من الامور فعلی ایّة ضروریة تقال فقال الشیخ فی الاشارات علی الضرورة الازلیة. و قال فی الشفاء علی الضرورة الذاتیّة. و انّما لم یطلق الشّیخ الضرورة المطلقة علی غیرهما من الضرورات لأنّها مشتملة علی زیادة من الوصف و الوقت فهی کالجزء من المحمول . اعلم ان ّ ما ذکر من الضرورة و الامکان هی الّتی تکون بحسب نفس الامر و قد یکونان بحسب الذّهن و تسمی ضرورة ذهنیة و امکاناً ذهنیاً. فالضروریة الذّهنیة ما یکون تصور طرفیها کافیاً فی جزم العقل بالنسبة بینهما و الامکان الذهنی ما لایکون تصور طرفیه کافیاً فیه بل یتردد الذهن بالنسبة بینهما و الضرورة الذهنیة اخص ّ من الخارجیة لأن ّ کل نسبة جزم العقل بها بمجرّد تصور طرفیها کانت مطابقة لنفس الامر و الاّ ارتفع الامکان عن البدیهیات و لاینعکس ای لیس کلّما کان ضروریاً فی نفس الامر کان العقل جازماً به بمجرّد تصوّر طرفیه کما فی النظریات الحقة فیکون الامکان الذّهنی اعم ّ من الامکان الخارجی لأن ّ نقیض الاعم ّ اخص ّ من نقیض الاخص ّ.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضرورت شعری </span> ؛ صاحب کشاف اصطلاحات الفنون گوید: عبارتست از مراعات وزن شعر که برحسب ضرورت شاعر را به اموری بازدارد که انجام آن امور در نثر غیرجایز و در شعر روا باشد و آن امور نزد بیشتر از علماء فن ده چیز است که در این قطعه ٔ منسوب به زمخشری جمع آمده است . قطعه :<br />ضرورة الشعر عشر عد جملتها<br />قطعٌ و وصل ٌ و تخفیف ٌ و تشدید<br />مدّ وقصرٌ و اِسکان ٌ و تحریک ٌ<br />و منعُ صرف و صرف ٌ ثم ّ تعدیدُ.<br />پس قطع در همزه ٔ وصل باشد که اصل در آن پیوستگی به ماقبل است و آن پیوستگی هنگام ضرورت شعر بجدائی و قطع تبدیل می گردد، مانند همزه ٔ باب افتعال و غیره . وصل نیز مانند قطع در همزه قطع باشد که اصل در آن جدائی از ماقبل است و آن جدائی هنگام ضرورت شعریه به پیوستگی و وصل تبدیل می شود، مانند همزه ٔ باب اِفعال . وتخفیف نیز همچنان است در حرف مشدد و تشدید نیز همچنان باشد در حرف مخفف . و مدّ در الف مقصوره و قصر در الف ممدوده و اِسکان در حرف متحرک و تحریک در حرف ساکن و منع صرف در منصرف و صرف در غیرمنصرف . هکذا فی شروح الالفیة.<br /></font></div>'),
(174314, 'ضروری', '<span class=\"hlight\">ضروری .</span> <font color=\"DarkGreen\"><b>[ ض َ ری ی <span class=\"hlight\" dir=\"rtl\">/</span> ری ]</font></b> (از ع، ص نسبی ) منسوب به ضرور. لابد. لابُدّمنه . ناچار. ناگزیر.لاعلاج . بایسته . دربایست . بایا. اندربای <span class=\"hlight\">:</span> <br />چو نتوان به افلاک دست آختن <br />ضروری است با گردشش ساختن .<br /> <font color=\"Red\">سعدی .</font><br />خرسندی عاشقان ضروری باشد.<br /> <font color=\"Red\">سعدی .</font><br />و صاحب غیاث اللغات گوید منسوب به ضرورة است به حذف تاء. <BR><font color=\"Blue\">◄</font> بدیهی، مقابل نظری . صاحب کشاف اصطلاحات الفنون گوید: ضروری، لغة یطلق علی ما اکره علیه . و علی ما تدعو الحاجةالیه دعاءً قویاً. کالاکل ممّا یخمصه . و علی ما سلب فیه الاختیار علی الفعل و التّرک کحرکة المرتعش . و فی الجرجانی : الضرورة مشتقة من الضّرر و هو النّازل مما لا مدفع له . و فی الحموی، حاشیة الاشباه ههنا خمس مراتب ضرورة و حاجة و منفعة و زینة و فضول : فالضرورة بلوغه حدّاً ان لم یتناول الممنوع هلک او قارب الهلاک و هذا یبیح تناول الحرام . و الحاجة کالجائع الذی لو لم یجد ما یأکله لم یهلک غیر انّه یکون فی جهد و مشقة. و هذا لایبیح تناول الحرام و یبیح الفطر فی الصّوم . و المنفعة کالذی یشتهی خبز البرّ و لحم الغنم و الطعام الدسم و الزینة کالمشتهی بالحلوی و السکّر. و الفضول، التوسّع بأکل الحرام والشّبهة - انتهی . و فی عرف العلماء یطلق علی معان، منها: مقابل النظری ای الکسبی . فالمتکلّمون علی انّهما ای الضّروری و الکسبی قسمان للعلم الحادث . فعلم اﷲ تعالی لایوصف بضرورة ولا کسب . و المنطقیّون علی انهما قسمان، لمطلق العلم و علم اﷲ تعالی داخل عندهم فی الضروری، لعدم توقفه علی نظر. فعرفه القاضی ابوبکر من المتکلمین بانّه العلم الذی یلزم نفس المخلوق لزوماً لایجد المخلوق الی الانفکاک عنه سبیلاً. ای لزوماً لایقدر المخلوق الی الانفکاک عن ذلک العلم مطلقاً. ای لا بعد الحصول و لا قبله .فان ّ عدم القدرة من جمیع الوجوه اقوی و اکمل من عدمها من بعض الوجوه دون بعض . و لا یخفی ان المطلق ینصرف الی الفرد الکامل فخرج بهذا النّظری، فانه یقدر المخلوق علی الانفکاک عنه قبل حصوله، بان یترک النظر فیه و ان لم یقدر علی الانفکاک عنه بعد حصوله . و انّما صح ّ تفسیرنا قوله لایجد بقولنا لایقدر، لانک اذا قلت فلان یجد الی کذا سبیلاً، یفهم منه انّه یقدر علیه . و اذاقلت لایجد الیه سبیلاً، فهم منه انّه لایقدر علیه . و انّما اخترنا ذلک التفسیر لدفع ما اورد علی الحدّ من انّه یلزم خروج العلوم الضروریة باسرها. لأنّها تنفک بطریان اضداد العلم من النوم و الغفلة. و بفقد مقتضیه کالحس و الوجدان و التواتر و التجربة و توجّه العقل . فأن قلت الانفکاک مقدوراً کان او غیر مقدور ینافی اللزوم المذکور فی التّعریف فالایراد باق بحاله . قلت : المراد باللّزوم معناه اللّغوی . و هوالثبوت مطلقاً. ثم قیّده بکون الانفکاک عنه غیر مقدور فآخر کلامه تفسیر لاوله . و تلخیص التّعریف ما قیل : من ان ّ الضروری هو ما لایکون تحصیله مقدوراً للمخلوق . و لا شک انّه اذا لم یکن تحصیله مقدوراً لم یکن الانفکاک عنه مقدوراً و بالعکس . لانّه لامعنی للقدرة الا التمکن من الطرفین . فاذا کان التحصیل مقدوراً یکون ترکه الذی هو الانفکاک مقدوراً و کذا العکس، ای اذا کان الانفکاک مقدوراً یکون ترکه الذی هو التّحصیل مقدوراً. فمؤدّی العبارتین واحد. فمن الضّروریّات المحسوسات بالحواس ّ الظّاهرة. فانّها لا تحصل بمجرد الاحساس المقدور لنا. و الألما عرض الغلط. بل یتوقّف علی امور غیر مقدورة لانعلم ما هی و متی حصلت و کیف حصلت بخلاف النظریات فانّها تحصل بمجرد النّظر المقدور لنا. فان ّ حصولها دائر علی النظر وجوداً و عدماً فتکون مقدورة لنا. اذ لا معنی لمقدوریّة العلم الا مقدوریّة طریقه . و اذ لاینافی توقفها علی تصور الاطراف، فتدبر! فانّه زلّت فیه الاَ قدام . و منها المحسوسات بالحواس الباطنة، کعلم الانسان بالَمِه و لَذّته . و منها العلم بالامور العادیة. و منها العلم بالامور التی لاسبب لها و لایجد الانسان نفسه خالیة عنها. کعلمنا بان ّ النفی و الاثبات لایجتمعان و لایرتفعان . فان قلت اَ لیس ذلک العلم حاصلاً لنا بمجرّدالالتفات المقدور لنا فیکون مقدوراً. قلت الالتفات قدر مشترک بین جمیع العلوم . فلیس ذلک سبباً لحصوله . بل لخصوصیة الاطراف مدخل فیه . و معنی کون مجرّد الالتفات کافیاً فیه انّه لا احتیاج فیه الی سبب آخر، لأنّه سبب تام ّ. و النظری ّ هو العلم المقدور تحصیله بالقدرةالحادثة و القید الاخیر لاخراج العلم الضّروری . لأنّه مقدور التحصیل فینا بالقدرة القدیمة. و قال القاضی ابوبکر و امّا النظری، فهو ما یتضمّنه النظر الصحیح .قال الاَّمدی : معنی تضمّنه له انّهما بحال لو قدر انتفاء الاَّفات و اضداد العلم لم ینفک ّ النّظر الصّحیح عنه بلا ایجاب کما هو مذهب البعض و لا تولید کما هو مذهب بعض الاَّخر. فان ّ مذهب القاضی ان ّ حصوله عقیب النّظر بطریق العادة حال کون عدم انفکاک النّظر عنه مختصّاً حصولاً بالنّظر. فخرج العلم بالعلم بالشی ٔ الحاصل عقیب النّظر. فانّه غیر منفک عن العلم بالشّی ٔ عند القاضی . والعلم بالشّی ٔ عقیب النظر لا ینفک عن النّظر لکنّه لایکون له اختصاص بالنظر لکونه تابعاً للعلم بالشی ٔ سواء کان العلم بالشی ٔ حاصلاً بالنّظر او بدونه .ولا یخفی ان تضمّن الشّی ٔ للشی ٔ علی وجه الکمال انّما یکون اذا کان کذلک . فلایرد ان دلالة التضمّن علی القیدین خفیة. فمن یری ان الکسب لایمکن الاّ بالنّظر لأنّه لا طریق لنا الی العلم مقدور سواه، فان ّ الالهام و التعلیم لکونهما فعل الغیر غیر مقدورین لنا و کذلک التصفیة اذ المراد منه ان یکون مقدوراً للکل ّ او الاکثر.و التّصفیة لیس مقدوراً الا بالنسبة الی الاقل الذّی یفی مزاجه بالمجاهدات الشّاقة. فالنظری و الکسبی عنده متلازمان . فان ّ کُل ّ علم مقدور لنا یتضمّنه النظر الصحیح و کل ّ ما یتضمّنه النظر الصّحیح فهو مقدور لنا. و من یری جواز الکسب بغیر النظر بناء علی جواز طریق آخر مقدور لنا و ان لم نطّلع علیه جعله اخص ّ بحسب المفهوم من الکسبی . لکنه ای النّظری یلازم الکسبی ّ عادة بالاتفاق من الفریقین . اعلم ان الضّروری قد یقال فی مقابلة الاکتسابی و یفسّر بما لایکون تحصیله مقدوراً للمخلوق . ای یکون حاصلاً من غیر اختیار للمخلوق . و الاکتسابی هو ما یکون حاصلاً بالکسب و هو مباشرة الاسباب بالاختیار، کصرف العقل و النظر فی المقدمات فی الاستدلالیات و الاصغاء و تقلیب الحدقة و نحو ذلک فی الحسیات .فالاکتسابی اعم من الاستدلالی لأنه الذی یحصل بالنّظر فی الدّلیل فکل استدلالی اکتسابی دون العکس . کالابصار الحاصل بالقصد و الاختیار. و قد یقال فی مقابلة الاستدلالی و یفسّر بما یحصل بدون فکر و نظر فی دلیل فمن ههنا جعل بعضهم العلم الحاصل بالحواس اکتسابیاً ای حاصلاً بمباشرة الاسباب بالاختیار و بعضهم ضروریاً ای حاصلاً بدون الاستدلال . هکذا فی شرح العقائد النَسَفیّة للتفتازانی . و قال المنطقیون العلم بمعنی الصورة الحاصلة اما بدیهی ّ و هو الذی لم یتوقّف حصوله علی نظر و کسب و یسمی بالضروری ّ ایضاً و اما نظری ّ و هو الذی حصوله یتوقّف علی نظر و کسب ای البدیهی العلم الذی لم یتوقف حصوله المعتبر فی مفهومه فلایلزم ان یکون للحصول حصول و التوقف فی اللغة، درنگ کردن . فتعدیته بعلی یتضمن معنی الترتب فیفید قید التوقف انه لولاه لما حصل و قید الترتب التقدم فیؤول الی معنی الاحتیاج و لذاقیل الضروری ما لایحتاج فی حصوله الی نظر. فبالقید الاول دخل العلم الذی حصل بالنظر کالعلم بأن لیس جمیعالتصورات و التصدیقات بدیهیاً و لا نظریاً و بالقید الثانی العلم الضروری التابع للعلم النظری کالعلم بالعلم النظری فانه و ان کان یصدق علیه انه لولا النظر لما حصل، لکنه لیس مترتبا علی النظر علی العلم المستفاد من النظر. و ان المتبادر من الترتب الترتب بلا واسطة. و بما ذکرنا ظهر ان تعریفهما بما لایکون حصوله بدون النظر و الکسب و بما یکون حصوله به ینقصان طرداًو عکساً بالعلمین المذکورین فظهر انه لایرد علی التعریفین ان العلوم النظریة یمکن حصولها بطریق الحدس فلایصدق تعریف النظر علی شیی ٔ من افراده، لأنه انما یردلو فسر التوقف علی النظر بمعنی انه لولاه لامتنع العلم . اما اذا فسر بما ذکرنا اعنی لولاه لما حصل فلا. و تفصیل ذلک ان ّ طُرق العلم منحصرة بالاستقراء فی البداهة و الاحساس و التواتر و التجربة و الحدس فاذا کان حصوله بشی ٔ سوی النّظر لم یکن الناظر محتاجاً فی حصوله الی النظر و لایصدق انه لولاه لما حصل العلم و اذا لم یکن حصوله بما عداه کان فی حصوله محتاجا الیه و یصدق علیه انّه لولاه لما حصل العلم . ثم ّ ان ّ البدیهی و النظری یختلف بالنسبة الی الاشخاص فربما یکون نظری لشخص بدیهیاً لشخص آخر و بالعکس . فقید الحیثیة معتبر فی التعریف و ان لم یذکروا. و اما اختلافهما بالنسبة الی شخص واحد بحسب اختلاف الاوقات فمحل بحث، لأن الحصول معتبر فی مفهومهما اولا و هو بالنظر او بدونه . و بما حررنا اندفع الشکوک التی عرضت للناظرین، فتدبر.<br />(تنبیه ) قد استفید من تعریفی البدیهی و النظری المطلقین تعریف کل واحد من البدیهی و النظری من التصور و التصدیق . فالتصور البدیهی کتصور الوجود و الشی ٔ، و التصدیق البدیهی کالتصدیق بأن الکل اعظم من الجزء و التصور النظری کتصور حقیقة الملک و الجن و التصدیق النظری کالتصدیق بحدوث العالم . ثم التصدیق عند الامام لما کان عبارة عن مجموع الادراکات الاربعة فانما یکون بدیهیاً اذا کان کل واحد من اجزائه بدیهیاًو من ههنا تراه فی کتبه الحکمیة یستدل ببداهة التصدیقات علی بداهة التصورات و علی هذا ذهب البعض الی عدم جواز استناد العلم الضروری الی النظری و اما عند الحکیم فمناط البداهة و الکسب هو نفس الحکم فقط فان لم یحتج فی حصوله الی نظر یکون بدیهیاً و ان کان طرفاه بالکسب . و علی هذا ذهب البعض الی جواز استناد العلم الضروری الی النظری . هذا کله خلاصة ما فی شرح المواقف و ما حققه المولوی عبدالحکیم فی حاشیته و حاشیة شرح شمسیة و ما فی شرح المطالع. و علم من هذا انه لا فرق ههنا بین المتکلمین و المنطقیین الا بجعلهم الضروری و النظری من اقسام العلم الحادث و جعل المنطقیین الضروری و النظری من اقسام مطلق العلم و منها مرادف البدیهی بالمعنی الاخص علی ما ذکر المولوی عبدالحکیم ای بمعنی الاولی و یؤیده ما مر ان الضرورة الذّهنیة مایکون تصور طرفیها کافیاً فی جزم العقل بالنسبة بینهما علی ما ذکر شارح المطالع ثم قال فی آخر بحث الموجهات : البدیهی یطلق علی معنیین، احدهما ما یکفی تصور طرفیه فی الجزم بالنسبة بینهما و هو معنی الاولی . و الثانی ما لایتوقف حصوله علی نظر و کسب - انتهی . و منها الیقینی الشامل للنظری و الضروری . فالضروری علی هذا ما لا تأثیر لقدرتنا فی حصوله سواء کان حصوله مقدوراً لنا بأن یکون حصوله عقیب النظر عادة بخلق اﷲ تعالی لا بتأثیر قدرتنا فیه او لم یکن حصوله مقدوراً لنا و علی هذا قال الامام الرازی العلوم کلها ضروریة لأنها اما ضروریة ابتداء او لازمة لها لزوماً ضروریاً -انتهی . فان القسم الاول ای الضروری ابتداءً هو البدیهی و الضروری و القسم الثانی هو الکسبی . هکذا یستفادمن شرح المواقف و حاشیته للمولوی عبدالحکیم فی المقصد الرابع من مرصد العلم . <BR><font color=\"Blue\">◄</font> به اصطلاح اهل ایران متوضّاء و طهارت خانه و جای ضروری فارسیان هندوستان است و بس . (آنندراج ).<br /></font></div>'),
(174315, 'ضروریات', '<span class=\"hlight\">ضروریات .</span> <font color=\"DarkGreen\"><b>[ ض َ ری یا ]</font></b> (ع اِ) ج ِ ضروریة. دربایستها.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضروریات سته </span> ؛ قضایای یقینی ششگانه که مرجع امور نظری بوده و عبارتند از: اولیات، محسوسات، متواترات، مجربات، حدسیات و فطریات . و ضروریات ستة نزد اطبا، عبارت است از هوا و ماء و نوم و یقظه و مأکولات و مشروبات . (از تذکره ٔ داود ضریر انطاکی ).<br /></font></div>'),
(174316, 'ضروریة', '<span class=\"hlight\">ضروریة.</span> <font color=\"DarkGreen\"><b>[ ض َ ری ی َ ]</font></b> (ع ص نسبی ) تأنیث ضروری . ضروریه ٔ مطلقه، قضیه ٔ موجهه ای که در آن حکم بشود بضرورت نسبت ثبوتیه یا سلبیه بین موضوع و محمول مادام که ذات موضوع موجود است . صاحب کشاف اصطلاحات الفنون آرد: عند المنطقیین قضیة موجهة بسیطة حکم فیهابضرورة ثبوت المحمول للموضوع او بضرورة سلبه عنه مادام ذات الموضوع موجودة کقولنا کل انسان حیوان بالضرورة و لا شی ٔ من الانسان بحجر بالضروره . سمیت ضروریة لاشتمالها علی الضرورة و مطلقة لعدم تقیید الضرورة فیها بوصف او وقت . هکذا فی شرح المطالع. و سیدشریف جرجانی در تعریفات گوید: ضروریة المطلقة هی التی یحکم فیها بضرورة ثبوت المحمول للموضوع او بضرورة سلبه عنه مادام ذات الموضوع موجودة. اما التی حکم فیها بضرورةالثبوت فضروریة موجبة کقولنا کل انسان حیوان بالضرورة فان الحکم فیها بضرورة ثبوت الحیوان للانسان فی جمیع اوقات وجوده و اما التی حکم فیها بضرورة السلب فضروریة سالبة کقولنا: لا شی ٔ من الانسان بحجر بالضرورة سلب الحجر عن الانسان فی جمیع اوقات وجوده . سته ٔ ضروریه . رجوع به ترکیب ضروریات سته ذیل «ضروریات » شود.<br /></font></div>'),
(174317, 'ضروس', '<span class=\"hlight\">ضروس .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص ) شتر ماده ٔ بدخو گزنده دوشنده را. (منتهی الارب ). اشتر که دندان کُنَد دوشنده را. (مهذب الاسماء). ناقه که گاه دوشیدن بگزد. گزنده . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> ماده شتر که در نو زادن بگزد (؟). (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> آن کس که تیرهاء قمار بگرداند. <BR><font color=\"Blue\">◄</font> شدید. (مهذب الاسماء): حرب ضروس ؛ حرب مهلکة.<br /></font></div>'),
(174318, 'ضروس', '<span class=\"hlight\">ضروس .</span> <font color=\"DarkGreen\"><b>[ ض ُ ]</font></b> (اِخ ) ذوضروس ؛ لقب شمشیر ذی کنعان حمیری که در آن نوشته بود «انا ذوضروس قاتلت ُ عاداً وثمود باست من کنت ُ معه و لم ینتصر». (منتهی الارب ).<br /></font></div>'),
(174319, 'ضروس', '<span class=\"hlight\">ضروس .</span> <font color=\"DarkGreen\"><b>[ ض ُ ]</font></b> (ع اِ) ج ِ ضِرس . (منتهی الارب ).<br /></font></div>'),
(174320, 'ضروط', '<span class=\"hlight\">ضروط.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص ) مرد گوززن . تیزدهنده . ضِرّوط. (منتهی الارب ).<br /></font></div>'),
(174321, 'ضروط', '<span class=\"hlight\">ضروط.</span> <font color=\"DarkGreen\"><b>[ ض ِرْ رو ]</font></b> (ع ص ) گوززن . تیزدهنده . ضَروط. (منتهی الارب ).<br /></font></div>'),
(174322, 'ضروط', '<span class=\"hlight\">ضروط.</span> <font color=\"DarkGreen\"><b>[ ض ِرْ رو ]</font></b> (ع ص ) تندار. ضخم . یقال : انه لضرّوط. (منتهی الارب ).<br /></font></div>'),
