(174596, 'ضمر', '<span class=\"hlight\">ضمر.</span> <font color=\"DarkGreen\"><b>[ ض ُ <span class=\"hlight\" dir=\"rtl\">/</span> ض ُ م ُ ]</font></b> (ع مص ) دوسیدن شکم بپشت . چسبیدن شکم بپشت . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> باریک میان شدن . باریک میان شدن اسب . (زوزنی ).<br /></font></div>'),
(174597, 'ضمران', '<span class=\"hlight\">ضمران .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (اِخ ) وادئی است به نجد. (منتهی الارب ) (منتخب اللغات ). نصر گوید: ضمران بضم ضاد و فتح، آن وادئی است بنجد از بطن قوّ. (معجم البلدان ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ذوالضمران </span> ؛ موضعی است . (معجم البلدان ).<br /></font></div>'),
(174598, 'ضمران', '<span class=\"hlight\">ضمران .</span> <font color=\"DarkGreen\"><b>[ ض ُ ]</font></b> (اِخ ) سگی است، یا ماده سگی . (منتهی الارب ). نام سگی است . (مهذب الاسماء).<br /></font></div>'),
