(174600, 'ضمرز', '<span class=\"hlight\">ضمرز.</span> <font color=\"DarkGreen\"><b>[ ض َ رَ ]</font></b> (ع اِ) شیربیشه . <BR><font color=\"Blue\">◄</font> زمین سخت درشت . (منتهی الارب ).<br /></font></div>'),
(174601, 'ضمرز', '<span class=\"hlight\">ضمرز.</span> <font color=\"DarkGreen\"><b>[ ض ِ رِ ]</font></b> (ع ص ) ناقه ٔ کلان سال . ناقه ٔ کلان سال کم شیر قوی . (منتهی الارب ). اشتر قوی . (مهذب الاسماء).<br /></font></div>'),
(174602, 'ضمروط', '<span class=\"hlight\">ضمروط.</span> <font color=\"DarkGreen\"><b>[ ض ُ ]</font></b> (ع اِ) پوشیدنگاه . جای تنگ و پنهان . (منتهی الارب ). تنگنای .<br /></font></div>'),
(174603, 'ضمری', '<span class=\"hlight\">ضمری .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (اِخ ) شاعری عرب، معاصر معن بن زائدة. (الموشح مرزبانی ص <span class=\"hlight\" dir=\"rtl\">٢٥٤</span>).<br /></font></div>'),
(174604, 'ضمری', '<span class=\"hlight\">ضمری .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (اِخ )رجوع به عمروبن امیة شود. (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤١</span>).<br /></font></div>'),
(174605, 'ضمز', '<span class=\"hlight\">ضمز.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) خاموش ماندن و حرفی نزدن . (منتهی الارب ). خاموش شدن . (زوزنی ). خاموش بودن . (تاج المصادر). سخن ناگفتن وخاموش بودن . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> فروبردن لقمه را. <BR><font color=\"Blue\">◄</font> نگاه داشتن شتر دبه را در دهن و نشخوار ناکردن آن . (منتهی الارب ). نشخور باززدن شتر را (؟). (تاج المصادر). <BR><font color=\"Blue\">◄</font> برچفسیدن بچیزی و لازم گرفتن آن را و قیام و ثبات ورزیدن بر آن . (منتهی الارب ). چسبیدن بچیزی . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> حریصی و آزمندی کردن بر چیزی . (منتهی الارب ).<br /></font></div>'),
(174606, 'ضمز', '<span class=\"hlight\">ضمز.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص، اِ) جای درشت . <BR><font color=\"Blue\">◄</font> پشته ٔ دشوارگذار. <BR><font color=\"Blue\">◄</font> پشته ٔپست . <BR><font color=\"Blue\">◄</font> هر کوه جداگانه که در آن سنگ سرخ و سخت باشد و در آن خاک و گل نبود. (منتهی الارب ).<br /></font></div>'),
(174607, 'ضمزر', '<span class=\"hlight\">ضمزر.</span> <font color=\"DarkGreen\"><b>[ ض ِزِ ]</font></b> (ع ص ) شتر ماده ٔ توانا و قوی . (منتهی الارب ).<br /></font></div>'),
(174608, 'ضمزر', '<span class=\"hlight\">ضمزر.</span> <font color=\"DarkGreen\"><b>[ ض َ زَ ]</font></b> (ع ص ) زمین سخت . <BR><font color=\"Blue\">◄</font> زن درشت . <BR><font color=\"Blue\">◄</font> (اِ) شیر بیشه . <BR><font color=\"Blue\">◄</font> (اِخ ) شترماده ای است . (منتهی الارب ).<br /></font></div>'),
(174609, 'ضمس', '<span class=\"hlight\">ضمس .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) آهسته و نرم خائیدن . (منتهی الارب ). جاویدن خفیه و پنهان . (منتخب اللغات ).<br /></font></div>'),
(174610, 'ضمس', '<span class=\"hlight\">ضمس .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص ) دشوار و سخت . (منتهی الارب ).<br /></font></div>'),
(174611, 'ضمضام', '<span class=\"hlight\">ضمضام .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص ) آنکه فراهم آورد و احاطه کند هر چیز را. (منتهی الارب ).چیزی که بر چیز دیگر مشتمل باشد. (منتخب اللغات ).<br /></font></div>'),
(174612, 'ضمضم', '<span class=\"hlight\">ضمضم .</span> <font color=\"DarkGreen\"><b>[ ض ُ م َ ض ِ ]</font></b> (ع ص ) ضُماضم . شیر خشم آلود ودلیر. شیر که آمیزد هر چیز را (؟). (منتهی الارب ).<br /></font></div>'),
(174613, 'ضمضم', '<span class=\"hlight\">ضمضم .</span> <font color=\"DarkGreen\"><b>[ ض َ ض َ ]</font></b> (ع ص ) مرد خشمناک . (منتهی الارب ). خشمگین . ج، ضماضم . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> شیر خشم آلود. <BR><font color=\"Blue\">◄</font> مرد تندار آمیزنده هر چیز را. (منتهی الارب ).<br /></font></div>'),
(174614, 'ضمضم', '<span class=\"hlight\">ضمضم .</span> <font color=\"DarkGreen\"><b>[ض َ ض َ ]</font></b> (اِخ ) ابن جوس . تابعی است . (منتهی الارب ).<br /></font></div>'),
(174615, 'ضمضم', '<span class=\"hlight\">ضمضم .</span> <font color=\"DarkGreen\"><b>[ ض َ ض َ ]</font></b> (اِخ ) ابن حارث . صحابی است . (منتهی الارب ).<br /></font></div>'),
(174616, 'ضمضم', '<span class=\"hlight\">ضمضم .</span> <font color=\"DarkGreen\"><b>[ ض َ ض َ ]</font></b> (اِخ ) ابن عمرو غفاری . از یاران ابوسفیان است . صاحب کتاب حبیب السیر در سبب غزوه ٔ بدر گوید : هنگامی که ابوسفیان با قریشیان و اموال فراوان از شام بازگشته متوجه مکه ٔ مکرمه بودند، حضرت رسول با سیصدوپنج نفر از اصحاب که از آن جمله هشتاد کس از مهاجر و باقی از انصار بودند و هفتاد شتر و دو یا سه اسب و شش زره و هشت شمشیر داشتندبعزیمت گرفتن سر راه کاروان در دوازدهم یا ششم یا سیُم ماه مبارک رمضان از مدینه ٔ طیبه روان شدند. ابوسفیان از این واقعه آگاهی یافته ضمضم غفاری را روانه کرد تا از قریش استمداد کند. چون ضمضم به حریم رسید و پیغام ابوسفیان به قوم رسانید اکثر اکابر و اصاغر قریش تهیه ٔ اسباب سفر کرده نهصدوپنجاه نفر از مشرکان متوجه حرب پیغمبر گشتند و در میان ایشان هفتصد شتر و صد سر اسب بود و مجموع سواران و بعضی از پیادگان زره داشتند... صاحب امتاع الاسماع گوید: «... فادرکهم (ای ادرک عیر قریش ) رجل ٌ من جذام بالزرقاء من ناحیة معان و هم منحدرون الی مکة. فاخبرهم ان محمداً صلی اﷲ علیه و سلم قد کان عرض لعیرهم فی بدأتهم و انه ترکه مقیماً ینتظر رجعتهم و قد حالف علیهم اهل الطریق و وادعهم . فخرجوا خائفین الرصد و بعثوا ضمضم بن عمرو حین فصلوا من الشام و کانوا قد مروا به و هو بالساحل معه بکران فاستأجروه بعشرین مثقالاً و امره ابوسفیان صخربن حرب بن امیة ان یخبر قریشاً ان محمداً قد عرض لعیرهم و امره ان یجدع بعیره اذا دخل مکة و یحول رحله و یشق قمیصه من قبله و دبره و یصیح : الغوث الغوث، و یقال بعثوه من تبوک . و کان فی العیر ثلاثون رجلاً من قریش فیهم عمروبن العاص و مخرمةبن نوفل فلم یرع اهل مکة الا و ضمضم یقول : یا معشر قریش، یا آل لوی بن غالب اللطیمة، قد عرض لها محمد فی اصحابه، الغوث الغوث !و اﷲ ما اری ان تدرکوها. و قد جدّع اذنی بعیره، و شق قمیصه، و حول رحله، فلم تملک قریش من امرها شیئاً حتی نفروا علی الصّعب و الزلول، و تجهزوا فی ثلاثة ایام، و یقال فی یومین، و اعان قویهم ضعیفهم ...». آنگاه درباره ٔ خواب دیدن عاتکة و ضمضم آرد: «... و رأی ضمضم بن عمرو ان وادی مکة یسیل دماً من اسفله و اعلاه ورأت عاتکة بنت عبدالمطلب رؤیاها التی ذکرت فی ترجمتها...». رجوع به امتاع الاسماع ص <span class=\"hlight\" dir=\"rtl\">٦٦</span>، <span class=\"hlight\" dir=\"rtl\">٦٨</span> و <span class=\"hlight\" dir=\"rtl\">٦٩</span> شود.<br /></font></div>'),
(174617, 'ضمضم', '<span class=\"hlight\">ضمضم .</span> <font color=\"DarkGreen\"><b>[ ض َ ض َ ]</font></b> (اِخ ) ابن قتادة. صحابی است . (منتهی الارب ).<br /></font></div>'),
(174618, 'ضمضم', '<span class=\"hlight\">ضمضم .</span> <font color=\"DarkGreen\"><b>[ ض َ ض َ ]</font></b> (اِخ ) ابوالحصین المرّی . مردی از عرب که در یوم المریقب به دست عنترة الفوارس کشته شد. (عقد الفرید ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">١٩</span> و <span class=\"hlight\" dir=\"rtl\">٢٠</span> و <span class=\"hlight\" dir=\"rtl\">٢٥</span>).<br /></font></div>'),
(174619, 'ضمضم', '<span class=\"hlight\">ضمضم .</span> <font color=\"DarkGreen\"><b>[ ض َ ض َ ]</font></b> (اِخ ) الاملوکی، مکنی به ابوالمثنی . تابعی است و صفوان بن عمرو از او روایت کند.<br /></font></div>'),
(174620, 'ضمضم', '<span class=\"hlight\">ضمضم .</span> <font color=\"DarkGreen\"><b>[ ض َ ض َ ]</font></b> (اِخ ) مدینی . یکی از بطالین معروف، و بنام او کتابی کرده اند. (ابن ندیم ).<br /></font></div>'),
(174621, 'ضمضمة', '<span class=\"hlight\">ضمضمة.</span> <font color=\"DarkGreen\"><b>[ ض َ ض َ م َ]</font></b> (ع مص ) شجاع کردن دل خود را. <BR><font color=\"Blue\">◄</font> گرفتن همه را. <BR><font color=\"Blue\">◄</font> بانگ زدن شیر. (منتهی الارب ).<br /></font></div>'),
(174622, 'ضمعج', '<span class=\"hlight\">ضمعج .</span> <font color=\"DarkGreen\"><b>[ ض َ ع َ ]</font></b> (ع ص ) زن فربه تمام بدن پرگوشت . (منتهی الارب ). زنی تمام خلق . (مهذب الاسماء). زن درشت پست بالا. <BR><font color=\"Blue\">◄</font> شتر فربه تمام بدن پرگوشت . (منتهی الارب ). ماده اشتر بزرگ . (مهذب الاسماء). ناقه ٔ بزرگ . (فهرست مخزن الادویة). اشتر جوان . (مهذب الاسماء).<br /></font></div>'),
(174623, 'ضمن', '<span class=\"hlight\">ضمن .</span> <font color=\"DarkGreen\"><b>[ ض ِ ]</font></b> (ع اِ) ضمن الکتاب ؛ طی آن است . گویند: کان ذلک فی ضمنه ؛ ای طیّه . (منتهی الارب ). شکن و نورد کتاب و جز آن . (منتخب اللغات ). اندرون . (غیاث ) <span class=\"hlight\">:</span> و رهینه ٔ دوام ملک در ضمن آن به دست آید. (کلیله و دمنه ). عتبی می گوید و آن رساله را به اشارت سلطان در ضمن شرح حال امیر نصر ثبت کردم . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٤٢</span>).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضمناً</span> ؛ در ضمن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضمن اللفظ</span> ؛ صنعتی است در شعر که از میان لفظی، لفظ دیگر مذکور سازند، چنانکه در این بیت :<br />تو بی نظیر جهانی و من نظر نکنم <br />بجانبی که ندارد رخ تو تاب نظر.<br /> <font color=\"Red\">؟ (از آنندراج و غیاث ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضمن صحبت </span> ؛ در میان سخن . در اثناء کلام .<br /></font></div>'),
(174624, 'ضمن', '<span class=\"hlight\">ضمن .</span> <font color=\"DarkGreen\"><b>[ ض َ م َ ]</font></b> (ع مص ) بر جای ماندن و عاجز شدن . (منتهی الارب ). بر جای ماندن . (منتخب اللغات ). برجاماندگی . (منتهی الارب ) ( منتخب اللغات ). زمین گیری . <BR><font color=\"Blue\">◄</font> پذیرفتن چیزی را. (منتهی الارب ).<br /></font></div>'),
(174625, 'ضمن', '<span class=\"hlight\">ضمن .</span> <font color=\"DarkGreen\"><b>[ ض َ م ِ ]</font></b> (ع ص ) عاشق .(منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> بیمار در جای بمانده . زمینگیر. ج، ضُمَنی ̍. (مهذب الاسماء). برجای مانده و مبتلی شده ٔ بمرض . (منتخب اللغات ). برجای مانده و مبتلی در عاهت بدنی، و فی الحدیث <span class=\"hlight\">:</span> مَن اَکتب ضمناً بعثه اﷲ ضمناً؛ ای من کتب نفسه فی دیوان الضمنی او الزمنی لیعذر عن الجهاد بعث کذلک .<br /></font></div>'),
(174626, 'ضمنة', '<span class=\"hlight\">ضمنة.</span> <font color=\"DarkGreen\"><b>[ ض ُ ن َ ]</font></b> (ع اِمص ) بیماری . برجاماندگی از مرض . گویند: به ضمنة؛ ای زمانة، و کانت ضمنة فلان اربعة اشهر. (منتهی الارب ).<br /></font></div>'),
(174627, 'ضمور', '<span class=\"hlight\">ضمور.</span> <font color=\"DarkGreen\"><b>[ ض ُ ]</font></b> (ع مص ) لاغر گردیدن . (منتهی الارب ). باریک میان شدن . (دهار) (تاج المصادر). باریک میان شدن اسب . (زوزنی ). سبک گوشت شدن . (منتهی الارب ).<br /></font></div>'),
(174628, 'ضمور', '<span class=\"hlight\">ضمور.</span> <font color=\"DarkGreen\"><b>[ ض ُ ]</font></b> (ع اِمص ) لاغری . نزاری . هزال و ضعف . (بحر الجواهر). ذبول .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضمور عضوی </span> ؛ اطروفیا .<br /></font></div>'),
(174629, 'ضمور', '<span class=\"hlight\">ضمور.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص ) لاغر. (غیاث ) (آنندراج ).<br /></font></div>'),
(174630, 'ضموز', '<span class=\"hlight\">ضموز.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص ) خاموش . <BR><font color=\"Blue\">◄</font> هر کوه جداگانه که سنگهایش سرخ و سخت باشد و گل و خاک نبود در آن . <BR><font color=\"Blue\">◄</font> (اِ) شیر بیشه . (منتهی الارب ).<br /></font></div>'),
(174631, 'ضموم', '<span class=\"hlight\">ضموم .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ) هر رودباری که میان دو پشته ٔ بلند و دراز جاری باشد. (منتهی الارب ).<br /></font></div>'),
(174632, 'ضمی', '<span class=\"hlight\">ضمی .</span> <font color=\"DarkGreen\"><b>[ ض َم ْی ْ ]</font></b> (ع مص ) ستم کردن . (منتهی الارب ).<br /></font></div>'),
(174633, 'ضمیر', '<span class=\"hlight\">ضمیر.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ) درون دل . (منتخب اللغات ). اندرون دل . درون . باطن انسان .طَویّت . دل . (مهذب الاسماء ). ج، ضمائر <span class=\"hlight\">:</span> <br />آنچه بعلم تواندر است گر آنرا<br />گرد ضمیر اندر آوریش چو پرهون .<br /> <font color=\"Red\">دقیقی .</font><br />چون می خورم به ساتگنی یاد او خورم <br />وز یاد او نباشد خالی مرا ضمیر.<br /> <font color=\"Red\">عماره .</font><br />این بود ملک را بجهان وقتی آرزو<br />این بود خلق را همه همواره در ضمیر.<br /> <font color=\"Red\">فرخی .</font><br />زیرا که میرداند در فضل او تمام <br />ما را به فضل او نرسد خاطر و ضمیر.<br /> <font color=\"Red\">منوچهری .</font><br />خدای عز و جل تواند دانست ضمیر بندگان . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٥</span>).<br />مقرم بمرگ و بحشر و حساب <br />کتابت ز بر دارم اندر ضمیر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />چون ضمیر عاشقان شد روی خاک <br />از جهان برخاست جغد قیرفام .<br /> <font color=\"Red\">ناصرخسرو.</font><br />وز آن گشت تیره دل ِ مرد نادان <br />کز اوی است روشن به جان در ضمیرم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />خدای جل جلاله در ازل بعلم قدیم دانسته بود اما خلقان از ضمیر دل او <font color=\"DarkGreen\"><b>[ شیطان ]</font></b> آگاه نبودند. (قصص الانبیاء ص <span class=\"hlight\" dir=\"rtl\">١٨</span>). هیچ چیز نگشاد که ضمیر اهل خرد آن را قبول کردی . (کلیله و دمنه ). چون محاسن صلاح بر این جمله در ضمیر متمکن شد خواستم تا بعبادت متحلی گردم . (کلیله و دمنه ). نه در ضمیر ضعیفان آزاری صورت بندد و نه گردنکشان را مجال تمرد باقی ماند. (کلیله و دمنه ).<br />درحال بگوش هوش من گفت <br />وصف تو که با ضمیر شد ضم .<br /> <font color=\"Red\">خاقانی .</font><br />آن دید ضمیرم از ثنایت <br />کز نیسان بوستان ندیده ست .<br /> <font color=\"Red\">خاقانی .</font><br />سخن که خیمه زند در ضمیر خاقانی <br />طناب او همه حبل اللَّه آید از اطناب .<br /> <font color=\"Red\">خاقانی .</font><br />از روشنی ّ او نزدی کس بدو مثل <br />گر در ضمیر تو نشدی مضمر آفتاب .<br /> <font color=\"Red\">خاقانی .</font><br />نه آنچنان بتو مشغولم ای بهشتی روی <br />که یاد خویشتنم در ضمیر می آید.<br /> <font color=\"Red\">سعدی (گلستان ).</font><br />سخنی کآن ز اهل درد آید<br />همچو جان در ضمیر مرد آید.<br /> <font color=\"Red\">اوحدی .</font><br />تا ضمیری است مر مرا بنظام <br />تا زبانیست مر مرا گویا.<br /> <font color=\"Red\">؟</font><br /> <BR><font color=\"Blue\">◄</font> نهانی . نهفته . (منتهی الارب ) <span class=\"hlight\">:</span> <br />چند صیادی سوی آن آبگیر<br />برگذشتند و بدیدند آن ضمیر.<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> نهان . نهفت <span class=\"hlight\">:</span> در ضمیر زمانه تقدیرها بوده است . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٧٣</span>). <BR><font color=\"Blue\">◄</font> چیزی مُضمَر. آنچه در دل گیرند. (مهذب الاسماء). آنچه در دل باشد <span class=\"hlight\">:</span> <br />همی به وصف تو جنبد ضمیرم اندر دل <br />همی به مدح تو گردد زبانم اندر فم .<br /> <font color=\"Red\">مسعودسعد.</font><br />راز. (منتخب اللغات ) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> یاد. <BR><font color=\"Blue\">◄</font> اندیشه . (دهار) (نصاب ). فکرت . فکر. (نصاب ). ج، ضمائر <span class=\"hlight\">:</span> <br />پی ثنای محمد برآر تیغ ضمیر<br />که خاص بر قد او بافتند درع ثنا.<br /> <font color=\"Red\">خاقانی .</font><br />قول و فعل آمد گواهان ضمیر<br />زین دو بر باطن تو استدلال گیر.<br /> <font color=\"Red\">مولوی .</font><br />قول و فعل و ضمیر چون شد راست <br />اختلافی نماند اندر خواست .<br /> <font color=\"Red\">اوحدی .</font><br /><BR><font color=\"Blue\">◄</font> آن است که چیزی اندیشد و پیدا کند به سؤال . (التفهیم، در احکام نجوم ). <BR><font color=\"Blue\">◄</font> وجدان . قوه ای است ممیزه که خیر را از شر و صحیح را از فاسد تمیز دهد و شریعت قلبیه ٔ مکتوبه ٔ الهیه که در تمام افراد بنی نوع بشر مودوع است عبارت از همین قوه است که بر اعمال و اقوال ما حکم کرده شکایت و حجت بر ما وارد آورد و عموم بنی نوع بشر را ضمیر هست . (قاموس مقدس ). <BR><font color=\"Blue\">◄</font> (اصطلاح نحو و دستور زبان فارسی ) عبارت از چیزی است که جای ظاهر گیرد، مانند «من » که بدل از محدث عنه است . ضمیر اسمی است وضعشده برای معنی کلی که شامل افراد بسیار می باشد واستعمال شود در معنی جزئی بقرینه ٔ خطاب و بجای اسم ظاهر استعمال شود چه از تکرار اسم ظاهر کلام از پایه ٔفصاحت بیفتد و چون تعلق کلام از متکلم باشد یا از مخاطب و یا غائب ضمائر نیز به سه قسم منقسم شوند: اول ضمیری که برای متکلم استعمال شود. دوم ضمیری که برای مخاطب استعمال شود. سوم ضمیری که برای غائب بکار رود، و هر یک از این نوع ضمایر یا متصل است و یا منفصل . ضمیر متصل آن است که بذات خود غیرمستقل باشد، یعنی تا وقتی که بماقبل خود متصل نشود در تلفظ نیاید، و این نیز دو قسم است : بارز و مستتر. ضمیر بارز آن است که برای وی در فعل حرفی و کلمتی مذکور شود و مستتر آن است که در فعل حرفی و کلمتی وی را مذکور نیفتد. اما ضمیر منفصل آن است که در تلفظ محتاج به اتصال با ماقبل خود نبود و بذات خود کلمه ای جداگانه باشد، چون من و تو و او و غیره . هریک از ضمایر متصله و منفصله را در حالات رفع و نصب و جر یا فاعلی و مفعولی و مضاف ٌالیهی حروف و الفاظی است، چنانکه الفاظ ضمایر فاعلی اینست : من، تو، او، ما، شما، ایشان ... الخ . (نهج الادب ). ضمیر اسمی است که بطور کنایه و اشاره بر متکلم و غائب یا مخاطب دلالت کند، و آن یا متصل است و یا منفصل . ضمیر منفصل آن است که خود کلمه ٔ مستقل باشد و به تنهائی گفته شود. ضمیر متصل آن است که به تنهائی گفته نشود بلکه چسبیده بکلمات دیگر و بمثابه ٔ جزئی از او باشد. ضمیر منفصل در عربی دو نوع الفاظ دارد، الفاظی که در موقع رفع استعمال شود و الفاظی که در موقع نصب استعمال شود، مثل هو، هما... الخ و ایاه، ایاهما... الخ . ضمیر متصل نیز دو گونه الفاظ دارد: اول الفاظی که تنها به فعل می چسبند و صیغه های ماضی و مضارع و امر بوسیله ٔ آنها تشخیص داده می شود و تعداد آنها یازده است : ا، و، ن، ت، تُما، تم، تُن ّ، نا، ی . دوم الفاظی که بهر سه قسم کلمه، اسم و فعل و حرف می پیوندد مانند: اُمّه، اَمره، له . <BR><font color=\"Blue\">◄</font> انگور پژمریده . ج، ضمائر. (منتهی الارب ).<br /></font></div>'),
(174634, 'ضمیر', '<span class=\"hlight\">ضمیر.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (اِخ ) شهری است به شحر از اعمال عمان نزدیک دغوث . (معجم البلدان ).<br /></font></div>'),
(174635, 'ضمیر', '<span class=\"hlight\">ضمیر.</span> <font color=\"DarkGreen\"><b>[ ض ُ م َ ]</font></b> (اِخ ) موضعی است نزدیک دمشق و گویند آن قریه و حصنی است در آخر آن قسمت از حدود دمشق که نزدیک سماوة است . (معجم البدان ).<br /></font></div>'),
(174636, 'ضمیر', '<span class=\"hlight\">ضمیر.</span> <font color=\"DarkGreen\"><b>[ ض ِم ْ می ]</font></b> (ع اِ) نهانی . <BR><font color=\"Blue\">◄</font> راز. (منتهی الارب ). نهفت .<br /></font></div>'),
(174637, 'ضمیر', '<span class=\"hlight\">ضمیر.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (اِخ ) تقی الدین . شاعر ایرانی . نخست شغل حلوافروشی داشت، سپس بهندوستان رفت و توانگر گشت . این بیت او راست :<br />بیستون را چون در خیبر به زور تیشه کند<br />عشق رنگ حیدری بر بازوی فرهاد بست .<br /><font color=\"Red\">(از قاموس الاعلام ترکی ).</font><br /></font></div>'),
(174638, 'ضمیر', '<span class=\"hlight\">ضمیر.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (اِخ ) کنورهیرالال بن راجه پباری لال . شاعر هندی و از رؤسای براهمه است . این بیت او راست :<br />از سینه ٔ سوزان بفلک ناله فرستم <br />وز دیده ٔ گریان بزمین ژاله فرستم .<br /><font color=\"Red\">(از قاموس الاعلام ترکی ).</font><br /></font></div>'),
(174639, 'ضمیر', '<span class=\"hlight\">ضمیر.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (اِخ ) همدانی . شاعر. اوراست منظومه ٔ شمع و پروانه . (کشف الظنون ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٠</span>).<br /></font></div>'),
(174640, 'ضمیران', '<span class=\"hlight\">ضمیران .</span> <font color=\"DarkGreen\"><b>[ ض َ <span class=\"hlight\" dir=\"rtl\">/</span> ض ُ م َ <span class=\"hlight\" dir=\"rtl\">/</span> ض َم ْ ی َ ]</font></b> (ع اِ) اسم عربی شاهسفرم است . (فهرست مخزن الادویه ). سپرغم که آن را ریحان و نازبو نیز گویند. (غیاث ) (آنندراج ). آن را ضیمران نیز گویندو شاه اسفرم شیرازی خوانند. آن سبز بود، و صاحب جامعکه گوید فودنج جویی است سهو کرده است . و طبیعت وی گرم و خشک بود در دوم و گویند سرد بود و محروری مزاج را نافع بود خاصه چون گلاب بر وی زنند و بر جائی که سوخته باشد ضماد کنند نافع بود و قلاع زایل کند. (اختیارات بدیعی ). در عرب شاهسفرم را ضمیران گویند. ارجانی گوید که شاهسفرم گرم و خشکست در یک درجه و تخم او اسهال صفرائی را تسکین دهد و طریق علاج او آن است که تخم او را بریان کنند و با آب سرد بکار برند. (ترجمه ٔ صیدنه ٔ ابوریحان ). رجوع به ضومران و ضیمران شود.<br /></font></div>'),
(174641, 'ضمیری', '<span class=\"hlight\">ضمیری .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (اِخ ) شاعری است باستانی .بیتی چند از اشعار او در لغت نامه ٔ اسدی آمده است :<br />گاه کوه بیستون و گنج بادآور زنند<br />گاه دست سلمکی و پرده ٔ عشرا برند<br />رونق پالیز رفت اکنون که بلبل نیمشب <br />بر سر پالیزبان کمتر زند پالیزبان <br />کرد شاها مهرگان ازدست گشت روزگار<br />باغ راکوته دو دست از دامن فروردجان .<br /></font></div>'),
(174642, 'ضمیری', '<span class=\"hlight\">ضمیری .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (اِخ ) کمال الدین حسین اصفهانی .از شعرای ظریف طبع ایران معاصر شاه طهماسب صفوی است و به گفته ٔ صاحب آنندراج گویا در اصفهان بلکه در ولایات دیگر بکثرت شعر او شاعری نیامده است . شش مثنوی بنام ناز و نیاز، جنةالاخیار، بهار و خزان، وامق و عذرا، لیلی و مجنون، اسکندرنامه سروده و به گفته ٔ صاحب قاموس الاعلام دو دیوان و بتصریح صاحب آنندراج هفت دیوان داشته بدین ترتیب : سفینه ٔ اقبال، صورت حال، کنزالاقوال، عشق بی زوال، صیقل ملال، عذر مقال، قدس خیال . و نیز چهار دیوان در برابر طیبات و بدایع و خواتیم و غزلیات قدیم شیخ سعدی مسمی به طاهرات و صنایع و بدایعالشعر و نهایت السحر گفته، و عیون الزلال در برابر دیوان حافظ و سحر حلال در برابر آصفی هروی و خجسته فال در مقابل شهیدی قمی و لوامع خیال در برابر میر همایون اسفراینی و بدایت وصال در برابر میرزا شرف جهان قزوینی و منتهای کمال در برابر کمال خجندی و معشوق لایزال دربرابر امیرخسرو دهلوی و حسن مآل در برابر حسن دهلوی . گویند بعلت هجوسرائی وی را در اصفهان تشهیر کردند.و بسال <span class=\"hlight\" dir=\"rtl\">٩٧٣</span> هَ . ق . درگذشته است ». هدایت در مجمع الفصحا گوید: اسمش کمال الدین حسین . ظریفی خوش صحبت و حریفی بلندهمت، اشعار نمکینش عاشقان را مرهم سینه ٔ مجروح و ابیات شیرینش عارفان را راحت روح . در زمان شاه طهماسب صفوی زبان بشاعری گشوده و در زمان حیات داد شاعری داده، گویا در اصفهان بلکه در ولایات دیگر بکثرت شعر او شاعری نیامده اما اکثر آنها چه (؟) که بالتمام بتحلیل رفته . غرض منتخب هر یک را هر جا دیده جمع و درین نسخه ثبت کرد. به اعتقاد فقیر این سعی و اهتمام که جناب مولانا در کمیّت شعر کرده اند اگر در کیفیت می فرمودند بهتر می بود و بتقریب بمهارت در علم رَمْل ضمیری تخلص می کرده . گویند شش مثنوی مسمی به ناز و نیاز، بهار و خزان، لیلی و مجنون، وامق و عذرا، جنةالاخیار و اسکندرنامه گفته و اسامی دواوین غزلیات او بدین موجب است، آنچه تتبع شد هفت دیوانست مسمی به سفینه ٔ اقبال و صورت حال و کنزالاقوال و عشق بی زوال و صیقل ملال و عذر مقال و قدس خیال تمام کرده و چهار دیوان در برابر طیبات و بدایع و خواتیم و غزلیات قدیم شیخ سعدی مسمی به طاهرات و صنایع و بدایعالشعر و نهایةالسحر گفته و عیون الزلال در مقابل دیوان خواجه حافظ شیرازی و سحر حلال در مقابل آصفی هروی و خجسته فال در برابر بابا شهیدی قمی و لوامع خیال در برابر همایون اسفراینی و بدایت وصال در برابر میرزا شرف جهان قزوینی و منتهای کمال در برابر کمال خجندی و معشوق لایزال دربرابر امیرخسرو دهلوی بپایان رسانیده و فقیر چنین می داند که تمامی عمر مولانا لیلاً و نهاراً و سراً و جهراً وفا به خواندن کتب مرقومه نمی کند تا به گفتن و نوشتن چه رسد، خلاصه چون غرابت داشت نوشتم و العهدة علی الراوی . صادقی کتابدار صاحب مجمعالخواص گوید: مولانا ضمیری اصفهانی بااینکه اصفهانی است شخصی هموار و خوش صحبت و بلندهمت بود، عاشق پیشه هم بود. در عهد خود اکابر و اعالی و ترک و فارس همه بصحبتش راغب و طالب بودند. صدهزار بیت شعر دارد و یک بیت آنها در ستایش پادشاهان نیست و این خود برای علو همتش بهترین دلیل است . دیوانی به تتبع دیوان خواجه حافظ به اتمام رسانیده و موفق شده است و اشعار بسیار خوبی از او شهرت دارد. در ولایت خود وفات یافته و قبرش هم در آنجاست .<br />ادوارد برون در تاریخ ادبیات خود ضمیری را درعداد شعرای شاه عباس صفوی آورده ولی ظاهراً گفته ٔ دیگران که وی را معاصر شاه طهماسب دانسته اند اصح است و این قول اخیر را نوشته ٔ صادقی کتابدار که خود معاصر شاه عباس بوده و گوید که ضمیری در ولایت خود وفات یافته و قبرش هم در آنجاست تأیید می کند. رجوع به مجمع الخواص ص <span class=\"hlight\" dir=\"rtl\">١٣٦</span> و مجمع الفصحا ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٥</span> و قاموس الاعلام ترکی و آنندراج شود. این ابیات متفرق ضمیری راست :<br />مشکل شده کارم ز تو درد دلم اینست <br />آگه نه ای از درد دلم مشکلم اینست <br />سیلاب سرشک از در او میبردم آه <br />عمری اثر گریه ٔ بیحاصلم اینست .<br />ز بس بحسن وی افزود غم گداخت مرا<br />نه من شناختم او را نه او شناخت مرا.<br />ناله ام را هست تأثیری و می ترسم که زود<br />بر سر رحم آورد یار ستمکار مرا.<br />هر گاه می روم که شکایت کنم ز تو<br />چون گوش می کنم بزبانم دعای تست .<br />می خواست رستخیز ز عالم برآورد<br />آن باغبان که تربیت این نهال کرد.<br />سر در جهان نهاد ضمیری سرشک تو<br />ترسم ز جور یار بعالم خبر برد.<br />چو می بینم کسی کز کوی او دلشاد می آید<br />فریبی کَاوّل از وی خورده بودم یاد می آید.<br />نومید چو آیم بسر کوی تو گویم <br />امّید که این بار چو هر بار نباشد<br />فریاد از آن لحظه که درد دلم آن شوخ <br />پرسد ز من و قوت گفتار نباشد<br />از حسرت دیدار تو یابد دل پردرد<br />آن ذوق که در لذت دیدار نباشد.<br />فریب بین که فرستد نوید وصل دمادم <br />به این خیال که شاید در انتظار بمیرم .<br />نه غمی است از تو در دل که به او رسیده باشی <br />نه مراست چاره از غم که ز کس شنیده باشی .<br />طبیبی گفت درمانی ندارد درد مهجوری <br />غلط می گفت خود را کشتم و درمان خود کردم .<br />چه کند خضر ندانم بحیات جاودانی <br />که مرا ملال گیرد ز دو روز زندگانی .<br />نه ز ضعف است که از خود رَوَم و بازآیم <br />هر نفس در طلب او بجهان دگرم .<br />هر دو عالم را بیک دیدن ز چشم من فکند<br />این زمان خود اندک اندک در دلم جا می کند.<br />گرنه فریب وعده ٔ روز جزا بود ز تو<br />سوی بدن که آورد جان گریزپای را.<br />علاج درد ضمیری نشد، نمی دانم <br />که گفته بود که دردت دواپذیر مباد.<br />بحکم صبر ملک عشق را امن و امان کردم <br />جفا را ساختم مشفق بلا را مهربان کردم .<br />ای عهدشکن آنهمه صحبت بکجا رفت <br />آن بستن پیمان محبت بکجا رفت <br />خوی کرده رخ از تشنه ٔ دیدار چه پوشی <br />ما هیچ نگوئیم مروّت بکجا رفت .<br />هر کس که دید کشته مرا گفت این کسی است <br />کزبهر آرزوی دل از جان گذشته است .<br />مجلسی پر رشک اغیار است رسوایم مساز<br />زآن اشارتها که یاد از صحبت پنهان دهد.<br />وصل دایم اضطراب شعله ٔ شوقم نشاند<br />چند روزی هجر میخواهم سزای من دهد.<br />جان از نظاره دوش چنان کامیاب بود<br />کز شرم آرزوبدل من گذر نداشت .<br />طی لسانی از خدا خواهم و روز محشری <br />پیش تو شرح تا دهم حال شب دراز را.<br />دوش از وعده ٔ امروز تو آمد یادم <br />فکر آن شب همه شب آه چه با جانم کرد.<br />شادم که وعده داد بفردای محشرم <br />کآن روز هیچ وعده بفردا نمی شود.<br />به اندک سوز غیر، از جا مرو کآن از هوس باشد<br />چو آتش در خس افتد شعله ٔ آن یک نفس باشد.<br />ز خانه دیر از آن ماه من برون آید<br />که بوالهوس ز ره انتظار برخیزد<br />کجاست بخت که آیی بدین غرض که مباد<br />ز رهگذار من آن بیقرار برخیزد.<br /></font></div>'),
(174643, 'ضمیری', '<span class=\"hlight\">ضمیری .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (اِخ ) همدانی . صادقی کتابدار در تذکره گوید: مولانا ضمیری همدانی ولد مولانا حیرانی است، گرچه اصلاً قمی است ولی بیشتربه همدانی بودن شهرت دارد. شخصی بود درویش نهاد و منصف و افتاده و رمال خوبی هم بود. در اوایل بمجلس شاه مرحوم بار یافته تردد می کرد. از نحوست یک دو بیت که نسبت به اهل مجلس کنایه و بلکه صراحت داشت او را ازآن مجلس بهشت آیین منع فرمودند، و آن بیتها اینست :<br />همه حافظ فلان ماهیچه <br />همه درویش رمز بغرایی <br />که دلالی و دف کشی صد بار<br />بهتر از شاعری و ملایی .<br />بقیه ٔ عمر را در گوشه ٔ همدان بسر می برد. این بیت که گفته است شهرت بزرگی دارد:<br />من به وادی مردم و مجنون به حی ّ ای ابر غم <br />گریه بر من کن که مجنون نوحه گر دارد بسی .<br />و این بیت را هم بد نگفته است :<br />می روم جلوه کنان بیخبر از اهل نظر<br />روش مردم این شهر چنین است مگر.<br />مگو رفتی پی سوزان دل از کویش چه آوردی <br />چه آوردم ز کویش پاره ای خاکستر آوردم .<br />وفاتش هم در همدان اتفاق افتاده و قبرش در آستانه ٔ امامزاده اسماعیل است . (مجمع الخواص ص <span class=\"hlight\" dir=\"rtl\">١٧٨</span> و <span class=\"hlight\" dir=\"rtl\">١٧٩</span>). او راست منظومه ٔ ناهید و بهرام . (کشف الظنون ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٨٢</span>).<br /></font></div>'),
(174644, 'ضمیل', '<span class=\"hlight\">ضمیل .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص ) خشک . ضامل . (منتهی الارب ).<br /></font></div>'),
(174645, 'ضمیلة', '<span class=\"hlight\">ضمیلة.</span> <font color=\"DarkGreen\"><b>[ ض َ ل َ ]</font></b> (ع ص ) زن برجای مانده . <BR><font color=\"Blue\">◄</font> زن لنگ، و منه : ان رجلاً خطب الی معاویة بنته عَرجاء فقال انها ضمیلة فقال انی ارید ان اتشرف بمصاهرتک و لاارید للسباق فی الحلبة. (منتهی الارب ).<br /></font></div>'),
(174646, 'ضمیم', '<span class=\"hlight\">ضمیم .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (اِخ ) از قرای یمن بناحیه ٔ جهران از اعمال صنعاء. (معجم البلدان ).<br /></font></div>'),
(174647, 'ضمیمة', '<span class=\"hlight\">ضمیمة.</span> <font color=\"DarkGreen\"><b>[ ض َ م َ ]</font></b> (ع اِ) چیزی که با چیزی آن را فراهم کرده باشند. (غیاث ) (آنندراج ). ج، ضمایم .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بضمیمه ٔ</span> ؛ با. به اضافه ٔ.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضمیمه ٔ اعور</span> . رجوع به زائده ٔ اعور شود. آویزه . (لغت فرهنگستان ). آپاندیس .<br /></font></div>'),
(174648, 'ضمین', '<span class=\"hlight\">ضمین .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص ) پذرفتار. کفیل . (منتهی الارب ) (منتخب اللغات ). پایندان . ج، ضمناء. (مهذب الاسماء). ضامن . (غیاث ) <span class=\"hlight\">:</span> <br />زهی بدولت ملک تو چرخ گشته ضمین <br />زهی بنصرت و فتح تو دهر کرده ضمان .<br /> <font color=\"Red\">مسعودسعد.</font><br />همه شب نیارامید از سخنهای باخشونت گفتن که فلان انبازم بترکستان است ... و این قباله ٔ فلان زمین و فلان چیز را فلان کس ضمین . (گلستان ).<br /></font></div>'),
(174649, 'ضن', '<span class=\"hlight\">ضن .</span> <font color=\"DarkGreen\"><b>[ ض ِن ن ]</font></b> (ع مص ) ضَنانة. زفت گردیدن و زفتی کردن . (منتهی الارب ). بخیلی کردن . (زوزنی ) (دهار) (تاج المصادر) (منتخب اللغات ).<br /></font></div>'),
(174650, 'ضن', '<span class=\"hlight\">ضن .</span> <font color=\"DarkGreen\"><b>[ ض ِن ن ]</font></b> (ع اِ) دوست خالص . (دهار). خاص و مخصوص . گویند: هو ضِنّی ؛ یعنی او خاص به من است . و فلان ضِنّی من بین اخوانی ؛ یعنی فلان در میان برادران من اختصاص مانندی به من دارد. (منتهی الارب ).<br /></font></div>'),
(174651, 'ضن', '<span class=\"hlight\">ضن .</span> <font color=\"DarkGreen\"><b>[ ض َ نِن ْ ]</font></b> (ع ص ) بیمار. گویند: ترکته ضنی ً و ضنیاً. (منتهی الارب ). ج، اَضْناء.<br /></font></div>'),
(174652, 'ضناء', '<span class=\"hlight\">ضناء.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) ضَنی . بسیاربچه شدن زن . (منتهی الارب ).<br /></font></div>'),
(174653, 'ضناط', '<span class=\"hlight\">ضناط.</span> <font color=\"DarkGreen\"><b>[ ض ِ ]</font></b> (ع مص ) بسیار انبوهی کردن بر چاه و مانند آن . (منتهی الارب ).<br /></font></div>'),
(174654, 'ضنان', '<span class=\"hlight\">ضنان .</span> <font color=\"DarkGreen\"><b>[ ض َن ْ نا ]</font></b> (اِخ ) ابن باز. شاعر است . (منتهی الارب ).<br /></font></div>'),
(174655, 'ضنانت', '<span class=\"hlight\">ضنانت .</span> <font color=\"DarkGreen\"><b>[ ض َ ن َ ]</font></b> (ع مص ) ضِن ّ. زفت گردیدن و زفتی کردن . بخیلی کردن . (تاج المصادر) (زوزنی ). بخل ورزیدن . بخیلی . (دهار). بخل .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(174656, 'ضناک', '<span class=\"hlight\">ضناک .</span> <font color=\"DarkGreen\"><b>[ ض ُ ]</font></b> (ع اِ) زکام . (منتهی الارب ) (مهذب الاسماء) (منتخب اللغات ). ضُنکة. (منتهی الارب ). چایمان . چاییدگی . سرماخوردگی .<br /></font></div>'),
(174657, 'ضناک', '<span class=\"hlight\">ضناک .</span> <font color=\"DarkGreen\"><b>[ ض َ <span class=\"hlight\" dir=\"rtl\">/</span> ض ِ ]</font></b> (ع ص ) زن پرگوشت . زن درشت . (منتهی الارب ). زن آگنده گوشت . (منتخب اللغات ) (مهذب الاسماء).<br /></font></div>'),
(174658, 'ضناک', '<span class=\"hlight\">ضناک .</span> <font color=\"DarkGreen\"><b>[ ض ِ ]</font></b> (ع ص ) استوارخلقت . (منتهی الارب ) (منتخب اللغات ). توانا. قوی (مذکر و مؤنث در وی یکسانست ). <BR><font color=\"Blue\">◄</font> زن گران سرین (اصمعی گوید شتر را نیز گویند). (منتهی الارب ). گران کفل . (منتخب اللغات ). ضَناک . زن پرگوشت . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> درخت بزرگ . (منتهی الارب ) (منتخب اللغات ).<br /></font></div>'),
(174659, 'ضنب', '<span class=\"hlight\">ضنب .</span> <font color=\"DarkGreen\"><b>[ ضَمْب ْ ]</font></b> (ع مص ) کوفتن کسی را بزمین . <BR><font color=\"Blue\">◄</font> گرفتن چیزی را. (منتهی الارب ).<br /></font></div>'),
(174660, 'ضنبر', '<span class=\"hlight\">ضنبر.</span> <font color=\"DarkGreen\"><b>[ ضَم ْب َ ]</font></b> (اِخ ) نام مردی . (منتهی الارب ).<br /></font></div>'),
(174661, 'ضنبس', '<span class=\"hlight\">ضنبس .</span> <font color=\"DarkGreen\"><b>[ ضِم ْ ب ِ ]</font></b> (ع ص ) سست بطش . <BR><font color=\"Blue\">◄</font> زود شکسته شونده . <BR><font color=\"Blue\">◄</font> سست . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> مرد سست گوشتین . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> فرومایه . <BR><font color=\"Blue\">◄</font> زودرنج . (منتهی الارب ).<br /></font></div>'),
(174662, 'ضنة', '<span class=\"hlight\">ضنة.</span> <font color=\"DarkGreen\"><b>[ ض ِن ْ ن َ ]</font></b> (اِخ ) نام پنج قبیله است : ضنةبن سعد در قضاعة و ضنةبن عبداﷲ درعذرة و ضنةبن حلاّف در اسد و ضنةبن خزیمة و ضنةبن العاص در ازد و ضنةبن عبداﷲ در نُمیر. (منتهی الارب ).<br /></font></div>'),
(174663, 'ضنة', '<span class=\"hlight\">ضنة.</span> <font color=\"DarkGreen\"><b>[ ض ِن ْ ن َ ]</font></b> (اِخ ) ابن عبدبن کثیربن عذرة قضاعی از قحطان . جدی جاهلی است . و منازل فرزندان وی بشام بوده است . (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٠</span>).<br /></font></div>'),
(174664, 'ضنت', '<span class=\"hlight\">ضنت .</span> <font color=\"DarkGreen\"><b>[ ض َن ْ ن َ ]</font></b> (ع اِمص ) بُخل . بخل شدید. شُح ّ. بخیلی . (دهار). دریغ کردن <span class=\"hlight\">:</span> و لشکرهای او با هدیه های گرانمایه که روزگار به امثال آن سبک شود و ضنّت نماید هر یک را یورت معین فرمود. (جهانگشای جوینی ).<br />تا شبی بنمود او را جنتی <br />باغک سبزی خوشی بی ضنتی .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(174665, 'ضندل', '<span class=\"hlight\">ضندل .</span> <font color=\"DarkGreen\"><b>[ ض َ دَ ]</font></b> (ع اِ) صندل است وزناً و معنی ً که کلان سر باشد (یا آن به صاد مهمله است ). (منتهی الارب ).<br /></font></div>'),
(174666, 'ضنط', '<span class=\"hlight\">ضنط.</span> <font color=\"DarkGreen\"><b>[ ض َ ن َ ]</font></b> (ع مص ) فربه و پرگوشت شدن . <BR><font color=\"Blue\">◄</font> شادمانی . شادمانی کردن . <BR><font color=\"Blue\">◄</font> لاف زدن . <BR><font color=\"Blue\">◄</font> بی بهره شدن زن از شوی . (منتهی الارب ).<br /></font></div>'),
(174667, 'ضنط', '<span class=\"hlight\">ضنط.</span> <font color=\"DarkGreen\"><b>[ ض َ ن َ ]</font></b> (ع اِ) پِه . پیه . (منتهی الارب ). شحم .<br /></font></div>'),
(174668, 'ضنط', '<span class=\"hlight\">ضنط.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) دو بار گرفتن زن . <BR><font color=\"Blue\">◄</font> تنگی . (منتهی الارب ).<br /></font></div>'),
(174669, 'ضنفس', '<span class=\"hlight\">ضنفس .</span> <font color=\"DarkGreen\"><b>[ ض ِ ف ِ ]</font></b> (ع ص ) سست بطش . سست گرفت . <BR><font color=\"Blue\">◄</font> زود شکسته شونده . <BR><font color=\"Blue\">◄</font> سست . <BR><font color=\"Blue\">◄</font> ناکس . <BR><font color=\"Blue\">◄</font> زودرنج . (منتهی الارب ).<br /></font></div>'),
(174670, 'ضنن', '<span class=\"hlight\">ضنن .</span><font color=\"DarkGreen\"><b>[ ض َ ن َ ]</font></b> (ع ص ) مرد دلاور پخته کار. (منتهی الارب ).<br /></font></div>'),
(174671, 'ضنو', '<span class=\"hlight\">ضنو.</span> <font color=\"DarkGreen\"><b>[ ض َن ْوْ <span class=\"hlight\" dir=\"rtl\">/</span> ض ِن ْوْ ]</font></b> (ع اِ) فرزند. (منتهی الارب ) (مهذب الاسماء).<br /></font></div>'),
(174672, 'ضنوط', '<span class=\"hlight\">ضنوط.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص ) زن دو دوست گیرنده . (منتهی الارب ).<br /></font></div>'),
(174673, 'ضنک', '<span class=\"hlight\">ضنک .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص ) (معرب از تنگ ) تنگ . (منتهی الارب ) (مهذب الاسماء): معیشت ضنک ؛ معیشت ضیّقة؛ عیش تنگ . (دهار). <BR><font color=\"Blue\">◄</font> تنگی در هر چیز (للذکر و الانثی ). (منتهی الارب ).<br /></font></div>'),
(174674, 'ضنک', '<span class=\"hlight\">ضنک .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b>(ع مص ) ضناکة. ضُنوکة. تنگ شدن . (منتهی الارب ) (زوزنی ). تنگ عیشی . تنگ عیش شدن . (تاج المصادر). دست تنگی .<br /></font></div>'),
(174675, 'ضنک', '<span class=\"hlight\">ضنک .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (اِخ ) موضعی است . (معجم البلدان ).<br /></font></div>'),
(174676, 'ضنکان', '<span class=\"hlight\">ضنکان .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (اِخ ) رودباری است در پائین سراة، آبش بدریا ریزد، و آن یکی از مخلافهای یمن است . (معجم البلدان ).<br /></font></div>'),
(174677, 'ضنی', '<span class=\"hlight\">ضنی .</span> <font color=\"DarkGreen\"><b>[ ض ُن ْ نا ]</font></b> (اِخ ) ابوضنی سعیدبن ضنی . محدث است . (منتهی الارب ).<br /></font></div>'),
(174678, 'ضنی', '<span class=\"hlight\">ضنی .</span> <font color=\"DarkGreen\"><b>[ ض َن ْی ْ ]</font></b> (ع مص ) ضَناء. بسیاربچه شدن زن . <BR><font color=\"Blue\">◄</font> بسیار شدن و زیاده گشتن بهره ٔ کسی . <BR><font color=\"Blue\">◄</font> بیمار شدن یا بازگردیدن بیماری کسی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> نزار شدن . (زوزنی ).<br /></font></div>'),
(174679, 'ضنین', '<span class=\"hlight\">ضنین .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص ) بخیل . (منتخب اللغات ) (دهار) (مهذب الاسماء). شحیح . زفت و ناکس . (منتهی الارب ). ج، اَضِنّة، اضنّاء. (مهذب الاسماء).<br /></font></div>'),
(174680, 'ضنیک', '<span class=\"hlight\">ضنیک .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص ) زندگانی تنگ . تنگدستی . (منتهی الارب ). عیش تنگ . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> مرد سست تدبیر و عقل و ضعیف بدن و جان . (منتهی الارب ). ضعیف رای و ضعیف تن . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> خادم که بر نان خدمت کند. (منتهی الارب ). کردی خوردی . <BR><font color=\"Blue\">◄</font> بریده . (منتهی الارب ).<br /></font></div>'),
(174681, 'ضهب', '<span class=\"hlight\">ضهب .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) برگردانیدن چیزی را به آتش و تغییر دادن . (منتهی الارب ).<br /></font></div>'),
(174682, 'ضهب', '<span class=\"hlight\">ضهب .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ)ضهب القوم ؛ هر جنس مردم بهم آمیخته . (منتهی الارب ).<br /></font></div>'),
(174683, 'ضهبا', '<span class=\"hlight\">ضهبا.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص )کمانی که در آن آتش اثر کرده باشد. (منتهی الارب ).<br /></font></div>'),
(174684, 'ضهت', '<span class=\"hlight\">ضهت .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) نیک پاسپر کردن چیزی را. (منتهی الارب ). پایمال کردن .<br /></font></div>'),
(174685, 'ضهد', '<span class=\"hlight\">ضهد.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) چیره شدن بر کسی . مغلوب کردن کسی را. (منتهی الارب ). مقهور گردانیدن . (زوزنی ) (تاج المصادر). قهر کردن . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> ستم کردن . (منتهی الارب ).<br /></font></div>'),
(174686, 'ضهر', '<span class=\"hlight\">ضهر.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ) کَشَف . (منتهی الارب ). سنگپشت . لاک پشت . سلحفاة. (فهرست مخزن الادویه ). <BR><font color=\"Blue\">◄</font> سر کوه . <BR><font color=\"Blue\">◄</font> نوعی است از سنگ در کوه مخالف رنگ ظاهر کوه . <BR><font color=\"Blue\">◄</font> ظاهر رودبار. <BR><font color=\"Blue\">◄</font> (اِخ ) کوهی است به یمن . (منتهی الارب ).<br /></font></div>'),
(174687, 'ضهز', '<span class=\"hlight\">ضهز.</span> <font color=\"DarkGreen\"><b>[ض َ ]</font></b> (ع مص ) نیک کوفتن کسی را. سخت پاسپر کردن چیزی را. <BR><font color=\"Blue\">◄</font> آرمیدن با زن . <BR><font color=\"Blue\">◄</font> به پیش دهان گزیدن ِ ستور کسی یا چیزی را. (منتهی الارب ).<br /></font></div>'),
(174688, 'ضهزم', '<span class=\"hlight\">ضهزم .</span> <font color=\"DarkGreen\"><b>[ ض ِ زِ ]</font></b> (ع ص ) ناکس و فرومایه . (منتهی الارب ).<br /></font></div>'),
(174689, 'ضهس', '<span class=\"hlight\">ضهس .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) بدندان پیشین گزیدن ِ ستور کسی را. (منتهی الارب ). گزیدن به پیش دهان . (منتخب اللغات ).<br /></font></div>'),
(174690, 'ضهل', '<span class=\"hlight\">ضهل .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص، اِ) شیر گردآمده .هر چیز که اندک اندک و یکی بعد دیگری فراهم آمده باشد. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آب اندک . (منتهی الارب ) (منتخب اللغات ). آب اندک در جوی . (مهذب الاسماء).<br /></font></div>'),
(174691, 'ضهل', '<span class=\"hlight\">ضهل .</span> <font color=\"DarkGreen\"><b>[ ض ُ هَُ ]</font></b> (ع ص، اِ) ج ِ ضَهول . (منتهی الارب ).<br /></font></div>'),
(174692, 'ضهل', '<span class=\"hlight\">ضهل .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) اندک اندک فراهم آمدن چیزی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> اندک و تنک گشتن شراب و نوشیدنی . (تاج المصادر) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بازگشتن بسوی اصل . <BR><font color=\"Blue\">◄</font> بازگشتن بسوی کسی نه به وجه مقاتلة و مغالبة، یا عام است . (منتهی الارب ). بازگردیدن . (تاج المصادر). بازگردیدن بسوی کسی نه به وجه مقاتلة و مغالبة. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> کم کردن و باطل ساختن حق کسی را. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> اندک اندک دادن . (منتهی الارب ) (تاج المصادر) (زوزنی ). <BR><font color=\"Blue\">◄</font> برداشتن و منسوب کردن خبر را بکسی . (منتهی الارب ).<br /></font></div>'),
(174693, 'ضهلة', '<span class=\"hlight\">ضهلة.</span> <font color=\"DarkGreen\"><b>[ ض َ ل َ ]</font></b> (ع اِ) عطای اندک . گویند: اعطاه ضَهلة من ماله ؛ ای عطیة نزرة. (منتهی الارب ).<br /></font></div>'),
(174694, 'ضهوب', '<span class=\"hlight\">ضهوب .</span> <font color=\"DarkGreen\"><b>[ ض ُ ]</font></b> (ع مص ) پس ماندن . <BR><font color=\"Blue\">◄</font> ضعیف و سست گردیدن . <BR><font color=\"Blue\">◄</font> مانا بمردان نشدن . (منتهی الارب ).<br /></font></div>'),
(174695, 'ضهول', '<span class=\"hlight\">ضهول .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص ) شترمرغ سپید. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> چاه اندک آب . (مهذب الاسماء) (منتخب اللغات ). چاه کم آب . <BR><font color=\"Blue\">◄</font> گوسفند یا ناقه ٔ کم شیر. ج، ضُهُل . (منتهی الارب ).<br /></font></div>'),
(174696, 'ضهول', '<span class=\"hlight\">ضهول .</span> <font color=\"DarkGreen\"><b>[ ض ُ ]</font></b>(ع مص ) گرد آمدن شیر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کم شیر گردیدن ناقه . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> اندک اندک فراهم آمدن چیز. (منتهی الارب ).<br /></font></div>'),
(174697, 'ضهی', '<span class=\"hlight\">ضهی .</span> <font color=\"DarkGreen\"><b>[ ض َ ها ]</font></b> (ع مص ) بی نماز شدن زن . <BR><font color=\"Blue\">◄</font> بار نگرفتن زن . <BR><font color=\"Blue\">◄</font> پستان ناکردن زن . <BR><font color=\"Blue\">◄</font> نرویانیدن ِ زمین گیاه را. (منتهی الارب ).<br /></font></div>'),
(174698, 'ضهی', '<span class=\"hlight\">ضهی .</span> <font color=\"DarkGreen\"><b>[ ض َ هی ی ]</font></b> (ع ص ) مانا.مانند. یقال : هذا ضهیّک ؛ ای شبیهک . (منتهی الارب ).<br /></font></div>'),
(174699, 'ضهیاء', '<span class=\"hlight\">ضهیاء.</span> <font color=\"DarkGreen\"><b>[ ض َهَْ ی َءْ ]</font></b> (ع اِ) نباتی است که به نبات سیال ماند. <BR><font color=\"Blue\">◄</font> (ص ) زنی که حیض نیارد. <BR><font color=\"Blue\">◄</font> زنی که شیر و پستان ندارد. (منتهی الارب ).<br /></font></div>'),
(174700, 'ضهیاء', '<span class=\"hlight\">ضهیاء.</span> <font color=\"DarkGreen\"><b>[ ض َهَْ ]</font></b> (ع ص ) زنی که نه حیض آورد و نه باردار گردد، یعنی مانا بمردان گردیده باشد، یا آنکه حیض آرد و باردار نگردد. ضَهْیاة. (منتهی الارب ). زن که عادت نبیند. زن که هیچ خون نبیند و فرزند نیز نیارد. <BR><font color=\"Blue\">◄</font> زنی که او را شیر نباشد. <BR><font color=\"Blue\">◄</font> زنی که پستان نباشد او را. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> درختی است خاردار. (منتهی الارب ).<br /></font></div>'),
(174701, 'ضهید', '<span class=\"hlight\">ضهید.</span> <font color=\"DarkGreen\"><b>[ ض َهَْ ی َ ]</font></b> (ع ص ) نیک سخت (ولافَعْیَل سواه ). (منتهی الارب ).<br /></font></div>'),
(174702, 'ضهید', '<span class=\"hlight\">ضهید.</span> <font color=\"DarkGreen\"><b>[ ض َهَْ ی َ ]</font></b> (اِخ ) جایگاهی است (یا آن به صاد است ). (منتهی الارب ). ابن جنی گوید: و من فوائت الکتاب ضهید اسم موضع، و مثله عتید و کلاهما مصنوع، و قد ورد فی الفتوح فی ذکر فلاة بین حضرموت و الیمن یقال لها ضَهْیَد فعلی ̍هذا لیست بمصنوعة. (معجم البلدان ).<br /></font></div>'),
(174703, 'ضوابح', '<span class=\"hlight\">ضوابح .</span> <font color=\"DarkGreen\"><b>[ ض َ ب ِ ]</font></b> (ع ص، اِ) ج ِ ضابح . (منتهی الارب ).<br /></font></div>'),
(174704, 'ضوابط', '<span class=\"hlight\">ضوابط.</span> <font color=\"DarkGreen\"><b>[ ض َ ب ِ ]</font></b> (ع اِ) ج ِ ضابطة.<br /></font></div>'),
(174705, 'ضواجع', '<span class=\"hlight\">ضواجع.</span> <font color=\"DarkGreen\"><b>[ ض َ ج ِ ]</font></b> (ع اِ) ج ِ ضاجع. پشته ها. هِضاب . (منتهی الارب ). رجوع به ضاجع شود.<br /></font></div>'),
(174706, 'ضواجع', '<span class=\"hlight\">ضواجع.</span> <font color=\"DarkGreen\"><b>[ ض َ ج ِ ]</font></b> (اِخ ) جایگاهی است در گفته ٔ نابغه ٔ ذبیانی . (معجم البلدان ).<br /></font></div>'),
(174707, 'ضواجع', '<span class=\"hlight\">ضواجع.</span> <font color=\"DarkGreen\"><b>[ ض َ ج ِ ]</font></b> (اِخ ) هفت اورنگ کهین . (مهذب الاسماء).<br /></font></div>'),
(174708, 'ضواحک', '<span class=\"hlight\">ضواحک .</span> <font color=\"DarkGreen\"><b>[ ض َ ح ِ ]</font></b> (ع اِ) ج ِ ضاحکة. چهار دندان که از پس نیش بود. (مهذب الاسماء). دندانها که وقت خندیدن ظاهر شود، یا چهار دندان که میان انیاب و اضراس است . (منتخب اللعات ).<br /></font></div>'),
(174709, 'ضواحی', '<span class=\"hlight\">ضواحی .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ) ج ِ ضاحیة. (منتهی الارب ). ضواحیک ؛ آنچه از تو پیدا باشد در آفتاب مانند دوش و شانه . (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضواحی الحوض </span> ؛ کرانهای آن . (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضواحی الرّوم </span> ؛ شهرهای ظاهر روم . (منتهی الارب ).<br /><BR><font color=\"Blue\">◄</font> آسمانها.(منتهی الارب ).<br /></font></div>'),
(174710, 'ضوادی', '<span class=\"hlight\">ضوادی .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ) ج ِ ضادی . (منتهی الارب ). سخن که بدان تعلل کنند.<br /></font></div>'),
(174711, 'ضوارب', '<span class=\"hlight\">ضوارب .</span> <font color=\"DarkGreen\"><b>[ ض َ رِ ]</font></b>(ع ص، اِ) ج ِ ضارب . (منتهی الارب ). زننده و تپنده .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عروق ضوارب </span> ؛ شرائین .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عروق غیرضوارب </span> ؛ اورده . رگ .<br /></font></div>'),
(174712, 'ضواری', '<span class=\"hlight\">ضواری .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص، اِ) ج ِ ضاری .<br /></font></div>'),
(174713, 'ضواضی', '<span class=\"hlight\">ضواضی .</span> <font color=\"DarkGreen\"><b>[ ض ُ ]</font></b> (ع ص ) سطبر درشت . (منتهی الارب ).<br /></font></div>'),
(174714, 'ضواع', '<span class=\"hlight\">ضواع .</span> <font color=\"DarkGreen\"><b>[ ض ُ ]</font></b> (ع اِ) بانگ چوکک . (منتهی الارب ). بانگ کوک نر. (مهذب الاسماء). بانگ مرغ ضوع . (منتخب اللغات ).<br /></font></div>'),
(174715, 'ضواع', '<span class=\"hlight\">ضواع .</span> <font color=\"DarkGreen\"><b>[ ض َوْ وا ]</font></b> (ع اِ) روباه . (منتهی الارب ).<br /></font></div>'),
(174716, 'ضواعة', '<span class=\"hlight\">ضواعة.</span> <font color=\"DarkGreen\"><b>[ ض َ ع َ ]</font></b> (ع مص ) خواری و فروتنی کردن . (زوزنی ).<br /></font></div>'),
