(174718, 'ضوامر', '<span class=\"hlight\">ضوامر.</span> <font color=\"DarkGreen\"><b>[ ض َ م ِ ]</font></b> (ع ص، اِ) ج ِ ضامر. (دهار). رجوع به ضامر شود.<br /></font></div>'),
(174719, 'ضوامن', '<span class=\"hlight\">ضوامن .</span> <font color=\"DarkGreen\"><b>[ ض َ م ِ ]</font></b> (ع ص، اِ) ج ِ ضامن . (منتهی الارب ). رجوع به ضامن شود.<br /></font></div>'),
(174720, 'ضوبان', '<span class=\"hlight\">ضوبان .</span> <font color=\"DarkGreen\"><b>[ ضو <span class=\"hlight\" dir=\"rtl\">/</span> ض َ ]</font></b> (ع ص ) ضؤبان . (منتهی الارب ). شتر قوی توانا و پرگوشت (واحد و جمع برابر است ). (منتهی الارب ).<br /></font></div>'),
(174721, 'ضوبان', '<span class=\"hlight\">ضوبان .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ) ضؤبان . (منتهی الارب ). دوش شتر. (منتهی الارب ).<br /></font></div>'),
(174722, 'ضوت', '<span class=\"hlight\">ضوت .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (اِخ ) موضعی است . (معجم البلدان ).<br /></font></div>'),
(174723, 'ضوتع', '<span class=\"hlight\">ضوتع.</span> <font color=\"DarkGreen\"><b>[ ض َ ت َ ]</font></b> (ع اِ) ضَتَع. جانورکی است، یا مرغی است . <BR><font color=\"Blue\">◄</font> (ص ) مرد گول (یا صواب ضوکة است ). (منتهی الارب ).<br /></font></div>'),
(174724, 'ضوج', '<span class=\"hlight\">ضوج .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ) خم رودبار. (منتهی الارب ). گردش رود. (مهذب الاسماء). ج، اضواج .<br /></font></div>'),
(174725, 'ضوج', '<span class=\"hlight\">ضوج .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص )میل کردن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> میل کردن تیراز هدف . (منتخب اللغات ). چسبیدن تیر از نشانه . برگردیدن تیر از نشانه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> فراخ گردیدن . (منتهی الارب ). فراخ شدن . (منتخب اللغات ).<br /></font></div>'),
(174726, 'ضوجان', '<span class=\"hlight\">ضوجان .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص ) آنکه خشک و نیک لاغر باشد، از ستور و مردم و نخلة. (منتهی الارب ).<br /></font></div>'),
(174727, 'ضوجانة', '<span class=\"hlight\">ضوجانة.</span> <font color=\"DarkGreen\"><b>[ ض َ ن َ ]</font></b> (ع ص ) تأنیث ضوجان : نخلة ضَوْجانة؛ خرمابن خشک و خشک شاخه (لغة فی الصّاد). (منتهی الارب ). <BR><font color=\"Blue\">◄</font> رود (؟). (مهذب الاسماء) .<br /></font></div>'),
(174728, 'ضور', '<span class=\"hlight\">ضور.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) گزند رسانیدن کسی را. (منتهی الارب ). گزند کردن . (تاج المصادر) (زوزنی ) (دهار). لغتی است در ضَیْر بمعنی گزند رسانیدن بکسی و زیان کردن . (منتهی الارب ).<br /></font></div>'),
(174729, 'ضور', '<span class=\"hlight\">ضور.</span> (ع اِ) ابر سیاه . (منتهی الارب ) (منتخب اللغات ).<br /></font></div>'),
(174730, 'ضور', '<span class=\"hlight\">ضور.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (اِخ ) پدر یحیی .صیاد ضبی . مثل است در سختی و صلابت . (منتهی الارب ).<br /></font></div>'),
(174731, 'ضور', '<span class=\"hlight\">ضور.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b>(اِخ ) بنوضور؛ قبیله ای است از عرب . (منتهی الارب ).<br /></font></div>'),
(174732, 'ضور', '<span class=\"hlight\">ضور.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b>(ع اِ) گرسنگی سخت . (منتهی الارب ) (منتخب اللغات ).<br /></font></div>'),
(174733, 'ضوران', '<span class=\"hlight\">ضوران .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (اِخ ) نام یکی از حصارهای یمن ازآن ِ بنی هرش، و آن از نام کوهی است بهمین اسم به برسوی این ناحیت . (معجم البلدان ).<br /></font></div>'),
(174734, 'ضوری', '<span class=\"hlight\">ضوری .</span> <font color=\"DarkGreen\"><b>[ ض َ را ]</font></b> (اِخ ) نام آبی است . (منتهی الارب ).<br /></font></div>'),
(174735, 'ضوز', '<span class=\"hlight\">ضوز.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ) ضوازة. پاره ٔ جداافتاده از مسواک . (منتهی الارب ).<br /></font></div>'),
(174736, 'ضوز', '<span class=\"hlight\">ضوز.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) کم کردن و نقصان کردن در حق کسی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> جور کردن در حکم . (منتخب اللغات ). جور و ستم کردن بر کسی در حکم . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خائیدن خرما را. (منتهی الارب ) (منتخب اللغات ). خائیدن . (تاج المصادر).<br /></font></div>'),
(174737, 'ضوس', '<span class=\"hlight\">ضوس .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) طعام خوردن . (منتهی الارب ).<br /></font></div>'),
(174738, 'ضوضا', '<span class=\"hlight\">ضوضا.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ) ضَوْضاء. ضؤضا. شور و غوغا. (منتهی الارب ). بانگ . (مهذب الاسماء). هیاهو. هیابانگ . هلالوش . شور و شغب . مشغله . (نصاب ). چنگ و چلب .<br /></font></div>'),
(174739, 'ضوضا', '<span class=\"hlight\">ضوضا.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (اِخ ) (جزیره ٔ ضوضا) در او بلاد بسیار بود و از جمله شهری از سنگ سفید چنانکه بشب روشنی می داد و جزیره را بدان بازمی خوانند. بدان شهر ماران بزرگ مستولی شدند و مردم آن رابازگذاشتند و اکنون خراب است اما <font color=\"DarkGreen\"><b>[ در ]</font></b> آب و هوا خوشترین آن ولایت بود. (نزهة القلوب چ اروپا ص <span class=\"hlight\" dir=\"rtl\">٢٣٦</span>).<br /></font></div>'),
(174740, 'ضوضاء', '<span class=\"hlight\">ضوضاء.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ) ضوضا. رجوع ب-ه ض-وض-ا ش-ود.<br /></font></div>'),
(174741, 'ضوط', '<span class=\"hlight\">ضوط.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) کژ شدن زنخ و کژی آن . (منتهی الارب ).<br /></font></div>'),
(174742, 'ضوطار', '<span class=\"hlight\">ضوطار.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص ) آنکه در بازار بدون رأس المال درآید و در کسب مطلوب حیله ها جوید. (منتهی الارب ).<br /></font></div>'),
(174743, 'ضوطر', '<span class=\"hlight\">ضوطر.</span> <font color=\"DarkGreen\"><b>[ ض َ طَ ]</font></b> (ع ص ) ضبطر. ضبطار. مرد کلان جثه ٔ فربه ناکس بزرگ سرین . مرد شگرف بی خیر. (منتهی الارب ). ج، ضَیاطر، ضیاطرة، ضَیْطارون .<br /></font></div>'),
(174744, 'ضوطری', '<span class=\"hlight\">ضوطری .</span> <font color=\"DarkGreen\"><b>[ ض َ طَ ]</font></b> (ع ص ) مرد شگرف بی خیر. (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بنوضوطری </span> ؛ گرسنگی . و نام قبیله ای است . (منتهی الارب ).<br /></font></div>'),
(174745, 'ضوع', '<span class=\"hlight\">ضوع .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) جنبانیدن چیزی را. (منتهی الارب ) (منتخب اللغات ) (تاج المصادر) (زوزنی ). <BR><font color=\"Blue\">◄</font> برکندن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بی آرام کردن . (منتهی الارب ) (منتخب اللغات ). هواسیدن یعنی پژمرده و بی آب شدن . <BR><font color=\"Blue\">◄</font> ترسانیدن . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> شکافتن . دوپاره کردن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> لاغر کردن سفر ستور را. (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> خورش دادن مرغ بچه را. <BR><font color=\"Blue\">◄</font> جنبیدن (؟) و بردمیدن بوی مشک . (منتهی الارب ). جنبیدن (؟) مشک و جز آن و دمیدن و منتشر شدن بوی آن، و همچنین دمیدن بوی بد را نیز گویند. (منتخب اللغات ). دمیدن بوی خوش . تضوع . بوی خوش دمیدن . (تاج المصادر) (زوزنی ) (دهار). <BR><font color=\"Blue\">◄</font> مایل کردن باد شاخ را. <BR><font color=\"Blue\">◄</font> آماده ٔ گریستن شدن کودک . (منتهی الارب ).<br /></font></div>'),
(174746, 'ضوع', '<span class=\"hlight\">ضوع .</span> <font color=\"DarkGreen\"><b>[ ض ُ وَ <span class=\"hlight\" dir=\"rtl\">/</span> ض ِ وَ ]</font></b> (ع اِ) مرغی است از مرغان شب، یا آن شوات است یا بوم نر که همه شب بانگ کند، و آن را چوکک هم گویند، یا مرغی است سیاه مانند زاغ پاکیزه گوشت . غاژ. غراب الزیتون . غراب الزرع . ج، اضواع، ضیعان . (منتهی الارب ). بوم نر را نامند که بفارسی کول نر گویند. (فهرست مخزن الادویه ). نوعی بوم . بوم نر. (دهار). کرک نر. (مهذب الاسماء). نوعی است از مرغان شب یا مرغی است که آن را کروان نیز گویند یا بوم نر یا مرغی است سیاه مانند غراب که خوش گوشت می باشد، و بعضی گفته اند نوعی است از مرغ که همه شب بانگ کند و آن را چوکک گویند. (منتخب اللغات ).<br /></font></div>'),
(174747, 'ضوف', '<span class=\"hlight\">ضوف .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) از پی کسی فراشدن . (زوزنی ).<br /></font></div>'),
(174748, 'ضوقی', '<span class=\"hlight\">ضوقی .</span> <font color=\"DarkGreen\"><b>[ قا ]</font></b> (ع ن تف ) تأنیث اضیق . (منتهی الارب ).<br /></font></div>'),
(174749, 'ضولج', '<span class=\"hlight\">ضولج .</span> <font color=\"DarkGreen\"><b>[ ض َ ل َ ]</font></b> (ع اِ) سیم (و صواب به صاد مهمله است ). (منتهی الارب ). اسم عربی فضه است (افصح به صاد مهمله است ). (فهرست مخزن الادویه ).<br /></font></div>'),
(174750, 'ضولع', '<span class=\"hlight\">ضولع.</span><font color=\"DarkGreen\"><b>[ ض َ ل َ ]</font></b> (ع ص ) مائل هوا و خواهش . (منتهی الارب ).<br /></font></div>'),
(174751, 'ضوم', '<span class=\"hlight\">ضوم .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) کم کردن حق کسی را و ستم به او. (منتهی الارب ).<br /></font></div>'),
(174752, 'ضومر', '<span class=\"hlight\">ضومر.</span> <font color=\"DarkGreen\"><b>[ ض َ م َ ]</font></b> (ع اِ) حوک . حوک خوانند و آن بادروج است . (اختیارات بدیعی ). بادروج . (فهرست مخزن الادویه ). <BR><font color=\"Blue\">◄</font> گل بستان افروز است و آن را تاج خروس هم می گویند و بوییدن آن عطسه آورد. (برهان ).<br /></font></div>'),
(174753, 'ضومران', '<span class=\"hlight\">ضومران .</span> <font color=\"DarkGreen\"><b>[ ض َ م َ <span class=\"hlight\" dir=\"rtl\">/</span> ض َ م ُ ]</font></b> (ع اِ) ضومیران . (ابن بیطار). ضمیران . شاهسپرم . (مهذب الاسماء). شاسپرم . (مهذب الاسماء). نوعی است از ریحان دشتی . (منتخب اللغات ). ریحان دشتی یا ریحان فارسی است . (منتهی الارب ). حبق الماء. پودنه ٔ لب جوی . پودنه ٔ جویباری . (ابن البیطار). فودنج النهری . پونه . صاحب اختیارات بدیعی گوید: صاحب جامع سهو کرده که آن را ضیمران گفته است و قول صاحب منهاج معتبر است که آن بیدمشک است و آن را بهرامج گویند و گفته شد و بدل آن بوم است یا ملخیه (؟) به وزن آن . (اختیارات بدیعی ). بیدمشک . (تحفه ٔ حکیم مؤمن ).<br /></font></div>'),
(174754, 'ضومیران', '<span class=\"hlight\">ضومیران .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ) ضومران . (ابن البیطار).<br /></font></div>'),
(174755, 'ضون', '<span class=\"hlight\">ضون .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ) شکنبه ٔ بره و بزغاله که هنوز علف نخورده باشد. (منتهی الارب ).<br /></font></div>'),
(174756, 'ضونة', '<span class=\"hlight\">ضونة.</span> <font color=\"DarkGreen\"><b>[ ض َن َ ]</font></b> (ع اِ) آهو ماده ٔ ریزه و خرد. (منتهی الارب ).<br /></font></div>'),
(174757, 'ضونة', '<span class=\"hlight\">ضونة.</span> <font color=\"DarkGreen\"><b>[ ض َ ن َ ]</font></b> (ع مص ) بسیاربچه شدن . (منتهی الارب ).<br /></font></div>'),
(174758, 'ضوک', '<span class=\"hlight\">ضوک .</span><font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) برجستن اسب بر ماده . (منتهی الارب ).<br /></font></div>'),
(174759, 'ضوی', '<span class=\"hlight\">ضوی .</span> <font color=\"DarkGreen\"><b>[ ض َ وا ]</font></b> (ع اِمص ) باریکی استخوان و خردی جسم در خلقت . لاغری . (منتهی الارب ).<br /></font></div>'),
(174760, 'ضوی', '<span class=\"hlight\">ضوی .</span> <font color=\"DarkGreen\"><b>[ ض ُ وی ی ]</font></b> (ع مص ) لاغر گردیدن . (منتهی الارب ). نزار شدن . (زوزنی ). <BR><font color=\"Blue\">◄</font> فراهم آمدن . <BR><font color=\"Blue\">◄</font> جای گرفتن . (منتهی الارب ). مأوی گرفتن . (زوزنی ). پناه بردن بکسی . <BR><font color=\"Blue\">◄</font> درآمدن در شب . <BR><font color=\"Blue\">◄</font> پرسیدن خبر چیزی را. (منتهی الارب ).<br /></font></div>'),
(174761, 'ضویحک', '<span class=\"hlight\">ضویحک .</span> <font color=\"DarkGreen\"><b>[ ض ُ وَ ح ِ ]</font></b> (اِخ ) کوهی در پایین فرش . (معجم البلدان ).<br /></font></div>'),
(174762, 'ضویضیة', '<span class=\"hlight\">ضویضیة.</span> <font color=\"DarkGreen\"><b>[ ض ُ وَ ی َ ]</font></b> (ع اِ)بلا. <BR><font color=\"Blue\">◄</font> (ص ) گشن تیزشهوت . (منتهی الارب ).<br /></font></div>'),
(174763, 'ضک', '<span class=\"hlight\">ضک .</span> <font color=\"DarkGreen\"><b>[ ض َک ک ]</font></b> (ع مص ) دشوار گردیدن کسی را کار و تنگ شدن . <BR><font color=\"Blue\">◄</font> فشار دادن چیزی را و تنگ گرفتن . (منتهی الارب ). تنگ کردن . فشردن . (منتخب اللغات ).<br /></font></div>'),
(174764, 'ضکاضک', '<span class=\"hlight\">ضکاضک .</span><font color=\"DarkGreen\"><b>[ ض ُ ض ِ ]</font></b> (ع ص ) کوتاه بالای پرگوشت . (منتهی الارب ).<br /></font></div>'),
(174765, 'ضکز', '<span class=\"hlight\">ضکز.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ، مص ) فشارش سخت . (منتهی الارب ).<br /></font></div>'),
(174766, 'ضکضاک', '<span class=\"hlight\">ضکضاک .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص ) پست بالا. مرد کوتاه . فربه پرگوشت . (منتهی الارب ).<br /></font></div>'),
(174767, 'ضکل', '<span class=\"hlight\">ضکل .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ) آب اندک . (منتهی الارب ).<br /></font></div>'),
(174768, 'ضی', '<span class=\"hlight\">ضی .</span> <font color=\"DarkGreen\"><b>[ ض َی ی ]</font></b> (ع مص ) ضوی . فراهم آمدن . <BR><font color=\"Blue\">◄</font> جای گرفتن و پناه بردن بکسی . <BR><font color=\"Blue\">◄</font> درآمدن در شب . (منتهی الارب ).<br /></font></div>'),
(174769, 'ضیابر', '<span class=\"hlight\">ضیابر.</span> <font color=\"DarkGreen\"><b>[ب َ ]</font></b> (اِخ ) مرکز بلوک گسگر در نزدیکی رشت (گیلان ).<br /></font></div>'),
(174770, 'ضیاح', '<span class=\"hlight\">ضیاح .</span> <font color=\"DarkGreen\"><b>[ ض َی ْ یا ]</font></b> (اِخ ) ابوالضیاح انصاری، نعمان بن ثابت . صحابی بدری . (منتهی الارب ).<br /></font></div>'),
(174771, 'ضیاح', '<span class=\"hlight\">ضیاح .</span> <font color=\"DarkGreen\"><b>[ ض َی ْ یا ]</font></b> (اِخ ) نام پدر محمد که محدثی است . (منتهی الارب ).<br /></font></div>'),
(174772, 'ضیاح', '<span class=\"hlight\">ضیاح .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص ) شیربسیارآب . (مهذب الاسماء). شیر تنک آب آمیخته . ضیح . (منتهی الارب ). لبن رقیق ممزوج . (فهرست مخزن الادویه ).<br /></font></div>'),
(174773, 'ضیاط', '<span class=\"hlight\">ضیاط.</span> <font color=\"DarkGreen\"><b>[ ض َی ْ یا ]</font></b> (ع ص ) مرد درشت و سخت . <BR><font color=\"Blue\">◄</font> مرد خمیده در رفتار. (منتهی الارب ).<br /></font></div>'),
(174774, 'ضیاطر', '<span class=\"hlight\">ضیاطر.</span> <font color=\"DarkGreen\"><b>[ ض َ طِ ]</font></b> (ع ص، اِ) ج ِ ضوطر. (منتهی الارب ). رجوع به ضوطر شود.<br /></font></div>'),
(174775, 'ضیاع', '<span class=\"hlight\">ضیاع .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ) زن و فرزندان و هرکه در نفقه و مؤنت او باشد. هر ضعیف و نیازمند که در امور و حوائج خود محتاج او بود. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> عیال . <BR><font color=\"Blue\">◄</font> آنکه افتقاد نداشته باشد. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> هلاک . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> نوعی از بوی خوش . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> وام . (مهذب الاسماء).<br /></font></div>'),
(174776, 'ضیاع', '<span class=\"hlight\">ضیاع .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b>(ع مص ) هلاک شدن . (منتهی الارب ) (منتخب اللغات ). ضایعشدن . (دهار). بباد شدن . (تاج المصادر). تلف گردیدن .بطلان . تباهی . تفقد. گویند: فلان مات ضیاعاً؛ مرد و کسی پروای او نکرد. ضیعة. ضیع. ضیَع. (منتهی الارب ).<br /></font></div>'),
(174777, 'ضیاع', '<span class=\"hlight\">ضیاع .</span> (ع ص، اِ) ج ِ ضایع. (منتهی الارب ). رجوع به ضایع شود. <BR><font color=\"Blue\">◄</font> ج ِ ضیعة، بمعنی خواسته و زمین و آب و درخت <span class=\"hlight\">:</span> <br />بس ای ملک که ضیاع من و عقار مرا<br />نه آفتاب مساحت کند نه باد شمال .<br /> <font color=\"Red\">غضائری .</font><br />این همی گوید گشتم بغلام و بستور<br />وآن همی گوید گشتم به ضیاع و به عقار.<br /> <font color=\"Red\">فرخی .</font><br />قیمت ضیاع از درم بدانگی بازآمده . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٦٢٠</span>). او را عفو کرد و ضیاع گوزگانان به وی ارزانی داشت . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٦٤</span>). دو قباله نبشته بودند همه اسباب و ضیاع حسنک را بجمله از جهت سلطان . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٨٢</span>). یک یک ضیاع را نام بر وی خواندند و وی اقرار کرد به فروختن آن . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٨٢</span>). چندان غلام و ضیاع و اسباب زر و سیم و نعمت هیچ او را سود نداشت . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٨٤</span>). ابونعیم مدتی در آن سخط بماند چنانکه ارتفاع آن ضیاعها به نوشتکین رسید. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٨٤</span>).بوسعید سهل بروزگار گذشته وی را بسیار خدمتهای پسندیده از دل کرده بود، چه بدان وقت که ضیاع خاص می داشت ... و چه در سایر اوقات . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٢٤</span>). پس از وفات سلطان محمود... صاحبدیوانی غزنه بدو <font color=\"DarkGreen\"><b>[ ابوسعید سهل ]</font></b> داده آمد با ضیاع خاص . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٢٤</span>).<br />گرگ و پلنگ گرسنه، میش و بره برند<br />وینها ضیاع و ملک یتیمان همی برند.<br /> <font color=\"Red\">ناصرخسرو.</font><br />امیدت بباغ بهشت است ازیرا<br />که در آرزوی ضیاع و عقاری .<br /> <font color=\"Red\">ناصرخسرو.</font><br />دانش به از ضیاع و به از جاه و مال و ملک <br />این خاطر خطیر چنین گفت مر مرا.<br /> <font color=\"Red\">ناصرخسرو.</font><br />ازداده ٔ تو اکنون چندانکه بنده راست <br />کس را یسار و مال و ضیاع و عقار نیست .<br /> <font color=\"Red\">مسعودسعد.</font><br />سازم از جود تو ضیاع و عقار<br />گیرم از مدح تو رفیق و قرین .<br /> <font color=\"Red\">مسعودسعد.</font><br />من یک فرومایه بودم اکنون بدولت خداوند پانصدهزاردینار زیادت دارم، بی ضیاع و چهارپا و بنده و آزاد.(نوروزنامه ). رود سپاهان از کوهها حایاد(؟) بیاید وچندان ضیاع را آب دهد و بعضی در ریگ ناپیدا شود. (مجمل التواریخ ). و از وی ضیاع بسیار مانده است . (کلیله و دمنه ). املاک هلاک شد و ضیاع به ضیاع رسید. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">١٠</span>). سلطان ضیاع و املاک ایشان بنواحی غرش از ایشان بخرید. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٤٧</span>). ضیاع و عقار فراوان بر آن وقف فرمود. (ترجمه ٔ تاریخ یمینی <span class=\"hlight\" dir=\"rtl\">٤٤١</span>).<br />دادشان چندین ضیاع و باغ و راغ <br />از چپ واز راست ازبهر فراغ .<br /> <font color=\"Red\">مولوی .</font><br />فضل مردان بر زنان ای بوشجاع <br />نیست بهر قوّت و کسب و ضیاع .<br /> <font color=\"Red\">مولوی .</font><br />زن کنی خانه باید و پس کار<br />بعد از آن بنده و ضیاع و عقار.<br /><font color=\"Red\">اوحدی .</font><br /></font></div>'),
(174778, 'ضیاغم', '<span class=\"hlight\">ضیاغم .</span> <font color=\"DarkGreen\"><b>[ ض َ غ ِ ]</font></b> (ع اِ) ج ِ ضیغم .<br /></font></div>'),
(174779, 'ضیاغمة', '<span class=\"hlight\">ضیاغمة.</span> <font color=\"DarkGreen\"><b>[ ض َ غ ِ م َ ]</font></b> (اِخ ) عشیره ای از قبیله ٔ آل کثیر از طوایف خوزستان ایران از طایفه ٔ عنافجه که در اراضی بین رود دزفول و رود شوشتر متوقف می باشند.<br /></font></div>'),
(174780, 'ضیافات', '<span class=\"hlight\">ضیافات .</span> (ع اِ) ج ِ ضیافة. (مهذب الاسماء).<br /></font></div>'),
(174781, 'ضیافت', '<span class=\"hlight\">ضیافت .</span> <font color=\"DarkGreen\"><b>[ ف َ ]</font></b> (ع اِمص، اِ) مهمانی . (دهار) (مهذب الاسماء). میهمانی . سور. ج، ضیافات . (مهذب الاسماء) <span class=\"hlight\">:</span> کفشگر... بضیافت بعضی از دوستان رفت . (کلیله و دمنه ). ایشان را بسرای ضیافت بردند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٣٤</span>).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">ضیافت پای پس دارد</span> .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضیافت آب حمام </span> ؛ کنایه از تواضع خشک است <span class=\"hlight\">:</span> <br />بیا که گر نکنم تر دماغت از جامی <br />کنم ضیافت خشکت به آب حمامی .<br /> <font color=\"Red\">مسیح کاشی (از آنندراج ).</font><br />ضیافت (نزد یهود) آن است که غالباً ازبرای امر مهم و عمده ای مثل از شیر بازگرفتن و مفارقت از دوستان و میلاد و عیش و شادی فراهم می کردند و ولیمه را رئیسی بود که امورات ولیمه بعهده ٔ وی موکول بود. (قاموس مقدس ). <BR><font color=\"Blue\">◄</font> (مص ) ضیافة. مهمان شدن نزد کسی . ضیف . (منتهی الارب ). بمهمانی آمدن نزد کسی . (منتخب اللغات ). مهمان شدن . (زوزنی ).<br /></font></div>'),
(174782, 'ضیافت خانه', '<span class=\"hlight\">ضیافت خانه .</span> <font color=\"DarkGreen\"><b>[ ف َ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب )مهمانخانه <span class=\"hlight\">:</span> به ضیافت خانه ٔ عقارب نواهس و حَیّات لواحس بشتافت . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٥٦</span>).<br />از ضیافت خانه ٔ درد تو دل نومیدنیست <br />هر نصیبی زآن سر خوان با جگرخواران رسید.<br /><font color=\"Red\"> کمال خجندی .</font><br /></font></div>'),
(174783, 'ضیافت خور', '<span class=\"hlight\">ضیافت خور.</span> <font color=\"DarkGreen\"><b>[ ف َ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ ]</font></b> (نف مرکب ) کسی که بمهمانی رود. میهمان .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">ضیافت خور خوش آمدگوی باشد</span> . (جامع التمثیل ).<br /></font></div>'),
(174784, 'ضیاق', '<span class=\"hlight\">ضیاق .</span> (ع اِ) پاره ای از خرقه های خوشبوآلوده که زنان بخود برگیرند. (منتهی الارب ).<br /></font></div>'),
(174785, 'ضیان', '<span class=\"hlight\">ضیان .</span> <font color=\"DarkGreen\"><b>[ ض َی ْ یا ]</font></b> (ع اِ) گیاهی است از جنس پیچک و زینتی است .<br /></font></div>'),
(174786, 'ضیاون', '<span class=\"hlight\">ضیاون .</span> <font color=\"DarkGreen\"><b>[ ض َ وِ ]</font></b> (ع اِ) ج ِ ضَیْوَن . (منتهی الارب ).<br /></font></div>'),
(174787, 'ضیاپاش', '<span class=\"hlight\">ضیاپاش .</span> (نف مرکب ) ضیاگستر. (آنندراج ). روشنائی بخش .<br /></font></div>'),
(174788, 'ضیاکل', '<span class=\"hlight\">ضیاکل .</span> <font color=\"DarkGreen\"><b>[ ض َ ک ِ ]</font></b> (ع ص، اِ) ج ِ ضَیکل . (منتهی الارب ). رجوع به ضیکل شود.<br /></font></div>'),
(174789, 'ضیاکلة', '<span class=\"hlight\">ضیاکلة.</span> <font color=\"DarkGreen\"><b>[ ض َ ک ِ ل َ ]</font></b> (ع ص، اِ) ج ِ ضیکل . (منتهی الارب ). رجوع به ضیکل شود.<br /></font></div>'),
(174790, 'ضیاگستر', '<span class=\"hlight\">ضیاگستر.</span> <font color=\"DarkGreen\"><b>[ گ ُ ت َ ]</font></b> (نف مرکب ) ضیاپاش . روشنائی بخش . (آنندراج ) <span class=\"hlight\">:</span> <br />گاه چون اشکال اقلیدس سر اندر سر شود<br />گاه چون خورشید رخشنده ضیاگستر شود.<br /> <font color=\"Red\">فرخی .</font><br />ظل ّ طوبی است بر آنکس که ضیاگستر شد<br />آفتاب ِ شرف و حشمت و سلطان شرف .<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(174791, 'ضیاگوگ الپ', '<span class=\"hlight\">ضیاگوگ الپ .</span> <font color=\"DarkGreen\"><b>[ اَ ]</font></b> (اِخ ) از نویسندگان ترک و از متعصبین پان تورانیزم . توضیح آنکه کلمه ٔ تور که با کلمه ٔ ترک اندک شباهت لفظی دارد و بخصوصه که قسمتی از ایالتهای شرقی ایران زمین قدیم و در جزو آن خاک توران بعدها ترکستان روسیّه نامیده شده و خلط نویسندگان قدیم ما، همه ٔ اینها سبب شده که ترکها خود را از تورانیان قدیم پندارند و گروهی از پیشروان و نویسندگان آنان شور بی اساسی ازبرای قوم توران در میان هموطنان خود برانگیخته اند، از آن جمله ضیاگوگ الپ که در سال <span class=\"hlight\" dir=\"rtl\">١٣٤٠</span> هَ . ق . درگذشت، گوید:«ای فرزندان اوقوزخان هرگز این کشوری که توران نام دارد از یاد مدهید». در جای دیگر گوید: «وطن ترکها نه ترکیه است نه ترکستان بلکه وطن آنان مملکت بزرگ و جاودانی توران است » . بعقیده ٔ اینگونه نویسندگان ترک، آنان بازماندگان تورانیانند، از این جهت بطرز بسیار عجیبی فضایلی ازبرای تورانیان قائل شده اند. (یسنا تألیف پورداود ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٣</span>).<br /></font></div>'),
(174792, 'ضیب', '<span class=\"hlight\">ضیب .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ) ضئب . جانورکیست دریائی . (منتهی الارب ). از دواب البحر. <BR><font color=\"Blue\">◄</font> حَب ّ لؤلؤ. (فهرست مخزن الادویه ). دانه ٔ مروارید. (منتهی الارب ).<br /></font></div>'),
(174793, 'ضیبر', '<span class=\"hlight\">ضیبر.</span> <font color=\"DarkGreen\"><b>[ ض َ ب َ ]</font></b> (اِخ ) نام کوهی است به حجاز. (معجم البلدان ).<br /></font></div>'),
(174794, 'ضیثم', '<span class=\"hlight\">ضیثم .</span> <font color=\"DarkGreen\"><b>[ ض َ ث َ ]</font></b> (ع اِ) شیر بیشه . (منتهی الارب ). اسد. شیر. (مهذب الاسماء). ضیغم . (آنندراج ).<br /></font></div>'),
(174795, 'ضیج', '<span class=\"hlight\">ضیج .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) ضیجان . میل کردن . (منتهی الارب ) (منتخب اللغات ). عدول کردن . (منتخب اللغات ). چسبیدن . <BR><font color=\"Blue\">◄</font> خطا شدن تیر. (تاج المصادر). خطا کردن تیر از نشانه . تخلف تیر از نشانه .<br /></font></div>'),
(174796, 'ضیجان', '<span class=\"hlight\">ضیجان .</span> <font color=\"DarkGreen\"><b>[ ض َ ی َ ]</font></b> (ع مص ) ضیج . میل کردن . (منتهی الارب ). چسبیدن . عدول کردن . (منتخب اللغات ).<br /></font></div>'),
(174797, 'ضیح', '<span class=\"hlight\">ضیح .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ) شهد. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> مقل پخته، که بهندی کوکل گویند. (منتهی الارب ). مقل پختج . (فهرست مخزن الادویه ). <BR><font color=\"Blue\">◄</font> شیر تنک آب آمیخته .(منتهی الارب ). شیر به آب آمیخته . (منتخب اللغات ).<br /></font></div>'),
(174798, 'ضیح', '<span class=\"hlight\">ضیح .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) به آب آمیختن شیر را. <BR><font color=\"Blue\">◄</font> خراب و خالی گردیدن شهرها. (منتهی الارب ).<br /></font></div>'),
(174799, 'ضیح', '<span class=\"hlight\">ضیح .</span> (ع اِ) آفتاب . <BR><font color=\"Blue\">◄</font> روشنی آفتاب . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> زمین هموار. <BR><font color=\"Blue\">◄</font> هرچه بر آن آفتاب رسیده باشد. <BR><font color=\"Blue\">◄</font> بقول عامه از اتباع ریح است، و گویند: جاء فلان بالضیح و الریح ؛ یعنی آورد تمامی آن که بر وی آفتاب می تابد و باد می وزد. (منتهی الارب ).<br /></font></div>'),
(174800, 'ضیر', '<span class=\"hlight\">ضیر.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) ضرر: لا ضیر علیکم ؛ ای لا ضرر فی تأخیر الصلوة بالنوم . ضور. گزند رسانیدن کار. (منتهی الارب ). گزند کردن . (دهار).مضرت کردن . (زوزنی ). <BR><font color=\"Blue\">◄</font> گزند. <BR><font color=\"Blue\">◄</font> زیان کردن . (منتهی الارب ) (تاج المصادر). <BR><font color=\"Blue\">◄</font> بیچارگی . <BR><font color=\"Blue\">◄</font> احتیاج . (منتهی الارب ).<br /></font></div>'),
(174801, 'ضیراک', '<span class=\"hlight\">ضیراک .</span> (ع اِ) نام نوعی از ماهی . (فهرست مخزن الادویه ). ماهی . (منتهی الارب ).<br /></font></div>'),
(174802, 'ضیرم', '<span class=\"hlight\">ضیرم .</span> <font color=\"DarkGreen\"><b>[ ض َ رَ ]</font></b> (ع ص ) سوخته . (منتهی الارب ).<br /></font></div>'),
(174803, 'ضیز', '<span class=\"hlight\">ضیز.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) کم کردن حق کسی را.(منتهی الارب ). نقصان کردن . (زوزنی ). <BR><font color=\"Blue\">◄</font> ستم کردن بر کسی . (منتهی الارب ). جور کردن . (زوزنی ).<br /></font></div>'),
(174804, 'ضیزان', '<span class=\"hlight\">ضیزان .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص ) اسپی بود که گاهی ماده را در زیر نکشید و هرگز بر ماده نجهید. (منتهی الارب ).<br /></font></div>'),
(174805, 'ضیزن', '<span class=\"hlight\">ضیزن .</span> <font color=\"DarkGreen\"><b>[ ض َ زَ ]</font></b> (اِخ ) ابن معاویة العبید السلیحی القضاعی . فرمانروای شهر خضر در میان دجله و فرات بعهد شاپور پسر اردشیر. صاحب مجمل التواریخ و القصص در ذکر پادشاهی شاپور پسر اردشیر آرد:... او را <font color=\"DarkGreen\"><b>[ شاپور را ]</font></b> با ضیزن ملک عرب حرب افتاد و او از دشت رومیان بود. اندر حصار رفت از شاپور تا دخترش بر شاپور شیفته شد و حصار به دست شاپور اندر نهاد و ضیزن کشته <font color=\"DarkGreen\"><b>[ شد ]</font></b> و <font color=\"DarkGreen\"><b>[ شاپور ]</font></b> این دختر را به زن کرد و باز بکشتش چنانکه گفته شود، و اندر شاهنامه ٔ فردوسی چنانست که این حادثه شاپور ذوالاکتاف را افتاد و نام ضیزن طایر گوید، در سیرالملوک چنانست که شاپور اردشیر بود، و اﷲ اعلم . ابن البلخی در فارسنامه گوید: و از سرگذشت او <font color=\"DarkGreen\"><b>[ شاپور پسر اردشیر ]</font></b>یکی آن است که امیری بوده ست از امرای عرب ضیزن نام از قبیله ٔ بنی قضاعه و خلقی بسیار بر وی جمع شده بود ودر کوهها که بحدود تکریت است قلعه ای داشت محکم و دروقتی که شاپور بخراسان بود بی ادبیها و دست درازیها کرد، پس چون شاپور بازآمد قصد او کرد و مدتی حصار او می داد و قلعه ٔ او نمی شایست <font color=\"DarkGreen\"><b>[ ظ: نمیتانست، یا نمیدانست، یا نمی یارست ]</font></b> ستدن و این ضیزن دختری داشت نضیره نام شاپور را بدید و بر وی عاشق شد و در سِر پیغام داد به شابور کی اگر عهد کنی مرا بخواهی عیب و عوار این دز تو را بنمایم تا بستانی، شاپور بر این جملت عهد بست و دختر راه گشادن آن بدو نمود و قلعه بستد و ضیزن را و هر کی در آن قلعه بودند بکشت و این دختر رابیاورد و زن کرد، و سخت پاکیزه و باجمال بود، و گویند یک شب با شاپور بهم در جامه ٔ خواب خفته بود، می نالید، شاپور پرسید که از چه می نالی، این دختر گفت در زیر پهلوی من چیزی است که مرا رنج می رساند، چون بدیدند ورق موری (؟) بر پهلوی او سخت شده بود و آن را مجروح کرده و خون روان شده، شاپور از آن در تعجب ماند و او را گفت پدرت تو را چه غذا می داد که چنین نازک برآمده ای، دختر گفت مرا مغز استخوان و مسکه و انگبین مصفی به غذا دادی و شراب مروّق بجای آب . شاپور گفت پس چون تو بپدر نشایستی که تو را بدین سان پرورید بدیگری چگونه شایی . بفرمود تا گیسوهای او را در دنبال اسب توسن بستند تا می دوید و او را پاره پاره گردانید.<br />زرکلی صاحب الاعلام گوید:آثاری از ضیزن بجای مانده که از آنجمله عُریسات است (در میان کوفه و قادسیه ) و طیزناباد که محرف ضیزن آباد است نام داشته . در حبیب السیر نیز سرپیچی ضیزن و کشته شدن وی به دست شاپور مشروح آمده است . رجوع به حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٩</span> و مجمل التواریخ و القصص ص <span class=\"hlight\" dir=\"rtl\">٦٣</span> و الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤١</span> و فارسنامه ص <span class=\"hlight\" dir=\"rtl\">٦١</span> و <span class=\"hlight\" dir=\"rtl\">٦٢</span> شود.<br /></font></div>'),
(174806, 'ضیزن', '<span class=\"hlight\">ضیزن .</span> <font color=\"DarkGreen\"><b>[ ض َ زَ ]</font></b> (ع ص، اِ) طفیلی . طفیل . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> نگاهبان معتمد. (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> فرزندان مرد و عیال و انبازان او. (منتهی الارب ). اولاد و عیال مرد و شریکان او. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> آب ده چالاک . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بازرگانی که متاع را نگاه دارد تا گران فروشد. (منتهی الارب ). محتکر. <BR><font color=\"Blue\">◄</font> مس و مانند آن که میان سوراخ بکره یا تیر بکره باشد. (منتهی الارب ). چوبی که بکره را بگیرد. چوبی که سوراخ بکره را تنگ کند اگر فراخ گردد. <BR><font color=\"Blue\">◄</font> فرزندکه مزاحم پدر خود باشد درباره ٔ زن وی . (منتهی الارب ). آنکه پدر را مزاحمت رساند و با زن پدر یکی باشد. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> آنکه بر سر چاه زحمت دهد و انبوهی کند. (منتهی الارب ). آنکه بر سر چاه هنگام آب خوردن زحمت دهد و انبوهی کند. (منتخب اللغات ).<br /></font></div>'),
(174807, 'ضیزن', '<span class=\"hlight\">ضیزن .</span> <font color=\"DarkGreen\"><b>[ ض َزَ ]</font></b> (اِخ ) بتی بوده است عرب را. رجوع به بت شود.<br /></font></div>'),
(174808, 'ضیزی', '<span class=\"hlight\">ضیزی .</span> <font color=\"DarkGreen\"><b>[ زا ]</font></b> (ع ص ) قسمةٌ ضیزی ؛ قسمت ناراست (لغةً فی الهمزة، ای ضئزی ). (منتهی الارب ). قسمةٌ جائره، قال اﷲ تعالی <span class=\"hlight\">:</span> قسمةٌ ضیزی (قرآن <span class=\"hlight\" dir=\"rtl\">٢٢/٥٣</span>)؛ ای جائرة. بهره ٔ کم کرده . بهره ٔ ناراست . قسمت ناقصه . بهره ٔ به ستم . قسمت غیرعادله . بخش بیدادی .<br /></font></div>'),
(174809, 'ضیس', '<span class=\"hlight\">ضیس .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص ) ضَیِّس . ضائس . گیاه پژمریده ٔ در خشک شدن درآمده . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) صابون . (مهذب الاسماء). ضیس (بکسراول )، بعربی اسم صابون است . (فهرست مخزن الادویه ).<br /></font></div>'),
(174810, 'ضیس', '<span class=\"hlight\">ضیس .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) خشک شدن گرفتن . (منتهی الارب ).<br /></font></div>'),
(174811, 'ضیس', '<span class=\"hlight\">ضیس .</span> <font color=\"DarkGreen\"><b>[ ض َی ْ ی ِ ]</font></b> (ع ص ) ضائس . ضَیس . گیاه پژمریده ٔ در خشک شدن درآمده . (منتهی الارب ).<br /></font></div>'),
(174812, 'ضیط', '<span class=\"hlight\">ضیط.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) ضَیَطان . جنبانیدن دو دوش و بدن را در رفتار با بسیاری گوشت و فروهشتگی اندام . (منتهی الارب ).<br /></font></div>'),
(174813, 'ضیطار', '<span class=\"hlight\">ضیطار.</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص ) ضوطر. ضَیْطَر. مرد کلان جثه . فربه ناکس بزرگ سرین . <BR><font color=\"Blue\">◄</font> مرد شگرف بی خیر. <BR><font color=\"Blue\">◄</font> بازرگانی که سفر نکند و از جای خود بجای دیگر نرود برای فروختن . (منتهی الارب ).<br /></font></div>'),
(174814, 'ضیطارون', '<span class=\"hlight\">ضیطارون .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص، اِ) ج ِ ضَوطَر. (منتهی الارب ). رجوع به ضوطر شود.<br /></font></div>'),
(174815, 'ضیطان', '<span class=\"hlight\">ضیطان .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص ) نعت ازضیط. رجوع به ضیط شود. (منتهی الارب ). مرد دوش و بدن جنباننده با بسیاری گوشت در رفتار. (منتهی الارب ).<br /></font></div>'),
(174816, 'ضیطان', '<span class=\"hlight\">ضیطان .</span> <font color=\"DarkGreen\"><b>[ ض َ ی َ ]</font></b> (ع مص ) ضیط. جنبانیدن دوش و اندام را در رفتار با بسیاری گوشت و فروهشتگی اندام . ضیطنة. (منتهی الارب ).<br /></font></div>'),
(174817, 'ضیطر', '<span class=\"hlight\">ضیطر.</span> <font color=\"DarkGreen\"><b>[ ض َ طَ ]</font></b> (ع ص ) ضَوطر. ضَیطار. مرد کلان جثه . فربه ناکس بزرگ سرین . (منتهی الارب ). بزرگ شکم . بزرگ و فرومایه . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> مرد شگرف بی خیر. (منتهی الارب ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(174818, 'ضیطری', '<span class=\"hlight\">ضیطری .</span> <font color=\"DarkGreen\"><b>[ ض َطَ را ]</font></b> (ع ص ) ضوطار. آنکه در بازار بدون رأس المال درآید و در کسب مطلوب حیله ها جوید. (منتهی الارب ).<br /></font></div>'),
(174819, 'ضیطن', '<span class=\"hlight\">ضیطن .</span> <font color=\"DarkGreen\"><b>[ ض َ طَ ]</font></b> (ع ص ) ضَیطان . مرد دوش و بدن جنباننده با بسیاری گوشت در رفتار. (منتهی الارب ).<br /></font></div>'),
(174820, 'ضیطنة', '<span class=\"hlight\">ضیطنة.</span> <font color=\"DarkGreen\"><b>[ ض َ طَ ن َ ]</font></b> (ع مص ) ضیطان . به رفتار آمدن پس جنبانیدن هر دو دوش و بدن را با بسیاری گوشت . (منتهی الارب ).<br /></font></div>'),
(174821, 'ضیع', '<span class=\"hlight\">ضیع.</span> <font color=\"DarkGreen\"><b>[ ض َ <span class=\"hlight\" dir=\"rtl\">/</span> ضی ]</font></b> (ع مص ) ضیاع . ضَیعة. هلاک شدن . (منتهی الارب ) (منتخب اللغات ). تلف گردیدن . <BR><font color=\"Blue\">◄</font> بی تیمار و هیچکاره گردیدن . (منتهی الارب ).<br /></font></div>'),
(174822, 'ضیع', '<span class=\"hlight\">ضیع.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع اِ) ج ِ ضیعة. (منتهی الارب ).<br /></font></div>'),
(174823, 'ضیع', '<span class=\"hlight\">ضیع.</span> <font color=\"DarkGreen\"><b>[ ی َ]</font></b> (ع مص ) ضَیاع . رجوع به ضیاع شود. (منتهی الارب ).<br /></font></div>'),
(174824, 'ضیعان', '<span class=\"hlight\">ضیعان .</span> (ع اِ) ج ِ ضُوَع و ضِوَع . (منتهی الارب ).<br /></font></div>'),
(174825, 'ضیعت', '<span class=\"hlight\">ضیعت .</span> <font color=\"DarkGreen\"><b>[ ض َ ع َ ]</font></b> (ع اِ) آب و زمین و مانند آن . (منتهی الارب ). زمین کشت . (دهار). زمین بسیاربرآمد از غله و جز آن . (منتهی الارب ). زمین برومند. آب و زمین که در او غله شود. (منتخب اللغات ). زمین و آب و درخت . (مهذب الاسماء). ج، ضیَع، ضیعات، ضیاع <span class=\"hlight\">:</span> سوگندان بر زبان راند که جز ضیعتی که بگوزگانان دارد و این چه نخست کرده است هیچ چیز ندارد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٦٤</span>). آنچه مخفف بود بگوزگانان به وقت و فرصت می فرستاد و ضیعتی نیکو خرید آنجا. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٦٤</span>). و می شنویم که قاضی بُست بوالحسن بولانی و پسرش بوبکر سخت تنگدستند و از کس چیزی نستانند و اندک مایه ضیعتی دارند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٢١</span>). یک کیسه به پدرباید داد و یک کیسه به پسر تا خویشتن را ضیعتکی خرند حلال، و فراختر بتوانند زیست . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٢١</span>).همی خواهم که بدان ضیعتی خرم اکنون ضیعتی بیافتم که بهر وقت ماننده ٔ آن به دست نیاید. (تاریخ بیهقی ).<br />ملت اسلام ضیعتی است مبارک <br />کشت و درختش ز مؤمن است و مسلمان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ای زهدفروشنده تو از قال و مقالی <br />با مرکب و با ضیعت و با سندس و قالی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />اندرین تنگی بی راحت بنشسته <br />خالی از نعمت و از ضیعت دهقانی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بشش طریق جبایت ستاندم از عامه <br />ز خانه و ز دکان و ز باغ و ضیعت و تیم .<br /> <font color=\"Red\">سوزنی .</font><br /><BR><font color=\"Blue\">◄</font> خواسته . (مهذب الاسماء). اسباب . متاع . کالا. <BR><font color=\"Blue\">◄</font> حرفه و صنعت و پیشه ٔ مرد. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بازرگانی . (منتهی الارب ).<br /></font></div>'),
(174826, 'ضیغم', '<span class=\"hlight\">ضیغم .</span> <font color=\"DarkGreen\"><b>[ ض َ غ َ ]</font></b> (اِخ ) ابن مالک مکنی به ابومالک العابد. مردی پرهیزکار ودیندار و متقی بود و از زهد و ورع وی حکایتها نقل کرده اند. عبیداﷲبن عمر قال : اتیت صاحباً لی یقال له عمران بن مسلم فارانی موضعین مبتلین فی مسجده احدهما بحذاء الاَّخر، فقلت ما هذا، قال هذا و اﷲ من دموع ضیغم البارحة بین المغرب و العشاء و هو راکع. ازهربن مروان الرقاشی قال رأیت ضیغم العابد و کنت اذا رأیت رجلاً لایشبه الناس من الخشوع و الضر و طول الحزن . محمدبن الحسین قال : حدثنی مالک بن ضیغم قال قالت اُمﱡه یعنی ضیغماً ذات َ یوم : ضیغم ! قال : لبیک یا اماه . قالت کیف فرحک بالقدوم علی اﷲ. قال فحدثنی غیر واحد من اهله انه صاح صیحةً لم یسمعوه صاح مثلها قط و سقط مغشیاً علیه فجلست العجوز تبکی عند رأسه و تقول : بابی انت ما نستطیع ان نذکر بین یدیک شیئاً من امر ربک . قال و قالت له یوماً: ضیغم ! قال : لبیک یا اماه . قالت تحب الموت ؟ قال نعم یا اماه . قالت و لِم َ یا بنی ؟ قال رجاء خیر ما عند اﷲ. قال فبکت العجوز و بکی فتسامع اهل الدار فجلسوا یبکون لبکائهم . قال و قالت له یوماً آخر: ضیغم ! قال : لبیک یا اماه . قالت تحب الموت ؟ قال لا یا اماه . قالت لِم َ یا بنی ؟ قال لکثرة تفریطی و غفلتی عن نفسی . قال فبکت العجوز و بکی ضیغم و اجتمع اهل الدار و جعلوا یبکون، و کانت امه عربیة کأنها من اهل البادیة. رجوع به صفة الصفوة ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٠</span> شود.<br /></font></div>'),
(174827, 'ضیغم', '<span class=\"hlight\">ضیغم .</span> <font color=\"DarkGreen\"><b>[ ض َ غ َ ]</font></b> (ع اِ) شیر بیشه . (منتهی الارب ). شیر. اسد. شیر قوی . شیر درنده . (منتخب اللغات ). شیر گزنده . (دهار). ج، ضیاغم <span class=\"hlight\">:</span> <br />کس را بجهان چون پسر تو پسری نیست <br />آهوبچه کی باشد چون بچه ٔ ضیغم .<br /> <font color=\"Red\">فرخی .</font><br />وز خلق یکی بسان میش است <br />پرخیر و یکی به شرّ ضیغم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />نیروده توست ناف خرچنگ <br />عشرتگه تو دهان ضیغم .<br /> <font color=\"Red\">خاقانی .</font><br />به اقبال تو از سگی برنتابم <br />که طبع هنر کم ز ضیغم ندارم .<br /> <font color=\"Red\">خاقانی .</font><br />پادشاه وحوش از آن باشد<br />که بخود کار خود کند ضیغم .<br /> <font color=\"Red\">ابن یمین .</font><br /><BR><font color=\"Blue\">◄</font> (ص ) گزنده . (منتهی الارب ) (منتخب اللغات ).<br /></font></div>'),
(174828, 'ضیغمی', '<span class=\"hlight\">ضیغمی .</span> <font color=\"DarkGreen\"><b>[ ض َ غ َ می ی ]</font></b> (ع اِ) شیر بیشه . (منتهی الارب ). اسد. (فهرست مخزن الادویه ).<br /></font></div>'),
(174829, 'ضیف', '<span class=\"hlight\">ضیف .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ) پهلو. (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> بازو. <BR><font color=\"Blue\">◄</font> ضیفا الوادی ؛ دو کرانه ٔ رودبار. (منتهی الارب ). کنار رود. (مهذب الاسماء).<br /></font></div>'),
(174830, 'ضیف', '<span class=\"hlight\">ضیف .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (اِخ ) احمد (الدکتور). مدرس بالجامعة المصریة. له مقدمة لدرسة بلاغة العرب و بلاغةالعرب فی الاندلس . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٢٢٠</span>).<br /></font></div>'),
(174831, 'ضیف', '<span class=\"hlight\">ضیف .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) نزدیک شدن آفتاب به فروشدن . (منتهی الارب ). نزدیک شدن آفتاب بغروب . (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> بیک سو رفتن تیر از نشانه . <BR><font color=\"Blue\">◄</font> فرودآمدن غم بر کسی . (منتهی الارب ) (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> مهمان شدن نزد کسی . ضیافة. (منتهی الارب ).مهمان شدن . (زوزنی ). مهمان داشتن کسی را. (منتخب اللغات ). <BR><font color=\"Blue\">◄</font> بی نمازی شدن زن . <BR><font color=\"Blue\">◄</font> چسبیدن و میل کردن . (منتهی الارب ). چسبیدن . (زوزنی ).<br /></font></div>'),
(174832, 'ضیف', '<span class=\"hlight\">ضیف .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ) میهمان . نزیل . مهمان (واحد و جمع و مؤنث و مذکر در وی یکسانست ). (منتهی الارب ) (مهذب الاسماء). مهمان و میهمانان . (دهار). و قد یجمع علی اَضیاف و ضیفان و ضیوف . (منتهی الارب ) <span class=\"hlight\">:</span> <br />گفت واللَّه تا ابد ضیف توام <br />هر کجا باشم بهر جا که روم .<br /> <font color=\"Red\">مولوی .</font><br />ضیف باهمت چو زآشی کم خورد<br />صاحب خوان آش بهتر آورد.<br /> <font color=\"Red\">مولوی .</font><br />هرچه آید از جهان غیب وش <br />در دلت ضیفست او را دار خوش .<br /> <font color=\"Red\">مولوی .</font><br />ضیف عیسی را چو استقبال کرد<br />چون شکر گویی که پیوست او به ورد.<br /> <font color=\"Red\">مولوی .</font><br /><BR><font color=\"Blue\">◄</font> (اِخ ) اسپی از نسل حرون . <BR><font color=\"Blue\">◄</font> نام مردی . (منتهی الارب ).<br /></font></div>'),
(174833, 'ضیفان', '<span class=\"hlight\">ضیفان .</span> (ع اِ) ج ِ ضَیف . (منتهی الارب ). رجوع به ضیف شود.<br /></font></div>'),
(174834, 'ضیفة', '<span class=\"hlight\">ضیفة.</span> <font color=\"DarkGreen\"><b>[ض َ ف َ ]</font></b> (ع ص، اِ) تأنیث ضیف . زن مهمان . <BR><font color=\"Blue\">◄</font> زن حائض . <BR><font color=\"Blue\">◄</font> بی نمازی . (منتهی الارب ).<br /></font></div>'),
(174835, 'ضیفن', '<span class=\"hlight\">ضیفن .</span> <font color=\"DarkGreen\"><b>[ ض َ ف َ ]</font></b> (ع ص، اِ) طُفیلی . (دهار) (منتهی الارب ) (مهذب الاسماء). مهمان ناخوانده . ج، ضیافن، ضیوف . (مهذب الاسماء).<br /></font></div>'),
(174836, 'ضیفوفة', '<span class=\"hlight\">ضیفوفة.</span> <font color=\"DarkGreen\"><b>[ ض َ ف َ ]</font></b> (ع مص ) بگشتن تیر از نشانه . (زوزنی ).<br /></font></div>'),
(174837, 'ضیفی', '<span class=\"hlight\">ضیفی .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (اِخ ) جد ملک الحارث الرایش حمیری . (مجمل التواریخ و القصص ص <span class=\"hlight\" dir=\"rtl\">١٥٤</span>).<br /></font></div>'),
(174838, 'ضیق', '<span class=\"hlight\">ضیق .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع ص ) تنگ . <BR><font color=\"Blue\">◄</font> (اِ) تنگی . <BR><font color=\"Blue\">◄</font> شک که در دل گذرد. (بکسر اول نیز آید). <BR><font color=\"Blue\">◄</font> آنچه باعث تنگی سینه باشد. (منتهی الارب ). تنگی در دل و سینه . (منتخب اللغات ).<br /></font></div>'),
(174839, 'ضیق', '<span class=\"hlight\">ضیق .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ) ج ِ ضَیْقة. (منتهی الارب ).<br /></font></div>'),
(174840, 'ضیق', '<span class=\"hlight\">ضیق .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (اِخ ) از قرای یمامة. و آن را ضیق قرقری نیز گویند. (معجم البلدان ).<br /></font></div>'),
(174841, 'ضیق', '<span class=\"hlight\">ضیق .</span> <font color=\"DarkGreen\"><b>[ ض َ <span class=\"hlight\" dir=\"rtl\">/</span> ضی ]</font></b> (ع مص ) تنگ شدن . (منتخب اللغات ) (تاج المصادر) (زوزنی ) (منتهی الارب ) (دهار). <BR><font color=\"Blue\">◄</font> بخیل شدن مرد. <BR><font color=\"Blue\">◄</font> نگنجیدن چیز در چیزی . (منتهی الارب ).<br /></font></div>'),
(174842, 'ضیق', '<span class=\"hlight\">ضیق .</span> <font color=\"DarkGreen\"><b>[ ض َی ْ ی ِ ]</font></b> (ع ص ) تنگ . (منتهی الارب ) (منتخب اللغات ) (مهذب الاسماء).گویند: ضیق لیق ؛ اتباع . (مهذب الاسماء) <span class=\"hlight\">:</span> <br />خانه ٔ گهواره و ضیق مدار<br />تا تواند کرد بالغ انتشار.<br /> <font color=\"Red\">مولوی .</font><br /><BR><font color=\"Blue\">◄</font> بخیل . (منتخب اللغات ).<br /></font></div>'),
(174843, 'ضیق', '<span class=\"hlight\">ضیق .</span> (ع ص ) ضد سعه . تنگ . (منتهی الارب ) (منتخب اللغات ) (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> (اِ) شک در دل . شک که در دل گذرد (بفتح اول نیز آید). (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِمص ) تنگدستی . درویشی . <BR><font color=\"Blue\">◄</font> آنچه گاهی گشاده باشد وقتی تنگ، مانند سرای و جامه . (منتهی الارب ). تنگی در خانه و جامه و جز آن . (منتخب اللغات ). تنگی . مقابل وسعت، گشادی . ج، اضیاق <span class=\"hlight\">:</span> و لشکر ری از جانب مشهد داعی بسبب ضیق حال و قلت زاد و انقطاع امداد با جانب محمدآباد نشستند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٦٦</span>).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضیق حدقة</span> ؛ تنگ شدن ثقبه ٔ عنبیة. (ذخیره ٔ خوارزمشاهی ). از معتاد تنگتر بودن ثقبه ٔ عنبیه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضیق صدر</span> ؛ انقباض سینه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ضیق نَفَس </span> ؛ تنگی دم . کوته دمی . نام مرضی که بهندی دمه (دما) گویند. (غیاث ). نفس تنگی . تاسه . رَبو. بُهر. غَنص . (منتهی الارب ). ضریر انطاکی در تذکره گوید: الربو، و هو اشتغال قصبةالرّئه بمواد تعاوق المجری الطبیعی فان ضر بالنفس فهو «ضیق النفس » اوحلل المفاصل و القوی ̍ فهو «البهر» و ان لم یکن معه السکون الا قائماً مادّاً عنقه فهو الانتصاب . صاحب کشاف اصطلاحات الفنون گوید: ضیق نفس، نزد اطبّا با بیماری ربو یکیست چنانچه در قانونچه ذکر کرده، و در آقسرائی گوید: ضیق نفس عبارتست از اینکه هوائی که در نفس می باشد منفذی برای بیرون شدن خود نیابد مگر راهی بس تنگ که اندک اندک از آن مجری بیرون شود، و اما آفتی که در نفس می باشد سببش آفتی است که در عصب و پرده ٔ مجرای تنفس ایجاد شده و مناسبتر آن است که این بیماری را به عسرالنفس تعبیر کنند چه ضیق النفس آن است که آفت آن تنگی مجری باشد و ابداً آفتی که در عصب و پرده ٔ مجری تولید می شود ربطی به تنگی نفس ندارد، و ضیق نفس از مرض خناق اعم است، و اما ربو عبارتست از عسرالنفس که نفس بیمار در این بیماری نفس کسی را مانند است که بر اثر رنج و تعب بسیار به سختی نفَس زند، و نفس او را سرعت و تواتر و صغری همراه باشد، سواء کان معه او لا. هذا کلام الشیخ . و سمرقندی بین ضیق النفس و بهر و ربو فرقی قائل نیست و هر سه لفظ را مترادف می پندارد. و در حدودالامراض از گفتار قرشی نقل می کند که او گفته : هنگامی که هوا برای استنشاق داخل مجرای تنفس می شود و بیرون می آید اگر مانند آن بود که از مجرای تنگی می گذرد آن را ضیق النفس نامند - انتهی .<br /></font></div>'),
(174844, 'ضیق', '<span class=\"hlight\">ضیق .</span> (ع اِ) ج ِ ضیقة. (منتهی الارب ).<br /></font></div>'),
(174845, 'ضیقی', '<span class=\"hlight\">ضیقی .</span> <font color=\"DarkGreen\"><b>[ قا ]</font></b> (ع ن تف ) ضوقی . تأنیث ِ اضیق . (منتهی الارب ).<br /></font></div>'),
(174846, 'ضیم', '<span class=\"hlight\">ضیم .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِ)ظلم و ستم . (منتهی الارب ) (مهذب الاسماء). ج، ضیوم <span class=\"hlight\">:</span> و شرف نفس هرآینه از تحمل حیف ابی تواند بود و بقبول ضیم تن در نتوان داد. (جهانگشای جوینی ).<br /></font></div>'),
(174847, 'ضیم', '<span class=\"hlight\">ضیم .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) کم کردن حق کسی را. (منتهی الارب ). نقصان کردن حق . (منتخب اللغات ) (تاج المصادر). ستم کردن . (منتخب اللغات ). بیدادی کردن . بیدادی . جور کردن . (تاج المصادر). ضیم الرجل (مجهولاً)؛ ستم کرده شد. کذا ضُیِم َ الرجل و ضوم الرجل . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> از مضرت نه اندیشیدن در انتقام . (غیاث ).<br /></font></div>'),
(174848, 'ضیم', '<span class=\"hlight\">ضیم .</span> (ع اِ) ناحیه ٔ کوه . (منتهی الارب ) (منتخب اللغات ). کرانه ٔ کوه . (منتهی الارب ). کنار. (منتخب اللغات ). کنار رود. (مهذب الاسماء).<br /></font></div>'),
(174849, 'ضیم', '<span class=\"hlight\">ضیم .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (اِخ ) رودباری است به سراة، و گویند بلدی است از بلاد هذیل، و نیز گویند رودباری است منبع آن در کوه بنی صاهله و در ملکان جاری است . (معجم البلدان ). موضعی است به سراة، یا رودباری است، و یا کوهی . (منتهی الارب ).<br /></font></div>'),
(174850, 'ضیمران', '<span class=\"hlight\">ضیمران .</span> <font color=\"DarkGreen\"><b>[ ض َ م ُ <span class=\"hlight\" dir=\"rtl\">/</span> ض َ م َ ]</font></b> (ع اِ) ضومران . ضومیران . (ابن البیطار). ضمیران . ریحان دشتی . نوعی از ریحان . نوعی است از ریحان دشتی . (منتخب اللغات ). ریحان فارسی . (منتهی الارب ). گیاهی است که شاه اسپرغم گویند. شاهسفرم . (مفاتیح ). شاه اسپرغم، یعنی بوستان افروز . (دهار). شاهسپرم . شاسپرم . (مهذب الاسماء). شاهسفرم است و بادروج را نیز نامند. (فهرست مخزن الادویه ). تفلیسی . گل بستان افروز. نازبو. (غیاث ). حبق الماء . پودنه ٔ لب جوی . پودنه ٔ جویباری . (ابن البیطار). پونه . فودنج النهری . کازیمیرسکی گوید: معنی این کلمه درست معین نیست، گیاهی است خوشبوی از جنس شاهسپرم . در عرب شاهسپرم را ضمیران گویند. ارجانی گوید که شاهسپرم گرم و خشک است در یک درجه و تخم او اسهال صفرایی را تسکین دهد، و طریق علاج او آن است که تخم او را بریان کنند و با آب سرد بکار برند. (ترجمه ٔ صیدنه ٔ ابوریحان ). صاحب اختیارات بدیعی گوید: آن را ضمیران نیز گویند و شاه اسفرم شیرازی خوانند، آن سبز بود نه چون کریانی (؟). صاحب جامع گوید فودنج جویی است و سهو کرده است، طبیعت وی گرم و خشک بود در دوم، و گویند سرد بود، محرورمزاج را نافع بود خاصه چون گلاب بر وی زنند، و بر جائی که سوخته باشد ضماد کنند نافعبود و قلاع را نافع بود. (اختیارات بدیعی ). ضمیران . قیل انه الفوتنج . (تذکره ٔ ضریر انطاکی ) <span class=\"hlight\">:</span> <br />بستد <font color=\"DarkGreen\"><b>[ زمستان ]</font></b> عمامه های خزسبز ضیمران <br />بشکست حقه های زر و درّ میوه دار.<br /> <font color=\"Red\">منوچهری .</font><br />از ارغوان کمر کنم از ضیمران زره <br />از نارون پیاده و از ناروان سوار.<br /> <font color=\"Red\">منوچهری .</font><br />بوستان افروز پیش ضیمران <br />چون نزاری پیش روی فربهی .<br /> <font color=\"Red\">منوچهری .</font><br />نه با رنگ او بایدت رنگ گل <br />نه با بوی او نرگس و ضیمران .<br /> <font color=\"Red\">منوچهری .</font><br />ز بان و ارغوان و اقحوان و ضیمران نو<br />جهان گشته ست از خوشی بسان لات و العزی .<br /> <font color=\"Red\">منوچهری .</font><br />مخایل سروری بکودکی زو بتافت <br />چو بر چمن شد دو برگ بوی دهد ضیمران .<br /> <font color=\"Red\">مسعودسعد.</font><br />شود بنعت سر زلف ضیمران صفتش <br />ببوستان دلم رُسته ضیمران سخن .<br /> <font color=\"Red\">سوزنی .</font><br />موی او گشته ز آفات جهان چون نسترن <br />روی او گشته ز احداث زمان چون ضیمران .<br /> <font color=\"Red\">وطواط.</font><br />گر سنگ پذیرد آب جودش <br />زآتش زنه ضیمران ببینم .<br /> <font color=\"Red\">خاقانی .</font><br />گرچه در غربت ز بی آبان شکسته خاطرم <br />زآتش خاطر به آبان ضیمران آورده ام .<br /> <font color=\"Red\">خاقانی .</font><br />جائی است ضیمران ضمیر مرا چمن <br />کَارواح قدس جز طرف آن چمن نیند.<br /> <font color=\"Red\">خاقانی .</font><br />گوئیا من نیم من آنکه بدم <br />خار را ضیمران همی یابم .<br /> <font color=\"Red\">عطار.</font><br />جز همان میلی که دارد سوی آن <br />خاصه در وقت بهار و ضیمران .<br /> <font color=\"Red\">مولوی .</font><br />تو که گرد زعفرانی، زعفران <br />باش و آمیزش مکن با ضیمران .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(174851, 'ضیمرن', '<span class=\"hlight\">ضیمرن .</span> <font color=\"DarkGreen\"><b>[ ض َ م َ رَ <span class=\"hlight\" dir=\"rtl\">/</span> ض َ م ُ رَ ]</font></b> (اِ) ضومران . ضیمران . ریحان دشتی یا فارسی است . (آنندراج ).<br /></font></div>'),
(174852, 'ضین', '<span class=\"hlight\">ضین .</span> (اِخ ) کوهی است بزرگ به صنعاء. (منتهی الارب ). کوهی است به یمن . (معجم البلدان ).<br /></font></div>'),
(174853, 'ضیهب', '<span class=\"hlight\">ضیهب .</span> <font color=\"DarkGreen\"><b>[ ض َ هََ ]</font></b> (ع اِ) هر جای تفسان به آفتاب که گوشت بر آن بریان توانند ساخت . (منتهی الارب ).<br /></font></div>'),
(174854, 'ضیوج', '<span class=\"hlight\">ضیوج .</span> <font color=\"DarkGreen\"><b>[ ض ُ ]</font></b> (ع مص ) چسبیدن . میل کردن . (منتهی الارب ).<br /></font></div>'),
(174855, 'ضیور', '<span class=\"hlight\">ضیور.</span><font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع اِمص ) حاجتمندی به چیزی . (منتهی الارب ).<br /></font></div>'),
(174856, 'ضیوف', '<span class=\"hlight\">ضیوف .</span> <font color=\"DarkGreen\"><b>[ ض ُ]</font></b> (ع اِ) ج ِ ضیف . (منتهی الارب ). رجوع به ضیف شود.<br /></font></div>'),
(174857, 'ضیوم', '<span class=\"hlight\">ضیوم .</span> <font color=\"DarkGreen\"><b>[ ض ُ ]</font></b> (ع اِ) ج ِ ضَیم . (منتهی الارب ). رجوع به ضیم شود.<br /></font></div>'),
(174858, 'ضیون', '<span class=\"hlight\">ضیون .</span> <font color=\"DarkGreen\"><b>[ ض َی ْ وَ ]</font></b> (ع اِ) گربه ٔ نر. (منتهی الارب ) (فهرست مخزن الادویه ) (منتخب اللغات ). گربه ٔ دشتی . (دهار) (مهذب الاسماء). گربه ٔ برّی . ج، ضَیاوِن .<br /></font></div>'),
(174859, 'ضیک', '<span class=\"hlight\">ضیک .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (ع مص ) گشاده و متفرق انداختن شتر پای خود را از سختی گرما و قادرنبودن بفراهم آوردن ران خود را بر پستان . <BR><font color=\"Blue\">◄</font> خشم گرفتن بر کسی و خشمناک شدن . (منتهی الارب ).<br /></font></div>'),
(174860, 'ضیک', '<span class=\"hlight\">ضیک .</span> <font color=\"DarkGreen\"><b>[ ض ُی ْ ی َ ]</font></b> (ع ص، اِ) ج ِ ضائک . (منتهی الارب ).<br /></font></div>'),
(174861, 'ضیکان', '<span class=\"hlight\">ضیکان .</span> <font color=\"DarkGreen\"><b>[ ض َ ی َ ]</font></b> (ع مص ) نوعی از رفتار مرد فربه ران و آن حرکت دادن دوش و گشاده داشتن هر دو زانو است در رفتن . (منتهی الارب ).<br /></font></div>'),
(174862, 'ضیکل', '<span class=\"hlight\">ضیکل .</span> <font color=\"DarkGreen\"><b>[ ض َ ک َ ]</font></b> (ع ص ) کلان جثه ٔ فربه پرگوشت . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> مرد برهنه . (مهذب الاسماء). برهنه ٔ از فقر، یا عام است . <BR><font color=\"Blue\">◄</font> نیازمند. محتاج . ج، ضیاکل، ضیاکلة. (منتهی الارب ).<br /></font></div>'),
(174863, 'ضییم', '<span class=\"hlight\">ضییم .</span> <font color=\"DarkGreen\"><b>[ ض ُ ی َی ْ ]</font></b> (اِخ )ابن ملیح فهمی . از دلاوران عرب است . (منتهی الارب ).<br /></font></div>');
